/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230703-9","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"文教委員会","time":"午前１０時００分～午後 ０時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"教育職員の給与に関する条例の一部を改正する条例、(3)第４６号議案、学校教育職員の旅費に関する条例の一部を改正する条例、(4)第４７号議案…","agenda":"教育職員の給与に関する条例の一部を改正する条例、(3)第４６号議案、学校教育職員の旅費に関する条例の一部を改正する条例、(4)第４７号議案…","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"東京都が雇用している教員のほうの扶養手当の担保はどうなっているのか伺いたいのが一つと、それと、一言で言うと何のことなのか伺います。こうした異性パートナーと同性パートナーとの差というのですか、品川区と関わる民間の子ども・教育施設に広げるというのですか、いかがか尋ねました。","respondent":"中谷指導課長","answer":"最初の２つのご質問に答えさせていただければと思います。こちらを加えまして、規則としまして、死亡手当も含めて、旅費としております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望にします。もう少し、一言、分かりやすく旅費とは何ぞやというのを教えていただきたいです。","respondent":"中谷指導課長","answer":"扶養親族等を移転しない場合があるかと思うのですが、その場合は、規定する額の２分の１に相当する額を移転料として支給することになっています。食卓料、１２歳以上の者については職員相当の３分の２…","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"そのことで、パートナーシップ関係にあったとしても、カミングアウトを望まない方はいらっしゃると思います。新旧対照表の学校教育職員の給与に関する条例の第１４条で、そういったところでの担保というのはあるのか、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"この制度がご自身にとって、とてもいいものだということを分かっていただけた場合には、都のほうに証明書を発行してもらうと。その手続をしていただければ、この辺りが私たちとしては一番重要なところになってくるのかなと考えています。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それは要望も兼ねて、もし何かご意見があれば、言ってほしいと求めました。なぜ改正になったのかという中で、どういういきさつなのかというのを確認させてください。","respondent":"中谷指導課長","answer":"こういった申出があったときには、そのほかもそうですけれども、全て個別的に対応しますので、その辺りはご安心いただきたいと考えています。この制度を活用するに当たって、その違いによる不利益はないというところを判断した中で、このような選択になっていると認識しておりま…","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"競争してほしいというわけではないですけれども、このことのみならず、その他の場面で遭遇してくるのかなと。これは要望で終わります。","respondent":"中谷指導課長","answer":"教育委員会としての役割というところは、やはり人権意識をしっかり高めていくというところが使命だと考えています。その意味でも、人権教育の観点から、特に市民科でしっかり充実した取組が展開できるようにしてまいりたいと思います。","id":"exchange-005"}]},{"id":"topic-02","title":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このタイミングで補正に計上した理由があれば伺いたいのと、なぜ今年度は１万円で、これは来年度以降も継続する事業なのかというのを伺います。伺います。","respondent":"染谷子ども家庭支援センター長、石井保育支援課長","answer":"金額の上乗せは、本年度から事業の実施をすることが上乗せで補助を受ける条件となっておりまして、６月の補正で対応させていただいたものです。今後の実施の部分につきましては… 児童の安全確保支援事業に関する置き去り、見失い等の事故防止対策のご質問です。ドアセンサー等の設置についても費用補助の対象としていますので、こういったことで安全対策に対する補助を進めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今言ったような機器というのは、例えば区立保育園での導入状況はどうなっているか、もし分かればお伺いしたいと思います。１枚目の資料と参考資料についてなのですが、「等」について伺いたいのと、伺います。","respondent":"石井保育支援課長、立木保育課長、今井保育教育運営担当課長、中谷指導課長","answer":"ヒアリングを実施したところ、認可保育所では約７割程度の保育園が活用したいと考えております。新たに検討する施設があることも十分想定されますの… 先ほど紹介がありましたような機器に関しましては、区立保育園では特に今のところ使っているようなことはございません。… 例えば午睡中の突然死を防止するためのベビーセンサーの設置ですとか、あと、そういったところを想定していると伺っているところです。 特に協議会のところで…","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"部活動をやっている方は、部活動ですごく充実しているという実感があるわけですから、その当事者の声を協議会に入れないでどうするのだと。それは子どもの権利条約の観点でもあるので、そこら辺、ぜひ入れるべきだと思うのですけれども、お考えを伺いたいと思います。","respondent":"立木保育課長、中谷指導課長","answer":"例えば設置に時間がかかって午睡の時間が短くなってしまうとか、あとは、やはり人が確認することが一番であると。いいものがあれば導入したいと考えていますが、区立の場合は今のところその導入効果がというようなことで… これをやはり引き続きもっと拡充していくための在り方というところを検討していきたいと思います。最後の、協議会にお子さんの声を入れるということについては、ぜひ検討していきたいと思っています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"部活動のほうは、なるほど、よく分かりましたけれども、最後に１つだけ質問というか、これで終わりにします。ですから、そこら辺についてお考えがありましたら伺って、終わりにしたいと思います。","respondent":"中谷指導課長","answer":"今、ラグビーを小学校５年生から９年生まで活動していただくときに、ラグビーフットボール協会にヒアリングしています。試合については、これに合わせまして、いらしてくださったお子さんの学年に応じたメニューが展開できるように工夫してまいりたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"何を要望しているか分からない方に対して、どう支援していくのかというお考えがあれば、お考えをほしいと求めました。東京都の設置率が５０.６％ということでありますが、園バスが２６台あるとお聞きしていますが、お伺いしたいと思います。","respondent":"染谷子ども家庭支援センター長、石井保育支援課長、中谷指導課長","answer":"もう１点、先行して実施している区の状況を確認しておりますと、アンケートの未回答者が大体５％ぐらいだと聞いております。その５％のうち… なので、率にしますと約４割程度の設置率となっています。それまでには設置できるように働きかけてまいりたいのですが、設置事業者の繁忙の状況ですとか… お子さんに加えまして、指導者の先生におかれましても、こういったけがに対応できる保険料を込みで組ませていただいているところです。…","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"こちらは要望でお願いいたします。学校の部活動地域移行のことに関しましては、こちらは保険料も含まれての予算ということなので、こちらも引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、第１子、第２子、第３子などの記述があるのですが、第２子、第３子の定義を教えてほしいと求めました。地域ということで、ぜひ人材を確保していただきたいなと思いますが、その辺のご意見を説明を求めました。","respondent":"染谷子ども家庭支援センター長、中谷指導課長","answer":"もう１点、そういった対応が進められればというところを目的に、事業のほう進めさせていただければと考えております。第２子、第３子の定義ですけれども… その意味で、協議会がとても大事な場になるかなと考えています。２つ目のご質問としまして、教員の３割が指導していきたいという回答をしているのですけれども、今年度は特に注視していきたいと考えています。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"うちはちょうど１歳の子どもが誕生日を今月迎えて、来ているのかどうか確認していないのであれですけれども、そういうのがあるので。第３子の定義ですけれども、いわゆる戸籍上というのでしょうか、そういった部分に関して取り組んでいってほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"子ども家庭支援センターにおいて家事用品購入支援事業をやらせていただいた際に、きちんと対応できるように事業者と相談していきたいというのと、なるべく使い勝手がいいような形でやらせていただければと考えております。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは小さいところの確認と要望なのですけれども、東京都の専用サイトを使った電子クーポンみたいなのとはまた違ったところということですよね。クーポンがどういうあれなのか聞かせていただきたいのと、対象施設は限定しているのか、そこを聞かせてください。","respondent":"染谷子ども家庭支援センター長、立木保育課長","answer":"ギフトのサイトの考え方ですけれども、例えば都のサイトの共同利用といったことは想定していないということで、あくまで区のほうで構築するようにという話が来ているところです。 今回の安全確保支援事業の対象は、区立保育園も含んでおります。そういったところを考えた上で、区立がその体制をとっている中で有効に活用できるものがあれば、それは積極的に入れていきたいと考えています。","id":"exchange-014"},{"speaker":"せお委員","kind":"提案","question":"区立も、私も今まで子どもの事故のことで様々提案させていただいたのですけれども、ぜひ検証はお願いしたいなと思っています。国のマニュアルとかも結構丁寧に出ていると思うので、そういったところも含めて、一緒に考えていってほしいなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０月から活動を実施したい旨の記載がありますけれども、あらかじめ競技会場というのですか、教えてほしいと求めました。初歩的な質問になってしまうかもしれませんが、サッカーがないというのはどういうことなのか、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"前年度に各学校の校長から、１校１取組以上の地域連携をやっていこうということで、学校が選んだものになっております。たまたまなかったということで、何か、やらないとかということではないということは申し上げたいと考えています。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"会場のことなのですけれども、区としては、今、この辺を考えているとか、そういう主だったところというのがあれば教えていただきたい。その会議体の中で示していくのか、そういうのがある程度お考えがあるのであれば、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"会場につきましては、やはり一番いいのは、お子さんから近いところでなじみがあるという意味では、学校は一つの選択肢になるかなと考えております。どういった場所でやっていくかといった決定になっていくかなと考えていますので、それをもって…","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"進めていっていただきたいと思うので、そういう指導団体というのですか、それはどのようなものを想定しているのでしょうかということが２つ目です。中学校の名前とかが２つ載っていたりしているのですが、そのグループというのですか、それを教えてほしいと求めました。","respondent":"中谷指導課長","answer":"何がうまくいっているか、どういったところが課題なのかといったところも情報連携させてもらいながら、品川区としても考えていきたいと考えています。そして小学校３１校全てにご案内をかけていく予定ですので…","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後に、これは要望というか、それについて一つだけ。それができるかどうかというところが、教育委員会のほうでかなり力を入れていただきたいと思うのですが、そこのところを最後にお願いします。","respondent":"中谷指導課長","answer":"ご指摘いただいた各学校の取組、現在は、今こちらにご覧いただいているような取組からスタートしたというところになっておりますが、こちらも増えていくような取組として、教育委員会として支援していきたいと考えています。","id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ただ、補助的にこういうものを使って防いでいくという考え方は貫いていただきたいのですが、同じ気持ちですよねということを確認させてください。そういうこともどういうふうに、減っていく方向であるべきだと思うのですが、その辺についてはいかがか尋ねました。","respondent":"石井保育支援課長","answer":"現場の保育士がきちんとマニュアルに沿って安全を確認すること、これが一番であるという認識は我々も持ってあります。気をつけるような形で呼びかけをしているところでもありますので、様々な機会を捉えて、事故防止の取組を行っていきたいなと考えています。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それから、２校でしたか、あえて今やっているもの以外にというアンケート設定にしたのはどういうことなのかなというのを伺いたいと思います。会派の中でもぜひ確認してきてくれということで託されてきましたので、それにしてもどういうふうに、お答えほしいと求めました。","respondent":"中谷指導課長","answer":"２つ目の質問としまして、人工芝があるところとかというような、その辺りを実際にできる施設としっかり調整しながら決めていきたいと考えています。教員であったり…","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"だから、やはり中学生当事者が部活動に何を求めているかということをしっかり確認して、地域移行を進めていっていただきたいなと思っています。最後、これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成ですが、児童福祉費のほうは、いずれも児童の安全対策、孤立化防止など、子育て支援につながる内容です。現在の部活のメリットを維持しながら検討を進めてほしいと、改めて要望して、賛成とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-03","title":"第４４号議案、品川区立幼稚園条例等の一部を改正する条例","agenda":"第４４号議案、品川区立幼稚園条例等の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれ文言整理だと思うのですけれども、担当大臣の表記が変わっていますが、このことで、区として条例を通して提供する事業が変わるとか、そういったことがあるのかないのか、それぞれ伺いたいなと思います。","respondent":"石井保育支援課長","answer":"今ご質問ございました、今回、担当大臣が替わることによって、事業の内容等が変更になることはございません。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認したいのですけれども、改正する条例が１２ありまして、ここで品川区が持っている区立の、いわゆる名称ぷりすくーるですが、品川区立就学前乳幼児教育施設条例がどうなるかというのがないのですけれども、そこについてはどういう状況なのか尋ねました。","respondent":"今井保育教育運営担当課長","answer":"ぷりすくーるの条例もありますけれども、今回の条例改正の中には、ぷりすくーるの条例改正は含まないと判断させていただいたものです。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"関わりがないからここの１２の中に入っていないということですか。一つは保育部門があって、もう一つはいわゆる通称幼稚園があるのですけれども、そこに変更がないということでよろしいか尋ねました。","respondent":"今井保育教育運営担当課長、立木保育課長","answer":"今、提案しています条例改正の内容に基づきまして、ぷりすくーるの条例の中で改正する部分というのは、ないということで所管として判断させていただいているものです。 今回の国の法律改正に伴う条文改正と突き合わせた結果、ぷりすくーるの関係の条例に関しましては、該当する条文、当たっているものがないということで、今回は改正の必要がないです。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、３番目にある品川区保育の実施等に関する条例が変わるので、あえて断る必要はないということですか。ぷりすくーるの条例を変える必要がないということでよろしいか尋ねました。","respondent":"今井保育教育運営担当課長","answer":"失礼いたしました。委員のおっしゃるとおりでございまして、ぷりすくーるの条例については、今回は改正の必要がないということで判断させていただいたものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"かつ、子育ての自己責任・家庭責任を求めかねない、家庭という文言をあえて入れたと。対応する条例の条ずれや項ずれなどの文言整理なので、実質的な区民サービスへの変更や影響はないということで、賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２つ目が、検証を求める質問がありましたけれども、報告書以上でもそれ以下でもなかったということなのです。ここでも１点お伺いしたいのが、以上２点、改めて確認させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"意見","question":"学校給食の無償化で、未納の方がいらっしゃって、学校が徴収するという話だったのですけれども、現時点でどれぐらいの未納の金額があり、どのくらいの人数がいるかということと、今後、督促を具体的にどういうふうにしていくのかということをお尋ねしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません。これも西本議員だと思うのですが、どういうことがクリアされてそちらの小学校で進めていこうということになったのかということをお尋ねしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":42798,"voices":154}},{"id":"r05-20230703-5","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"総務委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"工事に際して、工期や工法についてどのような工夫をしようとしているのか、その点を確認させてほしいと求めました。様々対応が盛り込まれているとは以前から伺っておりますけれども、熱中症対策について、全般的な対応策をご説明ほしいと求めました。","respondent":"小林施設整備課長","answer":"１点目ですが、特別養護老人ホームを運営しながら対応する工夫という点ですけれども、旧第一日野小学校の跡地に仮移転いたします。そういったところで工事騒音の低減であったり、あるいは工事エリアの明確な分離というものを図る予定で計画のほうをしております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"特別養護老人ホームについては、居ながら工事となりますので、運営者と密に連絡を取って進めてほしいと求めました。２次下請、皆さんの健康がしっかり保障されるように、しっかり連携を取っていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、ここの冒頭で聞いておきます。全てべったりというか、少し掛け持ちでも日にちが分かれればどうなど、その辺の実態というものをどう捉えているかというところだけ教えてほしい。","respondent":"佐藤（聡）経理課長","answer":"今ほど委員のご指摘があったところは、今回のこの資料の電気設備工事の辞退理由のところ、配置予定技術者の配置が困難というところかと思います。そういった声を聴きながら、国の制度とも絡むところですので、今後とも研究していきたいと考えております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"現在のものは平成９年２月にできたと記載されていますけれども、今回、大規模改修工事に至った根本的な理由というものは何なのでしょうか。それで、実際年数的に、本来ならまだ大規模改修に至るまでにはいかないと思われるのですが、その辺について少し説明を求めました。","respondent":"小林施設整備課長","answer":"築年数からいくと大体２５年というところでございまして、大体耐用年数からいきますと、ものによっては１５年から２５年ぐらいが更新時期です。当然ながら２５年で耐力が落ちるものではございませんが、内装材だったり…","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"やはり工法ですか、そのような構造に変えていくべきではないかと思うのですけれども、もうやむを得ないということなのでしょうか。説明を求めました。","respondent":"小林施設整備課長","answer":"休館ができない施設ですので、今回、そのタイミングと併せて大規模改修につながったところです。それから工事を進めていくところですので、なるべくコストがかからないような工夫のほう、今後もしていきたいと考えております。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"新しく変わることなどがありましたら教えていただきたいということと、何かいろいろな方法などを考えていらっしゃるのかなと思いまして、その辺をお聞かせほしいと求めました。","respondent":"小林施設整備課長","answer":"災害時ＢＣＰの対応ですが、概要等にも記載されておりますように、今回太陽光発電のほうを設置しています。既存の屋上のほうに設置されておりますが、約倍程度の発電能力があるということで、一定程度災害時に対しても有効ではないかと考えております。","id":"exchange-006"}]},{"id":"topic-02","title":"第６２号議案、片袖机他の買入れ","agenda":"第６２号議案、片袖机他の買入れ","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"学校運営用品・製品一式ということですけれども、これまではあまりこのような議案を見た覚えがなくて、今までの契約の仕方と今回とどのように変えたのか、その狙いや目的についてもご説明ほしいと求めました。","respondent":"柏木学務課長","answer":"物品としては同じものを購入していたのですけれども、各教室ごとですとか、そのような形で分けて契約をさせていただいておりました。やはり同じ物品については同じ契約の中でするべきだろうというお話もございまして、今回教職員用で使う物品について…","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"今まで別々だったものを、今回まとめてということですけれども、それについての効果をどのように評価しているのかという点を改めて伺います。物品の引取りとか、把握とか、どのように進められたのかも併せて伺いたいです。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"１つの契約で済ますというところになると、我々としても、一定の金額について減額の好効果があると考えております。幾らぐらい減額になったかというところは、なかなか難しいところではありますが… こちらのほうで、現地で実際に現物を見て、必要なもの等の把握をしています。今回契約する前にも最終的な確認ということで担当者が学校のほうに行きまして、学校の職員と一緒に必要なものを精査しているという状況になります。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"それに対して、そこの部分はもう１回、言えるようでしたらおっしゃっていただきたいなと思います。もう１点ですけれども、数としては児童が使うものが多くなると思うのですけれども、この辺りはどのように購入されているのかお伺いいたします。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"先ほどの効果のところですけれども、物品が同様であれば、金額については比較することが可能かと思います。そういったところもありますので、今後も物品の入札金額については、そういった視点も持って研究していきたいと考えています。 移設できないもの、また、新たに買わなければいけないものを契約として出している形になります。毎年年度末に、老朽取替えと児童生徒用の増加分の予算を措置していますので、そちらのほうで対応しています。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問・要望","question":"今回それが適切かどうかということは特に申し上げませんけれども、使えるものはできるだけ使っていただくということでお願いしたいなと思います。以上、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"それをどうか。今もあるのだけれども、それをどうしていくのだということだって考えられるので、どうされていくのかなという考えをお持ちなのかと聞きたいです。","respondent":"佐藤（聡）経理課長","answer":"あるいは事業者の育成という面からも、非常に重要だと考えておりますので、そういったところは引き続きやっていきたいと思います。こちらからは申し上げないところですので、そういった健全な価格競争の中で図られるものだというふうに考えております。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"予定価格を出すといったら、どういう積算で予定、だからこの物品の金額は何％とすぐ出てきてしまうではないですか。その辺のやり方を教えてほしいです。","respondent":"佐藤（聡）経理課長","answer":"入札のやり方というところですけれども、いわゆる予定価格についてはお出ししているところです。予定価格の取り方ですけれども、契約担当部署、経理課のほうで出しております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと参考のためにお聞きしたいのですが、今回のこの契約は、大体何が何台でこのような金額が出たのかということを教えてください。それはあれですか、それについて、もし分かれば説明を求めました。","respondent":"佐藤（聡）経理課長、柏木学務課長","answer":"前段の何が何台というところですけれども、資料の５４ページのところの、片袖机５４台、あるいは少し飛びまして、会議用テーブル４６脚というところが主な内容です。 基本は再利用ということを考えてございまして、そのような形で、使うところがあればそちらのほうで活用すると。その後、その中でほかの所管で使うものがあれば使用していただいて…","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと１点だけ、要望ですが、今小学校、中学校でタブレットを使っていますよね。その辺も、もし今後検討していただければありがたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"塚本副委員長","kind":"確認","question":"一括で同じものは同じ、１点ちょっと確認ですが、これは今回のケースに関してはそのような判断をしてそうしました。制度化されて、きちんと今後はこのようなことになるのだよねということでのやり方を、手続の手法として変えたということなのかを確認させてください。","respondent":"柏木学務課長","answer":"今回限りではなくて、今後につきましても、まとめられるものはまとめた形で契約していこうということで、内部では確認を取って、すみません、ちょっと文書等では確認していませんけれども、そのようなことでやっていくということでの確認は取れているものです。","id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"そのようなことでいうと、何かきちんとした客観性や明文化したものがあったほうがいいのではないかなと思うのですが、その辺まで至っていないところの話はどうしてかということを最後にお聞きしたい。","respondent":"佐藤（聡）経理課長","answer":"この物品購入の、特に出ますけれども、そういったところはこれまでも経理課のほうで調整していたところです。所管課と経理課のほうで調整してやってまいりますので、そういった中で、これからも合理的な調達を図っていきたいと考えています。","id":"exchange-016"}]},{"id":"topic-03","title":"第５４号議案、総合体育館および日野学園空調設備改修工事請負契約","agenda":"第５４号議案、総合体育館および日野学園空調設備改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"子どもたちの社会資本に対する設備なわけだから、更新するわけだから、それ相当の額というものはきちんともらえているのですか。どれぐらいの金額を、実際区としてはもらえるのか尋ねました。","respondent":"森学校施設担当課長","answer":"今のご質問ですけれども、大体国、都からの補助金はおよそ１０％程度ということで、ほぼほぼ区の予算を使って改築をするということになってあります。要望といたしまして、国、都のほうには、もっと補助金を上げてほしいというように上げてはあります。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"だから今後、やはり２３区もしっかり心を一つにして、都や国にしっかりお金を出すようにしてほしいと私は思うのです。１０％では今後２３区でも、やはりほかの自治体でも大変だと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"逆に物価が下がったときに、今度逆スライド条項というものもやはりつくるべきではないかなと思うのです。私は不思議だと思うのですが、その辺、もし何かご見解がありましたら説明を求めました。","respondent":"佐藤（聡）経理課長","answer":"今まで、およそ１０年ほどですか、この条項を使いまして、適宜対応してきたところです。今申し上げた第２５条の中身は、国のほうも検討するということかなとは考えますけれども、そういったところを注視しながら考えていきたいと思います。","id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"今後、どのような方向性に対して対応するか、私は見ていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"ちょっと１点だけ伺いたいのですけれども、専決処分の日が令和５年４月２８日ということですが、当初比で２.６６％増ということです。これが２.７７％になるのか、２.８８％になるのか、判断の仕方をお聞かせいただけないか尋ねました。","respondent":"森学校施設担当課長","answer":"インフレスライドの基準日のお話かと思うのですけれども、基本的には区と業者で話し合って決めております。上がっていく基調の場合もあるのですけれども、そのバランスを業者と区のほうで見ながら、いつにしましょうというように決めているところです。","id":"exchange-021"}]},{"id":"topic-05","title":"専決処分の報告について（報告第２４号）","agenda":"専決処分の報告について（報告第２４号）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回のこの３つの給与条例の改正に伴って、仕事をしていく上で差はないということでよいのか、確認させてほしいと求めました。３点目、任命権者が証明書等により確認できた関係と書いてあるのですけれども、ご説明ほしいと求めました。","respondent":"崎村人事課長","answer":"全国の実施状況について、ほかの自治体でやっているところはちょっと認知しているところにないというところでお答えさせていただければと思います。証明書、それをもって区のほうに申請をいただいたときに任命権者がそれを認めるといった、そういった規定になっているところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"このようなものをご検討いただけないでしょうかというような、力強く進めていってほしいと求めましたが、いかがでしょうかということです。これを機に進めていただきたいと思うのですけれども、現状ではどうなのか、改めて伺いたいと思います。","respondent":"加島人権啓発課長","answer":"１点目にご質問いただきました、改めて性の多様性についてご理解、ご協力をいただけるようにということのお願いをしてまいりました。子どもに関する困り事にも対応していること、広域的な行政サービスに対応していること、都制度が現在区にとって利便性が高いと考え。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"グローバルな企業というのでしょうか、やはり各国の、給与や休暇の処遇について改善を進めていったというところは聞いたことがあります。企業との交流の機会の際には、こうした視点を広げていただけたらと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問・要望","question":"少しお伺いしたいのですけれども、どうもあまり問題視していない、例えば類似のものでいったら事実婚があるかと思います。その宣誓の証明書を申請するときに、事実婚と同様な、この点についてはどのように審査されるのか尋ねました。","respondent":"崎村人事課長","answer":"今ご説明させていただいたのは、パートナーシップ宣誓制度の証明書、それを必要とするといったお話をさせていただきました。そういった不正がないよう、申請に対して不正がないようにというところは、人事課としてもしっかりと取り組んでいるところです。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"確認ですけれども、その後の実態的な審査というものはまた別にやられるということでよろしいかというところを、確認させてほしいと求めました。今回の改正案の等の部分に、こうした自治体が発行した証明書以外のものも含まれてくるのか、運用の部分をお伺いできればと思います。","respondent":"崎村人事課長","answer":"受給する相手方なのかというところはしっかりと調べるようにしておりますので、そこについては、しっかり人事課として取組んでまいります。そういった画面を見せることによって、中には今後出てくるのかなというところもございまして…","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いだけしておきます。それと東京都パートナーシップ宣誓制度があった４行ですけれども、ポジティブと性善説でやっていただきたいということだけお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"塚本副委員長","kind":"質問","question":"すみません。１点教えてほしいのですけれども、申請するというのか、制度にはまっていくことができるのかどうかということをお尋ねしたいと思います。","respondent":"崎村人事課長","answer":"課長が、そういった状況にあるということの確認を取った上で申請をしていただくということに、今のところはなってあります。","id":"exchange-028"},{"speaker":"塚本副委員長","kind":"意見","question":"これから始まる制度でありますので、どうしてもそういった弊害のようなことが運用の中で出てくるところもあるかと思います。これは守秘義務というものはもちろん守られるべきものなので、その上でまた、そういったことについてもよく注意してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"今のところ、改めてそこの部分を、ではその情報をどこまで誰に渡していいのかというところを改めて周知徹底していただいたほうがいいと思います。改めてここのガイドラインを整理していただきたいなと思いますが、この点、最後。","respondent":"崎村人事課長","answer":"今回議決をいただいて、制度として運用していく際には、しっかりと後ほど管理職中心に周知をしていきたいと考えております。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"それはぜひそう進めていただきたいと思うのですけれども、離婚してもそのままの方もいらっしゃるし、それぞれの個人の尊厳を十分保障した仕組みとして進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どういうこと、これで私は本当に最善の配慮はしていただきたいけれども、ぜひそこの中でやっていっていただきたい。これだけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"澤田委員","kind":"質問・要望","question":"それが当たり前、そういう同性カップルだったりを当たり前として受け入れられるような環境づくりのほうにも、ぜひ力を入れていただきたいなという要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]},{"id":"topic-06","title":"第３７号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第３７号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明ありがとうございました。現状２類から５類に変わったことで、今あるのかないのか、そこのご説明をほしいと求めました。","respondent":"崎村人事課長","answer":"特例措置で定めている業務の内容については、５類感染症に移行されてからはございません。ＰＣＲ検査センターが区にも設置されましたけれども、ＰＣＲ検査を実施した際にその検体を運ぶ業務といったものは、現在行われていないところです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"現在は５類に変わったことで、コロナの感染状況については、今沖縄がまた増え始めていると。別の感染症がはやるのか、そこはもちろんよく分からないですが、十分な警戒はしていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]},{"id":"topic-07","title":"第４０号議案、職員の高齢者部分休業に関する条例","agenda":"第４０号議案、職員の高齢者部分休業に関する条例","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"それと、この際なので伺いたかったのですけれども、定年が引き上がるということは、職員の方にとってうれしいことなのですか。何というのですか、働かないと生活ができないという、ちょっと定年の引上げについてどのように考えているのか聞かせてもらえますか。","respondent":"崎村人事課長","answer":"確かにこれまでも定年後再任用職員として６５歳まで、年金と雇用の接続という観点で、希望する方は再任用職員として働いていらっしゃいました。以降６５歳まで再任用として働いていただけるという制度もありますので…","id":"exchange-036"}]},{"id":"topic-08","title":"第４１号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４１号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"森林環境税の導入ということですけれども、個人住民税均等割とした理由を伺いたいということと、それが入っていない理由はなぜか伺いたいと思います。安全対策というのでしょうか、交通安全対策というのですか、そこがどうなっているのか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、やはり累進課税を強化していく、この方法が必要だと思います。事故のないように、巻き込まれることのないように、対応については連携をしっかり取っていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけですが、今のキックボードですか、やはり我々運転している身からすると、非常に危険です。なぜこれを許可したのか、もう既に昨年３５人ほど死亡者が出ているということで、何か対策は取ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２点だけ伺います。これ区で出てきてどうです、これは一体どう捉えてどのような現実が起きているかということを理解されているのかなということを教えていただきたい。","respondent":"提坂税務課長、遠藤財政課長","answer":"〔同日後刻に「４,５９０万円」と答弁訂正あり〕具体的な活用予定としましては、その点に活用されるというように聞いてあります。税務課のほうとしては税をいただく立場ですが、それは全庁的に検討していく課題だと思ってあります。 令和４年度、令和５年度は、大体４,０００万円を超えるぐらいかなという形で、今動いてあります。現状、令和３年度まで公開させていただいていまして、そのような部分では木材を使った形で使わせていただいているというような状況です。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１回私も勉強しますが、いろいろなこういう造成だというような話になってきて、造成のお金がどうのこうのとか出てきてしまうのです。これは確かにいいのだけれども、優良住宅はいいのですが、これはもう１回私も勉強させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのほか今回の条例改正では、キックボードについては反対するものではありませんけれども、安全対策はしっかり進めていただきたい。軽自動車税のグリーン化特例の延長など、こうしたものは基本的には進めてほしいと求めましたが、全体としては反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]},{"id":"topic-09","title":"令和５年請願第５号 安保関連３文書・防衛財源確保法に反対する意見書提出に関する請願","agenda":"令和５年請願第５号 安保関連３文書・防衛財源確保法に反対する意見書提出に関する請願","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"その前に、１点だけ品川区に確認ですけれども、いわゆる安保３文書、反撃能力、５年間で４３兆円、ＧＤＰ比２％の軍事費増と。こうした流れは、非核平和都市品川宣言で掲げている恒久平和に反する事態だと私は思うのですが、品川区の認識だけ確認させてください。","respondent":"せりざわ委員長、勝亦総務課長","answer":"冒頭に説明したとおりでありますので、基本は委員間討議で行っていただければと思いますが、区としてご説明が特段あれば、ご意見をお願いします。 品川区としての非核平和に関してのことで、品川区として、そのような考え方で非核平和を進めていくという考え方です。今ご質問ありました防衛の関係の安保３文書等々につきましては、国で検討する課題かと存じます。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"品川区に、恒久平和に反する事態とは思わないのかと伺いましたが、結局、国が考えることで、区としては態度表明はないということだと思います。だから違うのだ、必要なのだという話を私は伺いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"国のほうでも岸田総理が話しているわけですから、この状況を見ますと、今回の意見書を提出することはふさわしくないと。そういう時宜と考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"意見","question":"出すべき話ではないし、区議会でどうという話ではないけれども、あくまでも私個人の見解を言います。だけれども、しっかり我々の国を守るには、今この状況に置かれている中で、私は、安保関連３文書はしっかり行っていくべきだと個人的には思っているとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"こういうテーマは国会でやるべきで、区議会でやるべきではないという意見がありましたけれども、区民から負託されている我々の大事な役割ではないか。ここから先は国で議論してくれというのは、とても残念な意見だと私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"この議会でやるのは違うと思っているから、さっきも何度も、私の個人的な見解を言うと。それは議員としてとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"区議会議員としてしっかりと議論するべきということは、区議会議員としては、区民を守るというところが最も重要なところかと思います。意見ですので、こうしたところを申し上げしますけれども、態度も表明するならば、本件請願については、不採択と私どもとしては考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"ですから、冒頭、抑止力では平和をつくれないと。それだけに、こういった軍事的な圧力を高める道は避けなければいけないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"意見","question":"中塚委員に誤解だけ解いてほしいのは、さっき、区議会議員の仕事はどこまでというのもあると。そこだけはよく理解してほしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"意見書を出してほしいという請願で、区議会で議論して意見書を出すという仕組みがあるわけだから、こうして議論していると思います。ぜひ、ご発言されていない各委員の意見を聞かせていただけたら伺いたいし、少なくとも戦争という惨禍を繰り返してはいけないと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"須貝委員","kind":"質問","question":"皆さんに負担をかけないようにして進んでいきますということを公言しているわけですから、それは、私は見守っていいのではないかと思います。政府の出方をしっかり見極めて、それでもし違う方向に行った場合には、我々も別の意見書を提出するということでいいのではないでしょうかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"議員がなられているわけですから、少し検討される際に考えていただきたいのが、防衛予算は必ずしも敵基地攻撃能力に限られているわけではない。私たちは区議ですから、区民の生命・安全を守っていくというのが重要かと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"澤田委員","kind":"質問","question":"不採択でお願いいたします。一部を取り上げて、区で議論する立場にないため、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"塚本副委員長","kind":"意見","question":"結論は不採択です。なされていくべきだし、必要な財源というのがどうしても必要であれば、我々は不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、態度に関しては、不採択でお願いしたいと思います。しっかりと日本をどう守っていくか、また区民をどう守っていくかというところは、提出しないということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、反対する意見書提出に賛成ということで、採択を求めたいと思います。罪のない民間人を殺すわけですから、こういうのを見たときに、不安だと思う国民の気持ちはよく分かります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"松本委員","kind":"質問・要望","question":"区民の方から国政について、区議会として要望を上げてほしいという話が出た場合には、積極的な議論があってもいいのかなと考えています。とはいえ、本件の中身については、私どもとは考え方が違うところですので、そこについては、不採択という意見を申し上げて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を出す、不採択です。特にこのことについては国の話だと思うので、私は、区議会の話ではないということだけは付け加えておきたいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"}]},{"id":"topic-10","title":"令和５年請願第９号 適格請求書等保存方式（インボイス制度）の実施延期を求める請願","agenda":"令和５年請願第９号 適格請求書等保存方式（インボイス制度）の実施延期を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど同様、私の意見を話して皆さんの意見も聞かせてほしいと求めましたが、まず、区に１点だけ伺います。インボイス実施延期を国に求める考えがあるのか、その議会の様子などは把握されているのか、そこだけ確認させてください。","respondent":"遠藤財政課長","answer":"それから税額を指示する、伝えるものだと認識していますので、こちらは国のほうで議論されると考えているところです。それから、ほかのところの議会の状況というところですが、私どもの方では、そのところまでは把握していないところです。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"国に対して中止を求めていただきたいのと、議会の議決状況なども、ぜひ注視していただけたらと思います。ここには実施中止を求めることと、私はそもそも反対ですから、せめて実施延期を求めるということは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"ですから、インボイスをやめて、何か別の制度で私は持っていくべきではないかと思います。インボイス制度の実施を延期するということですから、それが１年なのか２年なのか分かりませんが、私は待つべきだと考えます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"今回、延期・中止を求める方々の声があるというのも事実だと思うのですけれども、声優の岡本さんの会見とかは伺わせていただきました。本件については、また態度を先に表明しますけれども、私どもとしては不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"意見","question":"全てこれを今やっているので、これは必ずどちらとも、私はやるべき。そういう考えなので、請願は不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。理由としましては、インボイス制度は国としての政策であることから、区議会が決める権限はないですし、国で議論されるべきだからです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"塚本副委員長","kind":"意見","question":"そこから先３年間は、５０％控除ということでの経過措置もされている中で、これはやはり予定どおりすべきものと考えています。いろいろなこととかということで解決していくほうが、正論なのではないかと思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"大倉委員","kind":"意見","question":"費用の面とかも工夫しながら応援していってほしいと思っているものの、実際、もっとインボイスについて慎重な議論をしたほうがいいと考えています。もっと慎重な議論をしていくというのがいいだろうと考えていますので、態度については、趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は中止してほしいと思います。それは一言述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうしたらいいのだろうと悩んでいるならば、そういうことを国にしっかり要望して、国もそういう周知を徹底して動くことが私は大切だと思います。先ほどもありましたけれども、インボイス発行を求められない小さな会社もあるのですが、今回は国にしっかり言っていただきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ延期だけ求めて、それで終わらせるというのも、私は少し無責任なのかなと。それは言いっ放しになってしまうと考えていますので、私どもとしては、不採択と申し上げします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"大倉委員","kind":"意見","question":"趣旨採択ということだったのですが、もし態度を出さなくてはいけないということであれば、不採択でお願いしたいと思います。責任を持ってしっかりと、いつまでと決めることが必要だと思いますので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-11","title":"専決処分の報告について（報告第１９号）","agenda":"専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今の専決処分で、車に衝突のブザーといいますか、アイサイト、そういうのはつけてあるのか尋ねました。","respondent":"加島人権啓発課長","answer":"今、当課で管理しております庁有車につきましては、アイサイトはございません。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":63218,"voices":366}},{"id":"r05-20230704-6","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"区民委員会","time":"午前１０時００分～午前１０時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"令和５年度 文化センター等工事による休室・休館予定","agenda":"令和５年度 文化センター等工事による休室・休館予定","exchanges":[{"speaker":"山本委員","kind":"質問","question":"ちなみに、所管されている施設の中で、順次ＬＥＤ化をやっていらっしゃるということは、どれぐらいの進捗になっているのか尋ねました。","respondent":"篠田文化観光課長","answer":"こちらは、先ほど申し上げた施設整備課で全体の調整をしているもので、今、文化センター等で進んでいるところです。それから、きゅりあんに関しましては、全体のリニューアル工事もやってありますので、今回で全て終わるような形になってあります。","id":"exchange-001"}]},{"id":"topic-02","title":"デフスポーツ応援事業","agenda":"デフスポーツ応援事業","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"今年度、区内で強化合宿というのは、いつ頃とか場所というのが、もし決まっていれば教えていただきたいです。","respondent":"三井スポーツ推進課長","answer":"強化合宿の場所ということで、今回、日本ろう者サッカー協会から聞いていますのが、７月２８日から７月３０日で、天王洲公園サッカー場でやりまして、そのうち７月２９日については、区民の方に開放していただいているということで聞いております。","id":"exchange-002"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。もう１点だけ、どういった内容で、内容が決まっていればお教えいただけますか尋ねました。","respondent":"三井スポーツ推進課長","answer":"選手に対する質問コーナーとか、一緒にボールを蹴るとか、そういうことを予定しております。もう少し詳細については詰めていきたいと考えています。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"私もこういった交流会に参加したことがあるのですけれども、やはり代表の選手の方と、質問ですとか、一緒にプレーするというのは、本当にお子さんたちにいい体験の機会になると思いますので、よい交流会になるかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"事前申込不要だということで、これは一般区民の方も一緒だということだと思うのですけれども、区民の方にはどのように周知をされていくのか。品川区としては、たくさんの方に来ていただきたいというお考えなのか、その辺りを教えてほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"は、少年サッカー連盟などにも声をかけまして、実際にサッカーをやっているお子さんたちにも来ていただきたいと考えています。基本的に、なるべく多くの区民の方に来ていただきたいと考えていますが、なるべく広報しながわとＳＮＳ等を使って周知していければと考えています。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"意見","question":"多分そういうことで、たくさんの人に来てもらいたいということでハードルが下がっていると思いますので、ぜひ広報に力を入れていただいて。激突音というか、これはすごいスポーツだなと感じましたので、品川区でも多くの区民が実感できるような形で周知をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"観覧席の設置を考えているということで、どういう感じで天王洲公園サッカー場に、何人ぐらい入れる形のものにしていくのか。段々にしていくのか、そういうものは設置が可能なのかということを説明を求めました。","respondent":"三井スポーツ推進課長","answer":"それが難しいようですと、パイプ椅子とか、そういうものになってしまう可能性はありますが、一応それで考えております。そうすると、２００席から３００席程度かなと予定をしております。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"確認なのですけれども、（１）のトレーニングマッチ、その辺りはどのようになっているのかだけ確認をさせてください。スケジュールですとか、そういったところも、もしイメージがあれば確認させてください。","respondent":"三井スポーツ推進課長","answer":"デフスポーツの応援事業はこれで終わりませんで、デフリンピックの啓発ということで、１０月にイベントを予定しております。１０月のイベントの際に流せるようなことを考えておりますので、そのイベント前までには作成が終わるようにと考えております。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、様々、今後予定されているイベントですとか、そういう機会を捉えて積極的に発信をしていただきたいと考えています。今回、これから観覧席を設置するということで、その辺りの調整が終わり次第というところかと思うのですけれども、そこも確認させてください。","respondent":"三井スポーツ推進課長","answer":"障害をお持ちの方の受入れについては、これから日本ろう者サッカー協会ともよく話しながら考えていきたいと考えています。そういう方たちにもどのように来ていただけるかというのは日本ろう者サッカー協会と相談の上、広報できる範囲でしていきたいと考えています。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"ご覧になりたい方、ご興味ある方がなるべくご覧いただけるようにぜひ、現実的な観覧席等の部分もあると思いますので、日本ろう者サッカー協会とよくご相談いただいて進めていただきたいと思うのですけれども、その辺り、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"日本ろう者サッカー協会とそこはよく相談しながら進めていければと思います。区内には明晴学園もありますので、そちらとも連携が取れればいいなと思って、そちらも考えていければと思います。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、デフリンピックのデフの意味を教えていただけますか。","respondent":"三井スポーツ推進課長","answer":"デフは英語で、耳が聞こえない人とか、聞こえにくい人という意味があります。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"分かる範囲でいいのですけれども、デフリンピックにはどういう競技があるのか教えていただきたいです。今後、強化合宿を行うということで、サッカーという形になっていると思うのですけれども、まずそこまで伺います。","respondent":"三井スポーツ推進課長","answer":"デフリンピックの競技についてのご質問かと思われますが、サッカー以外ですと、デフリンピックの競技として決まっていますのが全２１競技あります。例えば、陸上、卓球、バレーボール、バスケットボール、ハンドボールなどがあります。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"子どもたちの参加とか、２０２５年にデフリンピックを行うということを契機に、この２年間やっていただきたいと思っているのです。その辺については、もう教育委員会と話していたりしているのかということも含めて答弁いただけますか。","respondent":"三井スポーツ推進課長","answer":"まだ教育委員会とは話せていないのですが、今年度は障害者支援課と、１０月にあるイベントなどの際に連携していければと思っています。東京都もデフリンピックには力を入れておりますので、東京都とも連携しながら、聴覚障害の理解促進については力を入れていければと考えていま…","id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"東京都があって、そこで各区がこうしてくださいというか、東京２０２０大会のときのような形になっていくのでしょうか。一番伺いたいのは、主体は東京都なのですかという確認をしたいので、その辺を。","respondent":"三井スポーツ推進課長","answer":"東京都とデフリンピックの関係性までは、すみません、不勉強で、現状、把握はできていませんが、東京都でも基本的には普及啓発に力を入れていくということで聞いております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"デフリンピックは、東京で開催することは決定しているのですよね。どこが主体でやっていくのか尋ねました。","respondent":"三井スポーツ推進課長","answer":"一般財団法人全日本ろうあ連盟スポーツ委員会というのがございまして、そこと東京都で一緒になってやっていくというのは聞いております。〔同日後刻に「一般財団法人全日本ろうあ連盟が主体となり、都が連携する」と答弁訂正あり〕","id":"exchange-015"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"今の時点で２泊３日というのは、これから８月、そのときのコロナの状況判断というのはしていかないといけないと思っているのです。相手先があるのですから、コロナ感染等に関してということも考えの中に入れていっていただきたいと、私は個人的に思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"特に１０月になった時点での状況になってくると思うのです。感染拡大した際にはそういう対応をしていくということで、ぜひお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"提案","question":"各委員から様々な視察の提案があったということが委員長から報告がありましたけれども、何のために行政視察に行くのかというところを確認した上で。先様のある話ですから、それはできないということになってしまいますので、粛々と議会事務局と調整を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"ですから、そうしたところというのは、現段階では想定が不可能であると私は考えています。必ずしも２泊３日ありきというところではない、そこを見失わずに、しっかりと判断していければいいかなというのが私の思いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"えのした委員","kind":"意見","question":"従前どおりになっていますので、２泊３日ありきというよりは、やはり行政視察の意味。それで、もともとのやり方に戻すということで、私はいいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"方面がどこかというよりは、事例がどういうものが学べるかというところが、まず大事かなと考えております。検討していく必要があると思いますので、そういった事例が視察できるということであれば、ぜひ進めていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"提案","question":"今のは私もそのとおりだと思うのですけれども、この前、期限までにということで、多分、各委員から幾つか提案があったと思うのですが、それを今、改めて申し上げたほうがいいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"どのような意見を述べるのがよろしいのでしょうか。あくつ委員のご発言を踏まえて、どう進めたらいいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"提案","question":"正副委員長のご判断にお任せしたいと思うのですけれども、それでよろしいですか。どういう意見を求めているのか、私も少し分からなかったのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"山本委員","kind":"提案","question":"そちらで私は異論がございません。ほかにも回れるというものが見つかりそうであれば、追加的にご提案をするのがいいのかなと思ったのですが、そういう理解でよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"せっかく、もし市役所とかに行くのであれば、そういうところも取り上げていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。学校プールの実施について、１点教えていただきたいのですが、これは実施できる学校をどのように選んでいらっしゃるのか尋ねました。","respondent":"三井スポーツ推進課長","answer":"こちらの資料に記載の７校に、第四日野小学校を加えた８校が開放の対象になっておりますが、こちらの７校となっております。","id":"exchange-027"},{"speaker":"山本委員","kind":"意見","question":"８校までというのは決まっているというか、教育委員会で決めていらっしゃるということなのですね。夏のプールは楽しいと思いますので、多くの子どもたちがエリアに偏ることなく利用できるように、今後ご検討いただけたらと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"えのした委員","kind":"質問","question":"一般質問でもありましたが、熱中症対策について、屋外水泳場、また学校プールともに、クーラーボックスの用意ですとか、お水、冷水機があるのか。監視員の方というのがどのぐらい配置されているのか、熱中症対策についてお伺いしたいと思います。","respondent":"三井スポーツ推進課長","answer":"個別にご説明させていただければと思いますが、監視員については基本的に入札で業者を選定しておりまして、監視員がいるような状態だと考えています。管理会社に依頼はしているところなのですが、こちらの詳細につきましてもお調べして…","id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認させてください。万が一インターネットが使えない状況の方等がいらっしゃった場合にはどのように対応されるのか、確認させてください。","respondent":"三井スポーツ推進課長","answer":"現在、予約システムはどうしてもインターネットを使うような形になってしまっておりますので、もしそういう声があるようでしたら、また今後検討させていただければと思います。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16461,"voices":84}},{"id":"r05-20230704-7","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"厚生委員会","time":"午前１０時００分～午後 ４時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"品川区立八潮南特別養護老人ホーム等の増改築","agenda":"品川区立八潮南特別養護老人ホーム等の増改築","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"ピッコロ、１日利用者数５名の定員になっているので、あと通える方の状況です。呼吸器ケア等されている方がここに通所可能なのかということを確認させていただきたいです。","respondent":"松山障害者支援課長","answer":"ピッコロですが、令和３年度から、定員５名から６名に変更しております。今現在も、そのように医療的ケアの方々が安心して通えるような施設にしていけるよう、丁寧に区としてはバックアップしていきたいと考えています。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問・要望","question":"定員を増やすだけではなくて、やはり内容や通える方の幅を広げるというところには、ぜひ取り組んでいただきたいなと考えています。そのほかの方々にも広く周知していただいて、その周知方法について、今後どのように検討しているかという点についても説明を求めました。","respondent":"東野福祉計画課長","answer":"説明会の周知方法ですが、住民の方へ掲示板等でのお知らせのほか、周辺の方につきましてはポスティングなどを考えているところです。既存の施設に入っている方々へも周知を行う予定でおりますので、そういった形で進めていきたいと考えています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今まで何があってどのような状況になっていたところにグラウンドが移設できることになったのかということを１つ教えてほしいと求めました。増築の中身についても教えていただきたいということと、特別養護老人ホームとしては何名増えるのかというところを教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"定員のほうは約１５０名ということで、増やしていきたいと。全体の定員を１００名から１５０名に増やす予定です。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これはぜひ残していただきたいなという思いがしているのですが、そこのところはちょっとどうなるのか、その辺の考え方も伺いたいと思います。それからあと、在宅介護支援センターが機能拡充となっているのですけれども、その機能拡充というものはどのような中身で拡充されるのかも伺います。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"どうしても建物ができる関係で、日陰になってしまうような部分もありますので、そういったところは一定程度の改修が必要と考えております。現在進めているのがユニット型で増築棟のほうは考えておりまして、そのような考えで… 私のほうからは、在宅介護支援センター等の機能拡充についてのご質問にお答えします。障害者の支援センターのほうも併設したときに移ってきたので、少しこの増改築を機会に、機能拡充と記載しています。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。個室ユニット型と多床室の割合、その辺ももう方向が出ているのであれば、ちょっとそれも教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"従来型個室のところが既存棟の３階、４階にありますので、そこの部分はできるだけ活かしていく形を取ろうと考えているところです。増築棟のところにユニット型のものを造っていくという考えです。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ残していただきたいということで、要望もさせてほしいと求めましたが、ちょっとその確認をお願いしたいと思います。それから、あと人員体制も、今は看護師３名ということですけれども、この２０名となると、その人員体制はどこまで拡充されるのかも伺います。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"個室のほうにつきましては、現在と同規模程度のものを残していきたいと考えています。そのようなところについた分については、また別のところへ配置するなど、できるだけ残していきたい考え方です。 次に医療的ケアの中身の充実や医療連携についてですが、変更によってどういう対応が必要なのかということを、運営事業者にはお願いをしています。あるいは医療連携、今後どういった医療連携が必要なのかにつきましても…","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"それと、あと呼吸器をつけた方も基本的に通える施設として整備されていくのか、その点も伺いたいと思います。当事者、家族の方々への説明会というものも行うべきではないかなと思うのですが、あったらいつ頃考えられているのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"次に団体や家族に対しての説明についてお答えいたします。通所されているご家族のみならず、団体の方に対しましては、情報提供する予定です。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"確認","question":"呼吸器をつけた方も、呼吸器をつけている人が通える場所というものが、品川区には１か所もないという状況がずっと続いていると思うのです。それなので、落ち着いている場合は、呼吸器をつけている方でも通えるようになるのか、その点だけちょっと確認をさせてください。","respondent":"松山障害者支援課長","answer":"区としては通っていただきたいと考えていますが、そういったことによって、区としては支援をしていきたいと考えております。あるいはケアの内容を充実させるということで、今の、現段階のピッコロ以上に内容を充実させていきたいと考えております。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような施設にぜひしてほしいと求めましたし、ぜひしてほしいと求めましたので、よろしくお願いします。本当にいい施設だと思っていますので、ぜひ残していただくということで、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回増設される中で職員宿舎６名とあるのですけれども、これは宿直用などの宿舎ということか尋ねました。","respondent":"東野福祉計画課長","answer":"宿直などではなくて、介護職員の確保のために、何といいますか、通常のアパートなどを借りるのではなく、そこに宿舎として準備をするというものです。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"職員用の住居ということで、ちなみに今回の増改築によって、どれぐらいの職員数が増えるという見込みでいらっしゃいますか尋ねました。","respondent":"東野福祉計画課長","answer":"今後法人の運営ということになりますので、ここをして定員などにつきましてもご提案をいただくということになります。ですから、今のところ何名増えるなどというところでは、明らかになった数字というものを持っているものではございません。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"それで、６名だと少し少ないかなと個人的に思います。可能かどうか分からないのですが、品川総合福祉センターの方とのお話を前向きにしていただけたらなと思いますが、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"こちらの職員寮の使い方につきましては、十分考えていきたいと考えています。まずこちらの介護職員用として設置をしてみて、拡充につきましてはどうなのかという部分は、十分な検証を図る必要があるのかなと考えております。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。前提として区のお考え方として、どこの介護施設も基本的には人員確保に苦労しているというような認識というように考えてよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"２０４０年あたりは、やはりだんだん厳しくなってくるのではないかということは、本会議の答弁等でもしています。もう２０年ぐらいずっと働いていてどんどん高齢化している、訪問系、人材確保については考えていかなければいけないと認識しているところです。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今働いている方が２０年ぐらい働いて高齢化していて、それに伴って今後は人材確保が難しいというようなお話でよろしいですか。もう１回。","respondent":"菅野高齢者福祉課長","answer":"私が伺った訪問介護、ヘルパーの事業者については、そのような傾向が強いというように伺っております。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"２年で辞めることが当たり前だしというように、逆に私自身１３年介護の仕事をしていますけれども、いろいろアンケートをしたりしてみて。そういった要望があれば、そういった対策も区のほうで前向きにしていただけるということでよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"介護人材についての事業者への支援等につきましては、現在も、事業者のヒアリング等もさせていただきながら取り組んでいるところです。各事業者、いろいろな事業者にそういった取組が届くように、いろいろとお声を聴きながら取り組んでまいりたいと思っているところです。","id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"先ほども質問が出ておりましたけれども、何というのですか、お考えでいらっしゃるということは確認させていただきました。小山台のほうでもつくります、そうしたところでも、こうした職員宿舎を設置するというお考えでいらっしゃるのか尋ねました。","respondent":"松山障害者支援課長、菅野高齢者福祉課長、東野福祉計画課長","answer":"認識としては一致しているものと考えております。これからその認識に向けて、具体的にきめ細かく、区民のお声も伺いながら詰めていく… 私のほうからは、職員の住宅確保支援についてお答えします。委員もおっしゃったとおり、スペースの問題等もありますので… 元芝アパート跡地のほうにつきましては、都における設計のほうがもう進んできておりまして、職員宿舎を設ける予定ではないということです。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる介護人材を確保していくという対策の１つとして、何というのでしょうか、お仕事上でも非常に必要なことなのかなとも考えられるところです。今までも、そのお部屋のしつらえというのですか、そうしたものの課題は何かありましたか尋ねました。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"八潮のところにつきましては、現在通常のワンルームアパートのような形のものを予定しています。あまり華美な形ではないのですけれども、十分な生活環境ができるようなスペースを用意したいという考えです。 医療的ケアの依存度の高い方についての受入れについてのご質問です。それからまた、今後も事業者と綿密に打合せをしながら、きちんと丁寧に進めていきたいと考えています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"現在この八潮南特別養護老人ホームのショートステイの定員は１１名かと思うのですが、今回ショートステイの定員は増やされるご予定はあるのかということと、この今のショートステイの利用状況をお伺いいたします。","respondent":"菅野高齢者福祉課長、東野福祉計画課長","answer":"こちら１１名に変更して、８１名から８９名に増やさせていただいて、そういった運用の工夫もさせていただいている次第です。ですから、運営事業者といろいろと相談しながら減らした経緯等もありますので… 先ほどほかの委員からのご質問にもありましたとおり、ショートステイの人数につきましては、同規模程度のものを考えているものです。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどの職員宿舎のことでちょっと伺いたいのですけれども、利用料は何円か、ちょっとそれを教えていただきたいということと……。〔「家賃のことですか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"家賃です、家賃。それから、希望者がたくさんあったときはどのようにして入居者を選ぶのか、その需要の状況というものもちょっと教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"職員宿舎、今後細かい内容等については詰めします。そういった利用料と横引きな形で考えているということと、そういった法人等のお話も聞きながら、ご相談させていただきたいと思っているところです。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"希望者が全員入れるような、そのような形にぜひしていただきたいということで、ちょっと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-02","title":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","agenda":"品川区障害者計画および障害福祉計画・障害児福祉計画策定のための基礎調査結果報告","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"区内事業所からの有効回収率３４.５％で回収を受けておられますが、詳細の２００ページ以上の資料のほうには載るのでしょうか。質問が難しい内容だったのか、ここだけがなぜ違うのか、分かればお願いします。","respondent":"川崎障害者施策推進課長","answer":"７ページのところの障害児の調査のところで、確かに１９６人ということで、ここの人数が下がっているという明確な理由などは把握は致しかねます。第１介助者、第２介助者というものを２人まで、実際の詳細については分かりかねます。","id":"exchange-022"},{"speaker":"ひがし委員","kind":"確認","question":"回収率のところについて少し気になるので、確認をさせてください。ウェブのところだけではなくて、今まで回答してくださった方々、どのようにフォローしていくのかという点をまずはお知らせください。","respondent":"川崎障害者施策推進課長","answer":"設問数増加と回答率の低下というものは比例する傾向がありますので、設問数を見直して項目の精査を進めていく必要はあるかなと考えております。設問数については、今後検討していきたいと思います。","id":"exchange-023"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その結果を見ましても、回収率だけではなくて、ウェブというものが今回始まったのはとてもすばらしいことだなと私も思っております。５７.５％から減った、１５ポイント大きく減少していますというところになるのですけれども、ご説明いただけますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"確かに今回、「働きたいとは思わない」という回答が増えています。パートで働きたいという方もいれば、そういった多様な働き方を今後支援体制として整備していく方向に動かしていきたいなと考えております。","id":"exchange-024"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ設問を考えるときの内容に加えていただきたいと思うということと、そのサポートというものをしっかりとしていただければいいなと考えています。そのような方々も地域で働きたいという意思は絶対あると思いますので、また質問のところについてはその項目を足してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ですから、概要版ではなくて報告書も配っていただきたいということで、これは要望させてほしいと求めました。その設問数が前と違うのか、増やしたというのだったらどれぐらい増えたのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"３級障害をお持ちの方は大変多いので、幅広く回答をつかめるように、属性の仲に障害種別というものを設けてアンケートを実施いたしました。回答の期間、回答のしやすさというものを整備したのですけれども…","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、要望も違いますし、あらゆるところがクロス集計を見ないと中身が見えないという状況になっていると思うのです。クロス集計というものはほとんど全部されていて、そのような実態が分かるようなクロス集計がされているのかということをちょっと伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"クロス集計のほうは、ほとんどの質問事項に対して、障害種別ごとにこのような網かけの状態で載せてはおります。ただ、今回はその属性の中に満遍なく回答を得るために載せさせていただいたのですけれども、こちらの策定のほうには反映していきたいと考えています。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから１５ページなのですけれども、これはｎが５４ということになっているのですけれども、これ回答いただいた方が５４ということなのでしょうか。区としてつかんでいたら教えていただきたいということと、その中で５４人の方が回答されたということで捉えていいのか。","respondent":"川崎障害者施策推進課長","answer":"これは障害児をお持ちのご家族の方が中心にお答えになったと思うのですが、５４人の方が回答していただいたという結果がこの数値になります。医療的ケア児支援関係機関連絡会、合計３０人の方、医療的ケア児の状況として認識をしています。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問","question":"すみません。回答された方が５４人ということは、それはどうしてそのように、医療的ケア者の人数も分かったら教えていただけたらと思うのですが。","respondent":"松山障害者支援課長","answer":"施策推進課長が答弁申し上げたのは３０人ということでしたが、その差異についてです。は相談中の方に対して３０人ということで、恐らく５４人の方につきましては、まだ相談途中の方もいらっしゃるかと推察をしております。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、５４人以上の方が医療的ケア児の方でいらっしゃるということですよね。これは回答いただいたのが５４人なので、大人のほうも人数として捉えている、捉えられている人数を教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"ただし、１５ページにありますように、５４人という数字が出ております。そのたびごとに数字というものは変更があるものと考えておりますが、この２つの数字以外には、区としては捉えているものはございません。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問","question":"実数をどうしたら品川区内で、ではどうしたら、なかなか出ないでしょうか。だから最大でつかんでいるものが、この回答あった５４人ということで、今のところはやむを得ないと、そのようなお考えですね。","respondent":"松山障害者支援課長","answer":"この５４人というお答えいただいた方も確かな数字だと思います。これ以外にお答えいただいていない方、正確な人数というものが、なかなか非常に把握しづらいです。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いします。区内の事業所へのアンケートなのですけれども、当然内容は、具体的にどのような設問をご用意されていますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"事業所の方への設問ということになります。また医療的ケア・重症心身障害児者の対応について、こういったところを質問として挙げさせていただきました。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。有効回収率が３４.５％ということで、私自身はそう思うのですけれども、この数字についてはいかがお考えか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そうですね。うちとしても１３９事業所に送らせてはいただいたので、やはり半数近く回答が上がれば、ここは委員のおっしゃるとおりだとは思います。","id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１００％にする必要はないと思いますけれども、やはり、いくらなんでも３４は、ちょっと実態を把握するのには少し心もとない数字かなと思います。ぜひ数字を上げてほしいと求めましたので、そういった施策というものは、お考えはありますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"はやはり周知のところも含めて、事業所様とは日々私どもも連携を取りながら、障害者の、そして障害児の実態というものをつかむために、事業所様とも日々の連携の中から前もっての周知をさせていただきつつ、実効的な回答を得られるように、私どもも工夫をしてまいります。","id":"exchange-034"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみにどのような理由でアンケートを答えられなかったのですかというような感じのことを伺って、お考えというか、検討していただけますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そういったご提案も含めて、私どもも工夫は図ってまいりたいと思います。","id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"当然自分たちの意見というものを区政に反映してほしいなどということは、そういったものを積極的に次回に活かしてほしいと求めました。よりよい、こういった障害者福祉計画を策定していくときに必要だと思いますので、ぜひご検討、前向きにお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"おぎの委員","kind":"意見","question":"そういったような、こちら側からの働きかけをまた引き続き、続けていただけるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"こしば副委員長","kind":"確認","question":"その状況について教えてもらいたいということと、これは２２.５％となっていまして、１８歳から３９歳の方が２５.５％と多い。これの関連性というものはあるのかどうかも含めて、今後に向けた考え、取組を教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"もう１点ですけれども、１１ページのところです。超短時間就労を今進めておりまして、有効な対策としては、１つ区としては前向きに進めていきたいと考えています。","id":"exchange-038"},{"speaker":"こしば副委員長","kind":"質問","question":"年齢との関連性をちょっと教えてもらいたい。１８歳から３９歳までの方は、正職員として働きたいというパーセンテージが多いから、多分リンクはしているのかなとは思うのです。","respondent":"松山障害者支援課長","answer":"１８歳ぐらいからは、あるいは就職する際に、やはりうまくいかないというところでご相談をいただく場合があります。これは発達障害者支援施設に関しましても、今後働けるように、区としては支援していきたいと考えております。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"先ほどのご説明で、今回の設問で新たに「相談時の困りごと」ということをお伺いしましたというご説明でした。その点の、どのようなことで今回の設問が増えたのか、お聞かせ願いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"この情報アクセシビリティの観点から、アクセスの重要性については今後検討していかなければならないと考えております。そういった困り事というものを設けることで、私どもも必要な支援、体制の整備というものを考えていきたいと思っているところです。","id":"exchange-040"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認をする、どうそれをアプローチというか、体制を整えてほしいと求めました。何かご意見、お答えが、コメントがあればお願いしたいと思いますが。","respondent":"川崎障害者施策推進課長","answer":"今委員おっしゃられましたように、必要なサービスを必要な方に受け入れていただけるように、私どもも実情のほうに対応していきたいと思います。","id":"exchange-041"}]},{"id":"topic-03","title":"令和４年度品川区障害福祉計画実績","agenda":"令和４年度品川区障害福祉計画実績","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"この目標値の2)施設入所者数のところ、目標値としては２７１人を超えないとなっているのですが、定員数について教えていただきたい。この目標設定をした、この値を設定した理由についての背景も教えていただきたいです。","respondent":"松山障害者支援課長","answer":"本計画をつくった時点では、品川区令和元年度末時点の入所者数は２７１人という、当時の数字です。国に従いまして、超えないことを基本とするということで策定委員会で決めたものです。","id":"exchange-042"},{"speaker":"ひがし委員","kind":"質問・要望","question":"だとしたら、現在目標値１０人というところだと、待っている方々は入れないのではないかと思います。今後、この目標値の設定についても検証していく予定なのか、また、その方法についても教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"その中で、実際に地域移行者数、これとは別に地域自立支援協議会、この２ページの下にあります。施設側から見たご本人の地域移行への状況等も把握しておりますので、また品川区の実態を踏まえて、策定委員会の中で議論していくものと考えます。","id":"exchange-043"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今後計画していっていただきたいと思うのと、こういう開設というのも必要だとは思うのですが、至らなかった理由などについても教えていただけますか尋ねました。","respondent":"松山障害者支援課長","answer":"このサービスを開始してくれないかという投げかけはしたのですが、あるいはスキル、まだそこまでいっていないというようなご意見もございました。実は令和５年度に区が補助金を予算立てしまして、今後とも、今後とも一歩ずつ開設に向けて努力していきたいと考えています。","id":"exchange-044"},{"speaker":"ひがし委員","kind":"意見","question":"これについてはしっかりとヒアリングを行いながら前向きに検討、そして、実行できるための要因というところもしっかりと見ていただければいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問","question":"障害者支援課長が足をけがされているので、着座での答弁をお願いしたいのですけれども、よろしいですか。お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１ページの(3)なのですけれども、令和２年のときにこれだけ低いという、その理由を教えていただきたいのが１点です。だから、令和２年のときがすごく少ないのか、このような形で増えてきたのか、そこだけの状況を教えていただきたい。","respondent":"坂野保健予防課長","answer":"コロナで申請の延長、それがあったせいで年度がずれ込んでいるので、こういう数字になっています。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが求められる施設入所の方というのが、どれぐらい入所を待っている方がいらっしゃるのかというのを教えていただけたらと思います。どのようなアプローチというか、誘致とかも含めてされたのか、その点も伺いたいと思います。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"こういうグループホームだったら入れるけれども、こういうグループホームは難しいといったような、受け側の施設側のといったこともあります。施設かグループホームか、なかなか決め切れない方もいらっしゃいますので… 区として整備費補助の周知として、法人等、令和４年度に約３００件ほど郵送なりメールなりで整備費補助の周知はさせていただいたところです。今後も民間の活力を使いながら、グループホームの整備、増やしていきたいと考えております。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは令和５年のところでは入れていくということになっていくのか、これは年１回しかされないのか、そのことも伺いたいと思います。続けて４ページのところも伺いたいのですけれども、２つ目の段落のところで、そこの具体的なところの確認をお願いしたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長、榎本荏原保健センター所長","answer":"では、私のほうから、整備費補助、令和４年度の実績についてですが、１件ございました。 こちらは、なかなか通常のショートステイでは受入れができない方向けに開始しているものですので、相談支援員を通じて周知を行っているところです。ただ… 品川区精神保健福祉地域連絡会、協議の場の回数についてですが、年１回の開催で行っております。開催時期につきまして…","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どこにどんな働きかけをされたのかも伺いたいと思います。その解決というのは様々求められているところだと思うのですけれども、今後また増やすという考えはあるのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"私立も含めての説明会を行わせていただき、あるいは訪問される側が理解していただけるように、周知に努めたところです。これまで設置以降、本当にコロナ対応に追われていた方々の集まりということですので、今年度についてはまずは２回の開催を予定しております。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"４ページの主な内容の４番なのですが、なかなかヘルパーが見つからず受けられないということをいろいろお伺いしてきているのですが。そこら辺のところも教えていただきたいのですけれども、足りない実態がどれぐらい改善されてきたのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"アンケート調査を品川総合福祉センターで実施しまして、移動支援の従事者として事業所に所属して、登録者としては３人でした。なかなか移動支援としては、お声に応え切れない部分もありますので、より力を入れて実施していきたいと考えています。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に移動支援は求めるところに足りなくて、登録される方がもっと増えるような形での品川区の取組もぜひ強力に進めてほしいと求めました。そこら辺のところの状況も改めて伺いたいのと、具体的にどんなことが支援されたのかということも教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"在宅介護支援センターに併設の６か所というのも、こちら、地域の相談支援事業者、指定特定相談事業所になります。地域拠点相談支援センターや在宅介護支援センターの併設型のところがバックアップするような形で、一緒に動く場合がありますので、そういった場合に。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１６ページの、これだけ求められているということなのかと思うのですけれども、放課後等デイサービスはこれから拡大が求められているのかと。が求められているのかと思うのですけれども、これからどういう手を打たれようとしているのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"令和元年度から倍近くの伸びで、利用者数は増えているのですけれども、その増加に事業者が追いついていないというのが現実です。親御さんにとってみれば、障害児の支援としては必要な場所になりますので、ここのところは強化をしていきたいと考えております。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ拡大できるようにということで、区としても取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問","question":"４番の専門的人材の確保・養成というところですが、年に１回、品福が東京都の指定を受けて区が助成されていらっしゃいます。１８ページに実績のほうですけれども、こちらの数字が見込みが１,６６４人に対して実績が１,３８３人で、その辺のご見解はいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"人材の確保というのが、移動支援事業については、比較的マンツーマンで対応するというものです。なかなか人材確保というのは今後、当然ながら、委員のおっしゃられたとおり、より人材確保を進めなければならないと区は認識をしております。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひそういった移動支援ヘルパーを含めた人材確保、そして、研修等を積極的に実施してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"６ページの障害児支援の提供体制の整備等についてお伺いしたいと思います。改めて訪問支援という事業内容、確認をさせてほしいと求めました。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援についてご説明いたします。保育所等訪問支援については、頻度が大体月に２回程度ということで国から示されておりますけれども、保育所等訪問支援がなくなった後。","id":"exchange-057"},{"speaker":"こんの委員","kind":"確認","question":"その後はどのようになっていますでしょうか。私立の体制も、今現状どうなっていますか尋ねました。","respondent":"松山障害者支援課長","answer":"私立の部分につきましても、所管する部署と連携を取りまして、説明会を行わせていただきました。１回だけの説明ではなかなか難しいというところがございまして、そして園、じっくりお母さんを中心として支援するということが重要かと思っています。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからもそうした説明会を増やすのか、連携を取りながら、そこはサポート体制をぜひ私立のほうでもつくってさしあげてほしいと求めました。いわゆるこの訪問支援員が入って、適切な療育なり、そうしたサポートにつながった例というのはどれぐらいあるのか尋ねました。","respondent":"松山障害者支援課長","answer":"やはり比較的どうしても長期的な支援が必要なお子さん、あるいは発達を支援する見方や考え方、伴走型の支援だと考えております。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"伴走型、そうですよね。その体制を、どうか親御さんにも理解が及ぶような形で支援を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおり、お母様やお父様方、園の理解が本当に必要な、一番のお子さんにとってのサポートになるかと思いますので、そういった保護者の方や園側のお気持ちや体制に配慮しつつ、発達に応じて必要な支援を行ってまいります。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"１ページのところなのですけれども、障害児者の状況のところで、(3)の精神通院と手帳保持者数合計というのがありますが、年度を経るにつれ増えているのですけれども、ここから受け取ることは、精神障害の方が増加しているということでよろしいのか尋ねました。","respondent":"坂野保健予防課長","answer":"だからそれで増えている部分もあるでしょうし、実際に増えている部分もあるのかもしれません。なかなかそれは簡単には、こうですとは言い難いと思います。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"いろいろ難しい部分もあると思うのですけれども、制度が始まっての時間的なこともあると思うのですけれども、単純にこれ、増えているとは言えないのか尋ねました。","respondent":"坂野保健予防課長","answer":"要するに、制度が浸透しつつある過程なので。若干増えている印象はあることはありますが、これは増えています、これは減っていますというのはなかなか簡単には言えないところかと思います。","id":"exchange-062"},{"speaker":"筒井委員","kind":"確認","question":"細かいことはまたお伺いしたいと思いますけれども、この目標値というのはどういった基準で考えているのかということと、これは数値目標が難しかったところなのかということを確認したいと思います。","respondent":"松山障害者支援課長","answer":"成果目標にありますように、精神障害にも対応した地域包括ケアシステムの構築といったような、各自治体とも同じような目標にはなります。まだ新たな制度でしたり、なかなか今後の見込みがつかないというものもありますので、充実と書いてあるのもあります。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。それはやはり目標をクリアしやすい数字、ある程度現実的な目標値を区として考えて表示しているという理解でよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"あるいは本当に現実に即した、実態に即した見込みを算定した数字なのかというところの、その中でも議論がございました。かといって、きちんと努力して、現実的な数字を出そうということで議論した上での数値目標として設定をさせていただいたものです。","id":"exchange-064"}]},{"id":"topic-04","title":"品川区医療的ケア児地域生活支援促進事業の仮移転","agenda":"品川区医療的ケア児地域生活支援促進事業の仮移転","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それが今の説明になるというのは、随分１年以上前にご説明いただくというのは、これはなぜこんなに早いときに説明なのかということを教えてください。それから、地域への説明とか、利用者とか、そういう関係する人たちへの説明会みたいなものはいつ頃されるのかについても伺います。","respondent":"松山障害者支援課長","answer":"今後、７月５日に行財政改革特別委員会でのご報告というのがございまして、それが終わってから地域のほうに説明をさせていただきたいと考えています。特に集まるというようなものが難しい方々ばかりなので…","id":"exchange-065"},{"speaker":"鈴木委員","kind":"意見","question":"かなり年数がたっているような気がするのですが、建物の建設された時期、築何年なのか。そこら辺のところは、ここではないのかどうか分からないのですけれども、分かる範囲でお願いできたらと思いますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"昭和５８年に建築されておりまして、築３９年になります。今のところは改修で対応する予定です。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"仮移転先についてなのですけれども、利用者というのが送迎サービスで駐車場など、車を利用する方が多いと思うのですが、仮移転先に駐車スペース、また、送迎のサービスなどをつける予定はあるのか、説明を求めました。","respondent":"松山障害者支援課長","answer":"現在もベルについては特に送迎というものはございません。仮移転先についても、特に今のところ予定しているものはございません。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問","question":"今現在通われている方々というのは、駐車スペースがなくて、送迎もないという状況であると、医療的ケアの必要な方々は荷物が多かったり、移動するのが大変だと思うのですが、今の現状で送迎を利用したいという声が出ていないのか、また、駐車スペースについての声も上がっていないのか、伺います。","respondent":"松山障害者支援課長","answer":"事業者とも実は話を進めているところです。少し事業が軌道に乗ったら、送迎とかのサービスも考えようということで、事業者とは話しています。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"これは要望になるのですけれども、やはり行ってその場でお話をするというのと全然違うことだと思うので、送迎や駐車場のスペースの確保なども今後積極的に前向きに検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"こんの委員","kind":"確認","question":"というところの確認です。その辺を確認させてください。","respondent":"松山障害者支援課長","answer":"ベルについては、今のところ、想定では、児童発達支援センターの建物の中に戻ってくる予定です。そこからアウトリーチしたりというような地域支援事業についてもありますし、児童発達支援センターとしてリニューアルしていきたいと考えています。","id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"そうなると、１階部分は、児童発達支援センターの中にベルの場所が確保されるという理解でいいのでしょうか。去年ですかね、戻るとまた３００m2弱となってしまうとあれなので、どんな感じか尋ねました。","respondent":"松山障害者支援課長","answer":"改修設計を今年度予定しておりますので、どのように新たな２か所目の児童発達支援センターとして有効に機能させていくかというところにつきましては、改修設計の中で詰めていきたいと考えております。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問","question":"すみません。今度の新しくできるときは建物の１、２階部分を児童発達支援センターということで、そこら辺のところも説明を求めました。","respondent":"松山障害者支援課長","answer":"実際の児童発達支援センター等の運営の方法なのですが、まだ運営の方法については、今後、検討ということになっております。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問","question":"全国平均は２８％なので、なぜ要支援がこれだけ多いのか、それをどう捉えているのかをまず伺いたいと思います。それは改善が必要なのではないかと思うのですけれども、区としてはどういう対策を検討しているのかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"審査は適正に行われており、その結果が全国構成比と比較して要支援の割合が高くなっているものと認識しているところです。申請をして２週間ぐらいで訪問の日程の連絡が行って、結果が出るまで大体１か月少し、１か月半弱ぐらいで結果が着くと捉えております。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"適正に行われているということで言われているのですけれども、多分、全国も適正にされていると思うのです。あるにもかかわらず、区としてなぜこんなに全国平均と比べて違うのかというところはどう捉えられているのか、そのことを伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区としては、第８期の品川区介護保険事業計画において、健康づくりと介護予防サービスの充実を基本方針の一つとして掲げております。１２ページ、１３ページに総合事業等の実施状況を掲載しておりますが…","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"要支援の場合だと、きちんとサービスを受けられるというところでぜひ改善していただきたいということで、これは要望をさせてほしいと求めました。１か月の利用料が５０万円とか７０万円とか、要介護５であれば２６万円とか、そういうところはどう考えられているかも伺っていきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区内の特定施設、そのうちの大体４割ぐらいの方は区民の方が入居しているという状況で、それ以外の方は区外の方ということになります。こちらとしては、保険者として、請求された保険給付をさせていただいているという実態です。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問","question":"これが１か月とか、１年丸々ではないということになると、伺いたいと思います。滞納に対しての相談窓口というのはどこになっているのか、どんな相談がされているのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"納期限に払込みがなかった場合には、催告書とか督促状とか、そういったものをまず送らせていただく。その方たちが丁寧に一軒一軒、少しずつですけれども徴収をいただいていたりとか、そういった工夫の相談窓口等も設けしています。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問","question":"滞納の理由というのが、払いたくても払えないとか、貧困の状態だとか、そういうのがあって、こういう滞納の状況になっているのか。暮らし・しごと応援センターですとか、生保につなぐとか、そこら辺がどのようにされているのかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"これは今の生活では厳しいということでしたらば、もちろん生活保護の窓口のほうにおつなぎするという形の手続もしています。前のページの９ページに保険料がありますが、一定程度お支払いができるものと私どもは見込んでおりまして、徴収をさせていただいている次第です。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"私はここに高齢者の生活が大変な状況というのがあるのではないかという思いで伺っているのですけれども、そのようなところでは、つかまれているのか。一人一人に徴収員が出て、それに任せるというのではなくて、そこら辺のところがどうなっているのかというところを改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今、こちらの保険料を納めているところは、高齢者福祉課の保険料係というところで対応しています。連携を図って、今もしておりますが、引き続き強めていきたいと思っているところです。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最後に１つだけ確認なのですけれども、今までどおりそういうペナルティーはしていないという確認をさせてほしいと求めました。介護保険制度推進委員会は１年間で何回ぐらい計画されているのかと、それから、直近の介護保険制度推進委員会の日程が分かっていたら説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"７月２６日水曜日の午後１時半か２時だったか、午後開催予定を今、考えているところです。今年度については４回開催をする予定となっておりまして、区の需給見込みとか、そういったところを審議していく予定となっております。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それはどういった理由というか、そういったものをお聞かせいただきたいのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"この間、在宅介護支援センター２０か所に高齢者の総合支援システムというシステムを配備させていただいておりまして、そういった機能もあります。在宅介護支援センターで、そちらのほうで対応させていただいたりとかということで…","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、そういった総合支援システム等があるので、いわゆる包括支援センターであるような、保健師とか社会福祉士が常駐していれば、そういったシステムというか、そういう体制は構築していなくても大丈夫だという判断ということでよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"もちろんそういった専門職の方たちのノウハウは必要だと考えていますし、高齢者福祉課にも一定程度の保健師がいて、常に助言等をしています。在宅介護支援センター、サブセンターの地域包括支援センターという形にさせていただいて、地域包括支援センターが本来やる役割。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ほかの包括支援センターがあるところに比べると、相談しにくいとか、その辺はサービスの充実を少し進めていっていただきたいと考えております。６８％ケアプランを作成されているということで、民間が３１.６％、ほかの区と比べて割合というのはいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"地域包括支援センターのサブセンターの役割を果たしているという、区と在宅介護支援センターとの関係性が他区とは少し違う、オリジナルというか。要支援１、地域包括支援センターのサブセンターの役割を果たしておりますので、要支援の１。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私が以前勤めていたほかの区に比べると、民間の割合が少ないかと思うのですけれども、それが何か決まった理由があるのかと思ったのですが、それはいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"民間居宅介護支援事業所の数等につきましては、これは自然に来ていただくものというか、特に民間居宅介護支援事業所に対しての厳しい規制とかをしているわけではございませんので、自然な形でこういう割合になっているのだと捉えています。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３ページのところで、やはり施設系は大分支出がボリュームが増えやすいというところもあると思うのですけれども、そういったことが理由なのか。そういったところをお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"ただし、品川区が目指す高齢者介護の在り方、目標は、できる限り住み慣れた我が家で暮らすというのを目標としています。その部分を最優先に考えて、こちらの在宅介護に力を入れているというのが、第一の目的となっております。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"かしこまりました。１２ページ、７番の(1)の1)の柔道整復師による機能訓練訪問事業というものの概要をご説明いただきたいのですけれども。","respondent":"川原高齢者地域支援課長","answer":"高齢者地域支援課よりご説明をします。要介護状態にならないために、充実させる必要があるという目的の下、柔道整復師による機能訓練訪問事業を短期集中サービスとして実施したものです。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、訪問リハビリの要素が強いという理解でよろしいか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"こちらの認識としては、柔道整復師を機能訓練指導員として、利用者の居宅を訪問して、自立支援を目標とした、外出の支援のための、その方に応じた身体的な動きの目標を設定して、運動指導ですとか歩行訓練を実施するような形です。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"柔道整復師はどのように募集してというか、どういう形で派遣されていらっしゃるのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"公益財団法人の東京都の柔道整復師会品川支部に委託をしている形です。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"品川支部に委託していると。区内にある整骨院とか、柔道整復師がいらっしゃるようなところから派遣されるとか、そういったことはお考えか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"実際に訪問していただいているのは、区内の整骨院の柔道整復師がご自宅に訪問しているような形です。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"こういった取組はぜひ続けてほしいと求めましたので、要望ですけれども、よろしくお願いいたします。そのまま１２番の下の介護予防ケアマネジメントの予防事業なのですけれども、利用率というのは、回数とかというのはいかがか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"でありますと、総合事業対象者、令和４年度の３６０件に比べて令和３年は４０１人という形で、若干減っているような形です。それに併せまして、サービスを利用する要支援者のケアプランの作成実績１,４８８人に対して、こちらも併せて減っているという状況です。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"要望になってくると思うのですけれども、それこそ施設系のサービスとか重度の介護サービスに比べると、そんなに費用はかからないと思うのです。ぜひこういったところに積極的に力を入れていただきたいと思っておりまして、１点、あくまで一提案ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"こんの委員","kind":"確認","question":"現状だけ確認させてください。この実績はどのように捉えていますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"令和３年度は４５２人の活動人数に対して、今回は１００人少し逆に増えたかというところで、こちらからも積極的に対応していきたいと考えています。今後の対応についても話し合っているところでございまして、社会参加というところで引き続き実行してまいりたい…","id":"exchange-091"},{"speaker":"こんの委員","kind":"提案","question":"今後の展開というのはどうなってしまうのだろうかと思ってしまうところですけれども、そうするとそろえていくということになるのでしょうか。具体的にこういうボランティア活動があるといいという提案できるものは今ないのですけれども、いかがか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"今年度新たに運動系の介護予防事業と、あと、認知症の予防事業を支援事業を増やしています。ボランティアとして支援してくださっている、そういった事業を増やしている中で、ボランティアの活動の場もより増やしていきたいと考えています。","id":"exchange-092"}]},{"id":"topic-05","title":"品川区立健康センター指定管理者候補者の公募","agenda":"品川区立健康センター指定管理者候補者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"こういうことは今まで５年ごとだと３回ぐらいされていると思うのですが、その前の２回というのはどんな事業者がなっていたのか。これまでの経過を説明を求めました。","respondent":"若生健康課長","answer":"今期は令和元年度から開始しておりますので、平成２６年度から平成３０年度につきましては、３者合同の共同事業体に指定管理をお願いしています。第１期、平成２１年度から平成２５年度の指定管理につきましては…","id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その経過を教えていただきたいのと、この健康センターは、品川と荏原と両方同じ指定管理者が行うということですよね。その確認と、そこになるときにはまたこの５年間の後になるのかということで、またもう一回指定管理者の選び直しとなるのか。","respondent":"若生健康課長","answer":"１点目、過去の選定についても公募で行ったかですが、同様に１期から公募において、プロポーザル方式で実施をしています。保健センターは改修後戻る予定ですけれども、これは予定では令和１１年度まで仮にというか、企画のほうで検討を進めているです。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"公募についての説明会というのは行わないのでしょうかというところです。募集をかけて、それ以外のところと競争原理が働く中でよりいいところを選んでいただきたいと思うのですけれども、その点はいかがか尋ねました。","respondent":"若生健康課長","answer":"ここに関しての説明会ですけれども、こちらについては、参加申込みの資料のほうに、７月下旬に品川健康センターのほうで説明会と施設見学会、それからその後、荏原健康センターのほうでも見学会を併せて行う予定です。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"１期２期と共同事業体でされてきた中での健康づくりの事業、もっとこうしてほしい要望みたいなものとか、今後選ぶ視点としてはどのように持っていらっしゃいますか尋ねました。","respondent":"若生健康課長","answer":"これが９４％、健康センターの利用者に対しても満足度の高いサービスが提供できているということを区としても認識しているところでございまして、今後もよりよい健康づくり施策につなげていくためのサービス向上について提供いただける事業者を選定してまいりたいと考えています。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"どういうところが応募してくるかというのは分かりませんが、区としてこれまでの、ぜひよりいい事業者を選んでいただきたいと。評価をお聞きをしましたので、簡単にできる健康スポーツセンターみたいなものも出てきておりますので、いかがか尋ねました。","respondent":"若生健康課長","answer":"というのは、幼児から高齢者の方まで幅広く、しかも低料金で気軽にご利用いただける。高齢の、そういったところが区の健康センターの魅力かと思っているので、そういったところを今後とも充実させていきたいと思います。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"第４回定例会で上程されるということですので、また事業者がどのように決まったのかというのは、そのときに伺っていきたい。このように思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問","question":"今回、指定管理に当たって、品川区指定管理者制度活用に係る基本方針に則っていると思うのですけれども、これ、今回、設置条例というのはないのか尋ねました。","respondent":"若生健康課長","answer":"健康センターに関しては、公の施設になりまして、条例の根拠を持っております。健康センター設置条例というのを制定しています。","id":"exchange-099"},{"speaker":"筒井委員","kind":"質問・要望","question":"では、その健康センター設置条例に、それで指定管理者を選ぶということなのですか。それとも、指定管理者を選考するのは、あくまでも基本方針で選んでいくということなのか尋ねました。","respondent":"若生健康課長","answer":"条例のほうにも、指定管理者の選定の基準ですとか、そういう根拠のほうが規定されています。","id":"exchange-100"},{"speaker":"筒井委員","kind":"質問","question":"それで、今現在、住友エスフォルタが３期続けてやられているのですけれども、ほかに１期２期と住友が指定管理者と決定されたわけですが、１期２期の公募のときに、ほかのある意味競争相手となる業者というのは何者かあったのか尋ねました。","respondent":"若生健康課長","answer":"２期につきましては、１者のみと。３期につきましては、選定以外の候補者がほかに２者ございました。","id":"exchange-101"},{"speaker":"筒井委員","kind":"提案","question":"助言というか、ご提案がすばらしいものだったらそのままという結果もあり得るのですけれども、幅広い事業者から選んでいただきたいと考えております。公正かつ厳正な審査をお願いしたいと考えておりますけれども、その点、区のご見解はいかがか尋ねました。","respondent":"若生健康課長","answer":"条例ですとか指定管理者の基本方針等に則って、公正かつ厳正な審査を行ってまいりましたので、今回についても同じようにやってまいりたいと考えています。","id":"exchange-102"}]},{"id":"topic-06","title":"荏原保健センター等複合施設大規模改修工事","agenda":"荏原保健センター等複合施設大規模改修工事","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"仮移転先でもしっかりと利用者が利用しやすい状況をつくっていただきたいというのと、同じような状況を経験していますので、そこの点についての対応等についてはどのように考えていますか。","respondent":"菅野高齢者福祉課長","answer":"居ながら工事の部分について、荏原特別養護老人ホームの部分ですので、私のほうからお答えします。その辺りのところは丁寧に対応していきたいというところで、この辺り、丁寧に対応してもらうようにこちらのほうからもお願いする予定です。","id":"exchange-103"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご答弁いただきましたように、しっかりと入っている方々の声を聞きながら、対応策というところもその都度立てていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのスケジュールのところもお聞かせいただきたいのと、というのは、地域の説明会ですとか利用者説明会は既に終わっているということなのです。そこら辺の説明会の状況というのは、どのように行ってきたのかということについても説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"５月１７日から６月１日の間に地区の町会長会議に行きまして、また改めて大規模改修を行うことでご説明、資料の配布などを行っております。今後、施工業者が決まった段階で、併せてチラシ等の配布を近隣の住民の方に行い、都民住宅の方にも説明会を行うような計画になっておりま…","id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問","question":"８月から準備工事が始まるわけですから、今月ぐらいの間には近隣への説明会というのも必要なのではないかと思うのですが、その点はどう考えられているのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"２年ほど前から町会長会議をはじめ、そういった方々にも１年ほど前からお伝えして、周知を図っている状況です。最後に、先ほども申し上げましたとおり、チラシ配布等で施工者と区が併せて近隣住民の方のところに回っていくことで、今回は対応を考えています。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その説明をするようにということを求めるというわけにはなかなかいかないと思いますので、こういう施設ですから、これは検討はできないのでしょうか。丁寧にやってほしいと求めましたけれども、その点、いかがか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"大規模改修工事におきましては、先ほど、現に住んでいる方、都民住宅とか、近隣の方には、一定程度の説明をしてやっていくということで、今までも改修工事については、そんな形で行っていたということで、今回はそのような対応となっております。","id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今までもそうだということなのですけれども、ふれあい掲示板ですとか、チラシとか、町会長というだけでは私は十分ではないのかと思います。もしこれから地域の方からの声が上がったりとかということがあれば、途中でもぜひ説明とかは丁寧にしていただきたいということで、要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"こんの委員","kind":"確認","question":"確認です。利用者には既にこのことは伝わっているのですよねという確認と、利用者にはどのようにお伝えをされているのかというところを確認させてください。","respondent":"榎本荏原保健センター所長","answer":"精神の自立支援医療でありますとか、１年以上前より少し早いぐらいの時期からご案内をしておりまして、必ず窓口で言葉をかけてご説明をしております。予定というよりも、職員を配置して、丁寧にご案内するという形で対応したいと考えています。","id":"exchange-109"},{"speaker":"こんの委員","kind":"確認","question":"お母さんたちは若い方たちが多いので、電子でも、そうしたことでの確認とかというのもあるのでしょうか。その点だけ確認させてください。","respondent":"榎本荏原保健センター所長","answer":"ホームページにも仮移転のお知らせということで、地図も含めて掲示をしております。更新した後も、またそれに合わせて変えて、内容をより分かりやすくお知らせをする必要があると考えておりますので、そんな形で対応したいと思います。","id":"exchange-110"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"こんの委員","kind":"提案","question":"確認ですが、今提案された方向性、明石市のほうと。ちなみに、明石市のほうは何のテーマでこちらを選ばれたのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"こんの委員","kind":"確認","question":"例えば、障害者福祉が明石市は事例として見てきたほうがいいというふうに選ばれているのではないかと思ったのですが、そうではないのですか。その辺、確認させてください。","respondent":"松永委員長","answer":"それ以外にも、健康推進のほうでも関西方面で、例えば、大阪のほうでもやっているところがありますので、それも含めて今考えている最中ですので、今検討中です。","id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"繰り返しになりますが、明石市については何のテーマと決まっていらっしゃるのですか。要するに、障害福祉なのか、高齢福祉なのか、精神福祉なのか、はたまた地域共生なのかというところは見えていらっしゃるということなのか尋ねました。","respondent":"松永委員長","answer":"高齢者福祉に関しては、先ほどの在宅高齢者の生活支援の移動の支援とか、もう一つは、フレイル予防について等も含めて今検討中であります。明石市のほうでやっているということなので、そちらのほうにと考えています。","id":"exchange-113"},{"speaker":"こんの委員","kind":"提案","question":"分かりました。何かこちらも提案できるものがあれば、探してみたいというか、研究テーマとしてしていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"鈴木委員","kind":"提案","question":"兵庫県明石市を中心にということで、その近辺で行ける範囲のところであれば、これからまだ提案をしても検討いただけるということで、いつ頃までに提案とかというのはあるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。それがもしもまた本当に第９波が拡大したとかといったときには、またどうするかというのは検討することはあるということですよねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":84184,"voices":304}},{"id":"r05-20230704-8","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"建設委員会","time":"午前１０時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を89件整理しています。","topics":[{"id":"topic-01","title":"八潮五丁目地区まちづくりガイドラインの策定検討状況","agenda":"八潮五丁目地区まちづくりガイドラインの策定検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１３ページの真ん中辺りのところなのですが、そこは区がどう考えているのかというのを伺いたいと思います。パトリアのところを考えてみても、１０６か所いかないなと思っておりまして、どういったところが入っているのかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"取り組んでいることを、連携して進めていこうという内容でございまして、できるだけ記載していこうと。細かい状況のバックデータのところはご説明できないところなのですが、３ｔ規制がされているという状況を書かせていただいているようなところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"聞いたところによると、区としては何か補助していくとか支援していくというような考えがあるのかどうか、伺いたいと思います。八潮団地ができてから４０年ぐらいたとうとしているということで、区として何か支援できることがあるのかも含めて、お考えを伺いたいと思います。","respondent":"森道路課長、河内環境課長、鈴木都市計画課長","answer":"八潮団地内の３ｔ規制につきましては、少しお時間をいただいて、後ほど答弁させていただければと思います。 東京熱供給株式会社から説明を受けた内容によりますと、臨時的に値上げするというようなところも検討していきたいという考えが示されたところです。… 多世代交流や賑わい創出を支援するまちづくり拠点の整備というところで、また、これから様々な部署が検討していくということになろうかと思います。…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"パトリアとかにＡＴＭを設置してほしいということがありましたので、考えていただきたいと思うのですけれども、区のお考えを伺いたいと思います。いっぱい切られてしまったということなので、ぜひしっかりと保全していっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長、森道路課長","answer":"やはり様々な生活支援機能について、あるいは事業者への働きかけも含めて、区としても行っていきたいです。その中で、しっかりと緑を守っていく、残していくというような形で記載させていただいているところです。 先ほどの３ｔの通行規制というお話ですけれども、交通管理者である警察のほうで、警察のほうで大型車両の通行を制限していると。通過車両が実際３ｔ以上のものが入ってきている可能性があるですけれども、警察のほうと情報共有しながら…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"交通規制のほうは、連携をとって、入ってこないようにしてほしいと求めました。これまで育ててきた緑がなくなってしまうということになってしまうので、そこは十分説明もしながら、緑を保全していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"７月上旬頃ということですけれども、あと、何回行っていくのかということを伺いたいと思います。１回当たりにすると８人ぐらいなのかなというところなのですが、ぜひそういった対応をしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"将来の様々な計画立てあるいは検討の中で、この位置づけに基づいて取り組んでいただきたいという意味合いで、まずは記載させていただいたです。八潮みらい懇談会の中で説明し、コロナ禍の中での検討ということで…","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"目的ですが、これは何のためのまちづくりガイドラインなのでしょうか。それをどう捉えて、これから何年先の八潮地区の状況を考えながらこのガイドラインをつくろうとしているのか、まずそこを確認させてください。","respondent":"鈴木都市計画課長","answer":"先ほど冒頭でもご説明しましたが、八潮というのは昭和５８年に入居が始まって、それぞれの主体が今なお様々な取組を進めていただいていると。さらにまちづくりを進め、今ご説明した高齢化あるいは単身世帯の増加等については、支え合いですとか高齢者の方への支援ですとか。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"これから１０年先、２０年先を踏まえた形で、どういうまちにしていくのですかという議論につながると私は思っていました。どういうふうに次の世代につなげていくのですか、次の八潮の姿をどう考えていくのですかというふうにつなげていかないとおかしいのではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"団地の更新というのは非常に長い期間検討がされて、地域の人と一緒に考えながら、八潮の将来的な形もそういう形で進んでいくのかなという認識です。ここにはこういう機能が必要だねという時期ではまだないというのが区の認識でございまして、次の世代、次のまちにつなげていくと。","id":"exchange-007"},{"speaker":"西本委員","kind":"提案","question":"私が、提案の中で幾つかありますけれども、７、８ページを見ていただくと、八潮地区というのは様々な教育施設がたくさんあるのです。２０年、３０年かかるかもしれないですが、それに向けてやっていこうよというふうに品川区が決めて進めていくというのも一つの方法ではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"１０年前のまちづくりマスタープラン策定、各地区ごとでのまちづくりの方針、目標というのはマスタープランのほうでも定めております。鉄道の車両基地エリア、そうしたところの記載は、広域の計画であるマスタープランのほうでも整理をさせていただいているという状況です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"ここが足りないという、これからどういうふうに夢のある八潮地区にしていきましょうかというふうに話し合って進めていただきたいと私は思っています。鉄道の誘致、これをしっかりと位置づけて進めていただきたいと、意見として言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"２１ページに建物や歩道の段差解消とありますが、明らかな段差というのでしょうか、坂が多いのです。今後ますます高齢化が進む八潮地域のまちづくりガイドラインとして、私は大きく捉えていくべき視点だと考えていますが、いかがお考えか尋ねました。","respondent":"鈴木都市計画課長、森道路課長","answer":"先ほどご説明しましたように、コミュニティ、にぎわいの視点というテーマごとで整理をさせていただいていると。先ほどご説明したテーマごとにさらに深掘りをして、そうした検討も視野に入れながら、特化した検討を進めていくと。 ガイドラインの１２ページに記載しておりますが、歩道の幅員を広げたり、段差を解消したりという形で対応しています。それぞれの管理者の方と情報共有しながら、今…","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"何というのですか、西本委員のご指摘に同感でありまして、しっかりとしたプランにすべきだと考えています。団地内通路の段差解消だと思うのですが、こういうところにまで品川区が突っ込んで対応できるものなのかどうか、お聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"建築課長時代になりますが、こうした助成制度を使っていただいて団地内のバリアフリー化の改修を行っていただいているというような事例もあります。いろいろとお声を聞きながら、地域の声に耳を傾けながら、様々な取組を進めていきたいです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"そうしますと、建築課長時代のご経験を踏まえたご答弁がありましたが、これは団地内通路は全てその対象になるのでしょうか。で、若い世代を再び呼び戻そうとする取組というのでしょうか、中堅ファミリー層の方々もこの地域に呼び込んでいくという発想はないのか尋ねました。","respondent":"長尾建築課長、鈴木都市計画課長","answer":"今、私道整備助成のお話が出ておりましたので、私からその点についてご説明いたします。個別に状況を確認しながら対応していくことになるかなとは考えておりますけれども、できる限り、連携しながら進めていきたいと考えております。 あるいは計画に基づいて居住機能を新設するという考えは今のところございませんが、この計画全般のソフト的な取組も含めて、そうしたところにつながっていけばいいのかなというところでの計画立てです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"すみません、時間があれなので、もう１点だけ。２８ページにありました一団地認定の関係なのですけれども、この一団地認定が弊害というか、そこはクリアされるという認識でいいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"都市計画法上の一団地の網を外して、地区計画を外して、地区内の用途上の柔軟性は確保したです。例えば先ほどご説明したエレベーターをつくるような場合に、現在のところ、柔軟性は非常に高まっているというようなところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"ありがとうございました。５０年、６０年に向けて、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"簡単に確認だけ。４０代、５０代の方は住み続けるのであれば、考え方だけ説明を求めました。","respondent":"鈴木都市計画課長","answer":"八潮につきましては、本当に一斉に建物ができて、ある意味、更新時期も同時に迎えるような状況に今後なっていくのではないかと考えています。違う方法でまちづくりを進めていくかは、各建物所有者とも意見交換をしながら、今後出てくる話なのかなです。","id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"声がなかったのかというのを教えていただきたいのと、駐車場の稼働率というのですか、きちんと埋まっているのか。８月にガイドライン策定ですが、３２％というのをどのように感じているのかだけ、説明を求めました。","respondent":"森道路課長、鈴木都市計画課長","answer":"例えば陰になっているだとか、そういったところにはつける可能性があるのですけれども、基本的には区道上には設置していない状況です。防犯上というところもありますけれども、そこまで区道に設置することの必要性というところは… 自治会なり、あるいは管理組合がどう活用していくかというのは、それぞれが今後しっかりとお考えになるのかなというところかと思います。今回３２％ということで、同様の３０％前後の回収率というところで…","id":"exchange-016"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"後でそれでどうなったと言われても、時間がないですけれども、いろいろとご対応をお願いしたいと。防犯カメラは、見通しがいいということで、自治会から要望が特にあるわけではないということですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"これから区が、何か若者を呼び戻すようなアイデアというものを考え、そういう計画というものは絶対に考えられないことなのかどうか。それがあれば、説明を求めました。","respondent":"鈴木都市計画課長","answer":"あるいは、１室借り切って、そうした空間として働いていただくようなことはどうなのだろうという声も聞いたことはあります。多様な世代に入っていただくような取組について、区としても意見交換を重ねていきたいです。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"何か行政側が若者が集まるようなアイデアをどんどん出していく、もしそういうことができれば、またお願いをしたいなと思います。これは要望であります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-02","title":"東京港第９次改訂港湾計画","agenda":"東京港第９次改訂港湾計画","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"品川区との関わりについて確認させていただきたいのですが、まず１つは、全部ではなくて。それら含めて、品川区に係る部分で、今後、２１日に協議していくわけですので、その辺、教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"様々な技術革新で、スムーズに、計画的にトラック貨物を受け入れられるような取組を進めていきますと。現在も進めているところですがと伺っているところです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"今までかかっていた時間がかなり短縮されているというものもあったりして、安さも含めると、どんどん増えるのではないかなと。品川区としてはこういう観点で確認していきたいとか、そういう課題とかがあれば、教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"それに向かって整備を進めていくという基本的なことがありますけれども、この港湾計画も進めていただきながら、所管としては感じているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"船の排気ガスというのですか、今、それはどうなっているのか。公害も含めてですね、必要ではないかなと思っているのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"本編の１７ページの未来へつなぐグリーンポートというところで、様々、港湾の中でも導入を進めていくという位置づけがされているところです。基本的には、陸上電力供給による船舶のアイドリングストップなどという表現がされているところです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"船の、排気ガスと言うのか分からないですけれども、そこの環境規制というのは現状どうなっているのかというのが分かれば伺いたいのと、そこの区の考えも伺えればと思います。","respondent":"鈴木都市計画課長","answer":"申し訳ございません。船舶に関する排気量ですとか、そうしたところの規制があるかどうかというのは、現在、把握してございません。","id":"exchange-023"}]},{"id":"topic-03","title":"大井・西大井地区における密集住宅市街地整備促進事業の開始","agenda":"大井・西大井地区における密集住宅市街地整備促進事業の開始","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"昨年１１月に説明会を実施したということで、そこの参加人数と、どういった意見が出されたかというのを伺いたいと思います。何棟立ち退かなければいけないのかというところが分かれば伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"初めに、昨年１１月に行われました説明会の参加人数ですが、説明会は計２日実施しておりまして、合計で３２名の方にご出席いただいてあります。あくまでも任意でございまして、強制ではございませんので、立ち退くといったようなものではございません。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"そうしたところで合意形成がどこまでできているのかなと思うのですが、区の認識を伺いたいと思います。全体として道路を整備したらどれくらい、あるいは公園を整備したらどれくらいというのは把握されているのではないかと思うのですが、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"合意形成についての考えですが、説明会を実施する前と実施した後では、広くこの事業の導入計画については周知を図っているところです。平成２１年から検討が広く行われておりまして、地域での検討会等でも…","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"それを要望しておきたいと思います。整備計画図がありますが、３１号線を整備していくという前段階にならないようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"そういったところでは、こちらの３本の道路に関しましては、滝王子通り、また、南に関しましては補助３１号線につながるような形になってあります。補助３１号線に関しましては、今回、整備計画をつくらせていただいてあります。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"補助３１号線、ご説明のとおり、整備路線にもなっておりませんし、地域でも反対の声が上がっているというものですので、これは進めないように強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"３０ｍという青っぽい色があるのですけれども、この３０ｍというのは、ここも全部整備対象になるということなのでしょうかということが２点目。補助金とかも含めて、そういう仕組みはどの助成金を使うのか尋ねました。","respondent":"森道路課長、小川木密整備推進課長","answer":"進めていく予定ではおりますけれども、その時期がまだ見えないので、今のところは構想段階という形です。確かに歩くのに支障になる部分がないように、道路の端にしっかりとつけて、安全を確保したいと考えています。 今、我々も引き続き機能強化事業は必要だと考えていますので、今後もまた延伸に向けた準備等については進めてまいりたいと考えています。我々、ご相談に乗らせていただきたいと思いますので…","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"そこにチャレンジするわけですから、先ほど説明会に３２人とか言っていましたけれども、情報は行っていません。東京都、国からの何か助成金というか補助金とか、当てにしているものがあるのかどうかということを確認したいと思います。","respondent":"小川木密整備推進課長","answer":"今年度、令和５年度も引き続きやらせていただいて、粘り強くこの事業の内容については説明をさせていただきたいと考えています。今年度から取組を開始しまして、１０年間かけて、この計画を基にやっていきたいといったところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、取りあえず幅員６ｍというところで示されているのですが、そこだけではないのですよね。出さないというような取組なんかも、ぜひ強烈に進めていただきたいと考えていますので、そこだけご意見ほしいと求めました。","respondent":"小川木密整備推進課長","answer":"この地区に関しましては、委員おっしゃるとおり、道路基盤であったり老朽木造住宅であったりが密集しているところではありますが、我々も本事業、計画を基にしっかりと進めていきたいと考えています。","id":"exchange-030"}]},{"id":"topic-04","title":"大崎駅東口第４地区におけるまちづくり","agenda":"大崎駅東口第４地区におけるまちづくり","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ガイドラインの６ページのところにも書かれておりますけれども、最近、そういったところはどのように考えていらっしゃるのか伺いたいと思います。それと併せて、そういった面も、新しい建物もありますので、合意形成の状況が、そういった話合いとかがされているのかも含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"こうした再開発を行っていく中で、最新の環境に即した建物を建てていくところですので、環境面に配慮して進めていきたいと考えています。合意形成ですが、こちらの地区、今、再開発を含めてまちづくりの準備組合があるというところで…","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"宅地権者、区分所有者などについても、それぞれ２つの地区で何人なのかというところを伺いたいと思います。約９０％弱ということですから参加しているのだと思いますけれども、どのようにお考えなのか、声を聞いているところがあれば伺いたいと思います。","respondent":"中道都市開発課長","answer":"こちらにつきましては、平成１９年に先にこういったマンションを建てたというところで、自分たちは再開発に入らないです。で、今回のガイドライン策定におかれましても、こういった住民の方が参加してガイドラインをつくってきたところです。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料のガイドラインの５ページのところに、やはり再開発を進めていくための要望のように思うのですけれども、区のお考えを伺いたいと思います。そして、これは誰が所有をしているのか、緑道の整備ができない理由などがあるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"地元の方々もそうした地域特性を生かして、自分たちでまちづくりを考えていきたいというところで進めてきたというところは聞いてあります。ですので、そうした水辺の地域特性といったものを活かしたまちづくりを進めていきたいというふうに考えてあります。","id":"exchange-033"},{"speaker":"のだて委員","kind":"意見","question":"様々ご説明いただきましたけれども、いろいろ課題を挙げて再開発を進めていこうというような内容なのかなと、再開発しなければ解決できない内容なのかというふうに受け止めておりますということだけ最後に言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ママチャリ、そういう整備をするとかということも、やはり自転車で来る人たちも含めて構想を練っていただきたいということが２点目。あの問題は、やはり解決できないものなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"飛んでしまいますけれども、あそこを一体的にやるとしたら、やはりそれは継続的な審議をされている、検討されているのではないかなと非常に大きな期待をして質問したいと思うのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"自転車が安全に通れるように、そこは整備していきたいと考えていますので、そうした中で自転車に安全に通行していただければと考えています。橋梁のなかなか接続できない部分ですが、今、区も、毎年そこの部分については協議はしています。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"継続的に協議しているということで要望もされていると思うのですが、やはり諦めずに、区は交渉していただきたいというふうに思います。最後に、喫煙所、この周辺は喫煙所の問題も結構あって、解消されたのでしたかという確認をさせてください。","respondent":"長尾建築課長","answer":"コンテナ型喫煙所につきましては、大崎駅の東口側に最初に１つできまして、また今度、西口側のほう、バスの停留所のある付近に今年の４月にできたところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"確認","question":"喫煙所、東口のほうの喫煙所も整備されて解決しましたという認識でよろしいですか。もう一度、確認させてください。","respondent":"長尾建築課長","answer":"東口に設置されましたコンテナ型喫煙所につきましては、もともとなかった場所にコンテナを設置しまして、令和３年度に設置されているところです。道路上の部分に設置するに当たって、私が把握している範囲でお答えさせていただきました。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"それからそこに集うわけですから、ごみの問題、それからトイレの問題がいろいろ絡んでくると思うのです。なので、それは先々を考えていただいて、まちづくりをしていただければなというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"ここでの１つの特徴は、水辺に親しむということで親水性を求めてまちづくりが行われていますが、そういう要望は行うことはできるのでしょうか。というか、ぜひしていただきたいと思うのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"１８ページの左下、Ｂの部分、鉄道敷沿いの壁面後退の話です。見られるというところもありますので、ＪＲのほうにもそういった要望を伝えて、一体的なまちづくりを進めていきたいと考えています。","id":"exchange-040"},{"speaker":"田中委員","kind":"意見","question":"ぜひ、ＪＲのイメージアップにもつながると思いますので、私は積極的に協力していただけるだろうと思いますので、そういった視点での働きかけもぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-05","title":"戸越公園駅交通広場に関する都市計画手続き","agenda":"戸越公園駅交通広場に関する都市計画手続き","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それで、説明会が２月に行われたということで、そこで様々意見が出たと思うのですけれども、そういった住民の方の声があったのか伺いたいと思います。併せて、都市計画案の意見書の受付もしたということですので、そこでもどういった意見があったのか伺います。","respondent":"大石まちづくり立体化担当課長","answer":"駅前広場と取付道路で現時点で約２６画地、今後の都市計画決定後に用地測量を実施し確定するものですので、現時点では２６画地を予定しています。現在、７月下旬の都市計画審議会で改めて詳しい内容は説明いたしますので、今回のこの場での発言は控えさせていただきたいと思いま…","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"正確な人数は分からないということですけれども、２６画地が関わるということで、やはり大きな住民の方たちの暮らしが変わるということです。むしろ自動車中心のまちづくりになっていくのではないかと思うのですが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"効率的に事業を実施するという観点から、タクシー等々の交通機関の連携や交通アクセスの改善など、必要性としては認識しています。１つは、まちを歩きやすくするということも１つウォーカブルという観点がありますので、今後引き続き関係機関と協議してまいりたいと考えておりま…","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"それに沿った計画を進めていくということになってしまうと思います。そうすると、実際、区が掲げているウォーカブルなまちづくりということにはならないと思うのですが、改めて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"補助２９号線、こちらは特定整備路線といたしまして、延焼遮断帯の形成や避難路の確保といった大きな目的があります。そういった課題も１つありますので、歩きやすい街並みをしっかりと形成するために、関係機関と今後協議してまいりたいと考えています。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は、２９号線は必要ないと考えていますけれども、その歩きやすいまちづくりという意味でも、道路ができることによって、交通量も増え、歩きにくい、事故の可能性も増えていくというふうになると思いますので、区としても、こうした認識も持ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"この立体化はいつ頃と想定されているのでしょうか。何となくこのまちづくりという中で、その時期的なところが少し見えないので、どういうことを想定されているのかお聞きしたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"現時点で令和７年度の完成という形で目指していると聞いておりますので、恐らく、補助２９号線のほうが先に出来上がるのかなと思ってあります。１０年とは言わないのですけれども、事業認可取得後にしっかりと設計をした中で、その辺が明らかになってくるものと考えています。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"今度、反対側、駅前のほうは、まだ今、再開発を進めておりますけれども、そこは、東急ですか、スーパーが入るのですよね。それを踏まえて考えていただきたいというふうに思いますが、その考え方についてお聞きしたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"現時点だと、交通広場が道路の指定になりますので、交通広場内での駐輪場の設置はなかなか難しいのかなと思ってあります。今後検討していくことになろうかと思いますので、１つの意見として伺いながら、しっかりと協議に臨んでいきたいと考えております。","id":"exchange-047"}]},{"id":"topic-06","title":"粗大ごみの品目別手数料の改定","agenda":"粗大ごみの品目別手数料の改定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それは分かりました。それともう１つ、区分２以上の改定というのがついているわけですが、この違いが分からなかったので伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"申し訳ございません。区分２のほうは、差し替えのほうの資料を見ていただければと思いますので、よろしくお願いします。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"すみません、今の机上配付と、事前にというところでは、何が違うのですか。どれを対応させればいいか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"以前の配っている資料の一番最後のページを省いているものが机上配付された資料ですので、よろしくお願いいたします。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"ただ１点、お願いしたいのが、ホームページのほうで収集日とかを選ぶわけです。なので、そこの工夫は何かありますか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"そういう場合に、今年度、粗大ごみシステムを全面改修する予定になっております。こういった部分、少しでも重視しまして、いろいろな品目がインターネットで選べるような形でやっていきたいと、このように考えております。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"粗大ごみ、ごみの収集で受け取れない、例えば砂とかも受け取ってくれるのです。なので、そこら辺もご案内をしていただくと、より分かりやすくなるのかなと思いますが、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"月２回ほど、地域の３１か所ぐらいの学校等を利用しまして、そういったものをシルバー人材センターの方に依頼しまして回収する機会を設けております。こういう部分につきましては、今後も周知方法をいろいろ工夫しながら、皆様に伝えて利用していただくように努力してまいります。","id":"exchange-051"}]},{"id":"topic-07","title":"自転車ヘルメット購入助成申請の受付開始","agenda":"自転車ヘルメット購入助成申請の受付開始","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点は、保険にもよると思うのですが、幾らぐらいかかるものになるのでしょうかということが１点。それは信じていいのでしょうかという、少し不安になっているのですけれども、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"区民交通傷害保険ですと、自動車損害賠償保険については１,４００円からの掛金で対応しています。あごひもは必須と考えていますので、可能な限り、あごひものついたヘルメットを推奨していきたいと考えております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"ですから、２,０００円の助成はあるという理解でいいのでしょうかということが１点と、チラシに書いていないですよね。ただ、助成金については、こういうマークがあれば大丈夫ということでいいのか尋ねました。","respondent":"工藤交通安全担当課長","answer":"ゆっくり、来年の３月３１日まで期限がありますので、保険に入っていただいた後に申請をしていただければと思います。それと２点目、あごひもがついたものということを推奨はするのですけれども、助成対象ということで受け付けたいと考えております。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問・要望","question":"そこはこれから問題として起きるかなというふうに思いますので、そこも注視してほしいと求めました。これは意見という形でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"周知を十二分にしていただきたいということで、もう端的に加えていただきたいというか、ぜひやっていただきたいという意味で伺っておきたいと思います。","respondent":"工藤交通安全担当課長","answer":"この制度の周知ですけれども、自転車商協同組合に未加盟の自転車商に対する周知ですが、何件か自転車商のほうからも問合せが来ております。こういったところに対しても、区としましては、チラシを配布し協力を求めていくというような形で今後進めていきたいと考えています。","id":"exchange-055"}]},{"id":"topic-08","title":"バリアフリー工事（ゼームス坂通り３工区）","agenda":"バリアフリー工事（ゼームス坂通り３工区）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それをなくして、下の２工区のような景観というか、そういう状況になっていくという理解でよろしいでしょうか。通路側との境界線の段差は、これは維持されるという、そういうイメージでよろしいのか尋ねました。","respondent":"森道路課長","answer":"それから、歩道と車道の段差ということですけれども、基本的には１５cm以上、車道と歩道の間に高さの差を設けなさいというふうにはなっています。その間のブロックを１５cm確保していって、その１５cmは確保されているということで…","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"ただ、民家のところとか、駐車場が道路側にあるとかというところは、あれは坂というか、斜面というか、ブロックで１５cmというのではなくて、そこはお宅のほうと協議しながらの整備という理解でよろしいか尋ねました。","respondent":"森道路課長","answer":"今では、そういった部分で歩道が少し下がったり上がったりというような勾配が出てきている、そういったところが課題だというふうに考えています。それによって車が入りやすく、しかも、歩道は波打たないというような形でつくっていきたいと思っています。","id":"exchange-057"}]},{"id":"topic-09","title":"Ｐａｒｋ－ＰＦＩ制度を導入する公園（東品川海上公園）","agenda":"Ｐａｒｋ－ＰＦＩ制度を導入する公園（東品川海上公園）","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"この間、利用者アンケートは１項目出ておりますが、利用者の方のお答えはどのような答えだったのかということを伺いたいと思います。ほかにどういった調査をされて、提案も含めて、どういったものが出てきているのかというところを伺いたいと思いますとの意見を述べました。","respondent":"高梨公園課長","answer":"具体的なところですと、カフェであるとか、レストランといったような答えがございました。公園の中に農園を設置して貸し農園、ドッグランをつくって、ドッグランの運営を収益施設として行いたいというような提案もあったところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"今回、地域からの声があったのか、どういった形で望まれているのかというところを伺いたいと思います。この東品川海上公園で施設をつくるということになるのかなと思うのですが、それはどのくらいの規模、何m2ぐらいを見込んでいるのか伺います。","respondent":"高梨公園課長","answer":"説明の中でも申しましたが、水辺の環境と地域の方々のイベントとのコラボレーションを期待できる公園であると区としては考えているところです。区として何m2ということで縛る予定はございませんが、カフェ等の収益施設を設置する際には…","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"マーケットサウンディング調査、それぞれの公園の中で、どういう観点で参画意向のある公園ということにされているのかなと思うのです。どこまで調査して、こういう結果になっているのかなと思うのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"細かな公園の立地であるとか、そういった説明は特になく、事業者のほうで各公園を調べていただいて提案していただくといったところでございました。飲食業を、レストラン等を行っている、そういった業者が手を挙げているといった例もございました。","id":"exchange-060"},{"speaker":"西本委員","kind":"提案","question":"その中で、やはりこちらサイドでの提案ということもある程度必要なのかなと。この前の段階で、もう少し品川区の意見を言ってもよかったのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"今、また、一緒に取り組んでいただけるような事業を行っていただく事業者を公募していきたいと考えているところです。どの程度の民間事業者の方が興味を持ってくれているのかというようなものを図るといったところで区としては考えているところです。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"何回も言いますけれども、交通の便ということを考えると、五反田とかのほうが交通の便はいいのです。Ｐａｒｋ－ＰＦＩの制度を見ながら、やはり品川区にとってという形でいろいろと工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"公募の指針をこれからつくっていくということで、地域の声、意見を反映させていくということなのですが、どういった形で反映させていくのかというところを伺いたいと思います。","respondent":"高梨公園課長","answer":"外部有識者等を加えた評価選定委員会を組織して、その中で議論をし、決めていくというようなステップです。検討中ですが、今、検討しています。","id":"exchange-063"}]},{"id":"topic-10","title":"（仮称）勝島人道橋およびしながわ花海道における都市計画決定","agenda":"（仮称）勝島人道橋およびしながわ花海道における都市計画決定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"川幅が狭まっているわけですけれども、それによって船の通行ですとか、そういった影響はないのかどうか伺いたいと思います。私が伺った中では、今回この整備が２０億円かかるということで、そうした声が区のほうには届いているかどうか伺いたいと思います。","respondent":"高梨公園課長、森道路課長","answer":"港湾局とも協議を行いまして、一定、恒久的に公園として担保ができるというようなところが１つ大きな理由としてはあります。都市計画公園となった場合でも、皆様にお使いいただく状況としては… 運河幅自体を３０ｍ以上確保しなさいということも、港湾局のほうからそういった条件を出されておりますので、それに従った設計をしています。１０月に行いました説明会の中でも、２０億円をしっかりと…","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、結局、花海道ですから、向こう側も道があるのでしたか。あそこの発展をしていただきたいという思いがあるのですけれども、協力体制とか、調和性とかについてはいかがか尋ねました。","respondent":"高梨公園課長","answer":"こちらの花海道はＮＰＯということで、地域の皆様、町会の皆様が主体となった団体に区からの委託をして管理をして頑張ってやっていただいてあります。説明会等もありますけれども、にぎわいを生み出して発展していけるような形で区としても支援をしてまいりたい…","id":"exchange-065"},{"speaker":"西本委員","kind":"質問・要望","question":"説明会が２６日にあるということなのですけれども、やはり発展的なイメージが沸くように、ぜひ説明をしっかりしていただきたいと思っています。なので、そうではなくて、それをさらによくしていくよという感じで、ご説明のほど、お願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"１つはこの人道橋ということと、新浜川公園の整備といったことも基幹事業ということで捉える中で国庫補助を求めて取り組んで、突然でもないのですが。４０％国庫補助を求めているという流れがあったと思っていたのですが、現実的に国庫補助を受けられないということでこういう回答をされたのか。","respondent":"森道路課長、高梨公園課長","answer":"１０月２０日の説明会の中では、ルート３というお話も参加された方からはいただきました。そういった中で、実際に橋ができるのはまだ３年先ですので、地域の方の意見を伺いながら協力していきたいというふうに考えています。 私から１点補足をします。この計画の中で整備を行う予定としておりまして、資料には記載がございませんが、しながわ花海道についても再整備を行うという計画でいるところです。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"総額２０億円としたときの最終的な決定は、１億８,０００万円以上の工事なので、もう一度改めてご説明ほしいと求めました。","respondent":"森道路課長","answer":"１０月２０日に開催した説明会の後、そういった部分のプラスの都からの支援をいただきながら、区の費用については抑えていきたいという趣旨で書かせていただいているところです。","id":"exchange-068"},{"speaker":"田中委員","kind":"質問","question":"分かりました。この４割プラス財源確保というような観点も含め、都市計画公園にするという、そういうことか尋ねました。","respondent":"高梨公園課長","answer":"これから都との協議になりますけれども、獲得できる補助金に関しましては積極的に活用していきたい、このように考えているところです。","id":"exchange-069"},{"speaker":"田中委員","kind":"質問","question":"都市計画公園の指定を受けるに当たりまして、現状の児童遊園の部分だけ、花海道で使っている護岸のところだけでも指定はされるのでしょうか。要は、今回の人道橋をつくって初めて都市計画公園として認定されるのか、人道橋がなくても認定されるのか、そこら辺はいかがか尋ねました。","respondent":"高梨公園課長","answer":"都市計画の決定に際しましては、東京都との協議等もありますけれども、人道橋がないと都市計画公園にはならないといった規定はございません。この人道橋の架設を機に、一体として都市計画公園にしていこうというところで、区として考えているところです。","id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"別の観点で確認をしたいのですが、恐らく確認はとれていると思いますが、この観点からの協議はなされたのか尋ねました。","respondent":"森道路課長","answer":"それも与条件として検討しておりますので、それについては、今の設定条件としては問題ないというふうに考えています。区としては、それに合わせて東京都のほうで、そういった将来の海面上昇に対して対策を講じていくというようなことも協議の中で確認をしています。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"基本計画は５.９ｍに対して、５.６ｍの高さの人道橋という部分では、何かあったのでしょうか。その考え方をお聞かせほしいと求めました。","respondent":"森道路課長","answer":"今、ご紹介いただきました計画について、１００年後のお話です。それを踏まえた護岸の整備計画を立案していくというようなお話をされていますので、まずは情報共有を図っていきながら進めていきたいと思っています。","id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"２０億円かけて人道橋を造って回遊性を求める、品川区の年間の一般会計予算の１％分の金額をここに充てることの評価、その上で真剣に判断をしていかなければいけない事業ではないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"}]},{"id":"topic-11","title":"しながわ水族館リニューアルに向けた今後の進め方","agenda":"しながわ水族館リニューアルに向けた今後の進め方","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この間もそういった形でやってきたと思いますので、ぜひそれはやってほしいと求めました。指定管理者制度にしていく理由を伺いたいのと、そうすると、何が変わるのか伺います。","respondent":"高梨公園課長","answer":"例えば直営で行うには非常に困難であるというもので、現在もですが、民間事業者の力を借りて運営をしている状況です。リニューアルに際しましては、指定管理者制度を活用して事業者を選定してまいりたい、このように考えているところです。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"利用者にとって変わる部分があれば伺いたいと思います。何かできなかったハードルがあるのかどうか伺いたいのと、比較すると、どちらが高いか安いのかを伺いたいと思います。","respondent":"高梨公園課長","answer":"１年ごとの契約更新ですので、長期間しっかりと水族館を管理していただけるという安心につながる制度なのではないかというふうに考えてあります。現在検討していますけれども、それまでしっかり区としても検討し、このように考えているところです。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"指定管理者のモニタリングは、限られた資料しか出されないという状況になっていますので、そこは資料をしっかり出してほしいと求めました。例えば、そういったことをやるようにするためなのか、何かそういった区の狙いがあるのか伺いたいと思います。","respondent":"高梨公園課長","answer":"一定期間、長期間しっかりとした事業者にお任せできるというところと、透明性が高いといったところがメインかなというふうに思ってあります。ご説明をしていかなければいけないということも考えていますので、また…","id":"exchange-076"},{"speaker":"西本委員","kind":"確認","question":"確認を少々したいと思うのですが、しながわ水族館の皆さんの取組を見て、今回のリニューアルにおいての区の思いを改めてお聞きしたいと思います。それから、指定管理者制度になったということになると、今までは業務委託だったのか尋ねました。","respondent":"高梨公園課長","answer":"今までの３０年間も愛していただきましたけれども、リニューアルをしっかりと進めてまいりたい、このように考えているところです。万が一、どういった補填の仕方があるのかといったところについては、事業者としっかりと対話をして協議してまいりたいというふうに考えてあります。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"いつまでいることができるのでしょうかということで、それから親も含めて、一度は見にいってほしいなと思うのです。イルカはどうなってしまうのかと、いろいろ考えられていると思いますけれども、その辺のイルカの先行きのお考えをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"そういったイルカとのお別れセレモニーであったり、移転先の候補等についても、前向きに検討してまいりたいというふうに考えてあります。シンボルマークも含めて、リニューアルに際しましては…","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"３番の設計委託ということで確認なのですが、それで、設計業者は運営準備事業者が選ぶという形になるということですよね。意思疎通という意味では、新しい視点でという部分もあるかと思うのですが、あえてこれを使った理由を改めてお聞きしたいと思います。","respondent":"高梨公園課長","answer":"広報につきましては、委員のご提案も含めて、広く区外から訪れる方々へも含めて行ってまいりたいと考えています。その設計事業者と運営事業者との連携はいいのですけれども、その計画の中で発注者として入って主体的に進めてまいりたいというふうに考えてあります。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に、いろいろなところでご協力をいただいたなというふうにすごく思っておりますし、やはりノウハウはかなり持っておられると思うのです。決して肩を持つわけではないのですけれども、今までの歴史とか経験なども十分に加味した形でお願いしたいというふうにお願いをして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"耐震化事業のほうでお聞きしますが、この一時滞在施設等で１９か所は、これはどこに、どういう条件の下でここになるのでしょうか。下水管はたくさんあると思うのですけれども、この１９か所は、どういうところでの１９か所なのか説明を求めました。","respondent":"北原河川下水道課長","answer":"今実施しているものでして、そちらを対象に実施するということで、１９か所をやる予定でおります。合わせて６０か所程度を、今、調査をしています。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"これ、避難所の、例えば小中学校の避難所のところも、たしか同じような工事がなかったでしたか。下水管の補強という形であったような気がしたのですけれども、それと同類の工事ですという理解でよろしいか尋ねました。","respondent":"北原河川下水道課長","answer":"避難所につきましては、過去に実施を、下水道局と品川区で役割分担をしながら進めてきておりまして、そちらと同様の工事をすることによって、こちらでも下水道管の機能を地震時も確保できるという工事になります。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"これ、以前に避難所のところで耐震化事業があったときに、避難所のトイレの問題がいろいろあって、大分それが回避できるというふうに思ったのです。ある程度、工事がなされていて、かなり耐久性がありますという認識でよろしいのか尋ねました。","respondent":"北原河川下水道課長","answer":"平成２５年ぐらいまでに避難所に選定されている箇所を順次やってきまして終わっておりまして、全て終わっているわけではないのですけれども、かなりの部分において地震時も排水ができるようになっております。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問","question":"新たに１９か所ということなのですが、そもそも東京都下水道局がもっと早くしているべきと思うのですが、何か理由みたいなのはあるのか尋ねました。","respondent":"北原河川下水道課長","answer":"２３区たくさんありますので、下水道局も施工しますし、品川区としても受託して早期にこういった耐震化が図れるように進めてきたところです。併せて、また追加されたところも順次進めていくというところになっております。","id":"exchange-084"},{"speaker":"田中委員","kind":"提案","question":"率先して今回のような形で受託をして事業を受けて、最小限の被害に抑えるという取組は、今後もぜひ続けてほしいと求めました。１つ提案というか、どこなのでしょうか、これは要望としてお伝えさせてほしいと求めました。","respondent":"北原河川下水道課長","answer":"浸水の原因になったりしないという側面もありますので、本日いただいた意見も参考にしながら、できることを進めていきたいと考えています。","id":"exchange-085"},{"speaker":"若林委員","kind":"質問・要望","question":"再構築事業のほうで、まず、下の東五反田一丁目・二丁目の、いわゆる対象路線と対象流域の数字が抜けているのはなぜでしょうかということが１つ。老朽化に伴う道路陥没というところのご説明、それから、排水能力の増強、この２つの目的について、もう少し重ねての説明をお願いしたいと思います。","respondent":"北原河川下水道課長","answer":"ですので、左の図と右の図の合計がこの対象４４６ｍという形になりまして、少し分かりづらい資料でありまして、申し訳ございませんでした。大体８０％ぐらいが下水道管の中に入ってきてしまうということで…","id":"exchange-086"},{"speaker":"若林委員","kind":"質問","question":"そうすると、なぜ東五反田と東品川が一緒の工事なのですかという単純な疑問について、お答えできたらお願いします。そういう意味なのでしょうかというお尋ねをさせていただいて、もう１つ最後に、参考にお聞きしたいと思います。","respondent":"北原河川下水道課長","answer":"事前に調査を行いまして、また、少し飛んだ位置でこういった２つのエリアを合わせたようなものが結果的に出てしまうことがあります。そちらを順次進めてきておりまして、今後、その第１期エリア以降に第２期のエリアとして進めていくということになっております。","id":"exchange-087"},{"speaker":"若林委員","kind":"確認","question":"その目黒川の北側、川は蛇行しているので、場所によっては西になったり、東になったりすると思うのですけれども、ざっくり北側が古くて、南側が比較的、管の新しさでいうと新しいという理解でいいのか確認をします。","respondent":"北原河川下水道課長","answer":"目黒川の左岸側が古い、右岸側から大田区側といいますか、そちら側が比較的新しいということになります。","id":"exchange-088"}]},{"id":"topic-12","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"従前どおり２泊３日ということなのですが、今後、コロナの感染状況を踏まえ、できれば日帰りにしたほうがいいのではないかというふうに、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":91436,"voices":276}},{"id":"r05-20230704-9","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"文教委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)城南第二小学校改築工事","agenda":"はじめに、(1)城南第二小学校改築工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"実際には省エネ効果があるものなのかというところを伺いたいのが１つと、区教委が実際にどう関わっているのかというのを伺いたいのですが、進めていっているのかというのを伺いたいと思います。","respondent":"森学校施設担当課長","answer":"重力換気という考え方もありますので、換気が自然にできるという考え方もございまして、ＺＥＢ化というものを学校建築にも導入しているところです。教育委員会との関わり方ですけれども、基本設計、実施設計ともに、定期的に会議を行いまして、定例会議を行って…","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"この城南第二小学校の設計についての一番事業者に伝えたことというのですか、重要視したことというのは幾つかあったのでしょうか。それを伺いたいと思います。","respondent":"森学校施設担当課長","answer":"まず１つは、体育館を２階に配置、体育館を２階にしてほしいというところ。それと、グラウンドを広く取って、子どもたちの活動の場である校庭を広げていこうというのをコンセプトに押し出していったところです。","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"図面からすまいるスクールの位置が確認できなかったので、そちらをお示ししてほしいと求めました。こちらも車椅子とかが通れる十分な距離が、図面だけからだと分かりにくいので、十分な幅があるのかといったところもお伺いしたいと思います。","respondent":"森学校施設担当課長","answer":"２階の右角のところ、こちらがすまいるスクールのところというふうに、検討を今のところしております。各階に車椅子対応のトイレを設置しておりまして、１階には、おむつ替えのシートも含めましたバリアフリートイレを設置しております。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけお伺いをします。サービスというか、そういうのはないのかなと思っているのですが、その辺で何かあれば説明を求めました。","respondent":"森学校施設担当課長","answer":"工事現場のほうで、少し時間をつくりまして、見学をしていただくというような対応もしてみました。どこかの部屋の壁の色であったり、何か工事に参画できないかというのを検討しておりまして、工事があることでの新たな学びについても検討しています。","id":"exchange-004"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"では、何かほかの子たちと違う特別な何かができたねというものを１つでも残していただけるといいかなと思うので、ぜひ進めていっていただきたいなと。これは要望で終わりますが、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"提案","question":"これは設計事業者からの提案もあると思うのですけれども、地域の要望も兼ねてこういうふうなテラスの観客席というようなことを基本設計、あと。それを確認させてくださいとの意見を述べました。","respondent":"森学校施設担当課長","answer":"多くなってまいりますので、体育館が２階ですので、バルコニーを設置しています。過去は６メートルと低いネットもあったのですが、飛び出しがございましたので、高くして近隣の皆様の安全を保つというふうに考えてあります。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"城南第二小学校の改築をぜひ推し進めてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったところをお聞かせいただきたいのと、具体的にどういった遊具があるのか、お聞かせください。そういったところと、全体の品川区の学校の考え方として、部屋の数というのはどういったお考えなのか。","respondent":"森学校施設担当課長","answer":"さらに増えた場合には対応ができるようにも、案としてはあります。基本的には、学校の教室数は、地域の児童・生徒が通える学校を用意していくという考え方で設計をしています。","id":"exchange-008"},{"speaker":"せお委員","kind":"意見","question":"それはそれで必要だったりして、そういったところも総合的に今後も検討してほしいなと、そういったところは考えているところです。部屋数は理解いたしましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ目は、これ、特別支援と書いてあるのは、特別支援教室だという理解でよろしいでしょうか。３つ目は、現在でも城南小学校は厳しいとお聞きしているので、そこをお尋ねします。","respondent":"森学校施設担当課長、柏木学務課長","answer":"基本的に特別支援教室ですので、少し離れて落ち着いたところというふうに考えて、この場所に設定しております。昇降口の部分もかなり広々としておりますので、小規模な選挙の場合はこちらでも投票は可能であろうと考えて… 城南小学校につきましては、就学人口を考えると、学校選択で入るのは非常に厳しいかなと考えています。やってみないと分からないところがありますけれども、ほかのところで受入枠があれば…","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから、選挙も分かりました。大丈夫とおっしゃっているので、そういうふうにご答弁をいただいたので、伺ったということにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"提案","question":"何点かご質問させていただきたいのですが、提案はするけれども、教えてください。取りあえずそれだけ伺いますとの意見を述べました。","respondent":"森学校施設担当課長","answer":"それと、太陽光パネルもそうですし、あと風力と太陽光が合わさった照明器具、そちらも外部に設置はする予定です。なおかつ、それぞれの階段の距離がありますので、どちらかが避難できない場合でも、避難できるというふうに計画はしています。","id":"exchange-012"},{"speaker":"吉田副委員長","kind":"確認","question":"さっきもう１個聞き忘れたのが、それから、工事中の学校に通う子どもたちへの安全の確保というのはどのように。ここではないのかもしれないですが、安全の確保だけは何か確認しておきたいなと思って、お答えになれる範囲で伺いたいと思います。","respondent":"森学校施設担当課長","answer":"これは北側になったりという形で、常に同じ面からできる限り出入りしないような形で、距離を保って工事を進めていくというふうに考えてあります。それと、近隣の皆様、それから、児童、保護者の皆様にも、工事の説明会を、契約が決まった後に速やかに開催する予定です。","id":"exchange-013"}]},{"id":"topic-02","title":"令和６年度新入学者の受入枠","agenda":"令和６年度新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"先日の文教委員会では小学校で６６人と、中学校では４２人ということだったと思うのですが、もう少し聞かせてもらえればと思いますとの意見を述べました。","respondent":"柏木学務課長","answer":"区内転居ですが、言葉どおり、区内の中で、通学区域が変わったところに引っ越した方です。城南小学校が指定されていたのですが、その後、城南第二小学校の学区域に引っ越しをされたとかという方になります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"この区内転居の理由とかというのは、つかんでいたりするのでしょうか。何か主な傾向とかがあれば、それを伺いたいと思います。","respondent":"柏木学務課長","answer":"理由ですが、すみません、そこまでは把握はしておりません。要は各ご家庭の事情としか、すみませんが申し訳ございません。","id":"exchange-015"}]},{"id":"topic-03","title":"「品川区学事制度審議会」の設置","agenda":"「品川区学事制度審議会」の設置","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"具体的には、区教委としてはどういう環境のことを考えているのか、お伺いしたいと思います。それと併せて、諮問を７月にするとありますが、諮問の内容について伺いたいと思います。","respondent":"柏木学務課長","answer":"子どもたちが多く過ごしているという状況が学校によってはありますので、そういう部分を排除していくという部分が、まず１つ目かと考えています。諮問の内容ですが、今、最終的な決定を取っているところですが、所掌事項にありますように…","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"やはり非常に大事な教育環境の確保だなというふうに、説明を聞いても思いました。この原因というのは区教委としてはどういうふうに考えているのか、伺いたいと思いますし、区教委としては今どこだと考えていらっしゃるのか伺います。","respondent":"柏木学務課長","answer":"児童・生徒、就学人口が増えている原因ですが、まずは品川区が住みやすい、子育てしやすいということが原因の１つかと考えています。次に城南小学校、大井第一小学校、この辺が増えている地域になりまして、特に城南小学校につきましては…","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そういう地域の文化とか伝統にも関わってくる案件ですから、これは公開で行うべきだと思うのですが、それはなぜ行わないのか。私たちは元から、学事制度審議会の中でやはり議題にしていくべきだと思うのですけれども、それについても伺いたいと思います。","respondent":"柏木学務課長","answer":"ただ、先ほども説明の中で言いましたとおり、要点筆記の形になりますけれども、ホームページ等で公開はいたします。その変更については、令和２年度の入学者から適用をしている状況になります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"その審議の過程というのですか、どんなことが今議論されていて、どういうことが論点になっているのかというのを共有しながら案をつくっていく。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"質問","question":"このパブリックコメントを実施するという事前の周知といったところではどのようにされているのか、またどんな工夫をされているのか、お伺いしたいと思います。","respondent":"柏木学務課長","answer":"事前にパブリックコメントをしますという周知というのは、あまり記憶がないのですけれども、ただ、ホームページ等で要点筆記等の形になりますけれども、そういう部分で事前に、当審議会につきましては周知ができるのかなとは考えてあります。","id":"exchange-020"},{"speaker":"ゆきた委員","kind":"質問","question":"では、パブリックコメントについては、ホームページで発信された際に、区民はその際に認識されるということで間違いないでしょうか。お伺いしたいと思います。","respondent":"柏木学務課長","answer":"私もそのように認識をしています。","id":"exchange-021"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"よりこのニーズが求められているところに対してパブリックコメントが周知されますよということで、要望で、そうしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"ちょうど中間報告みたいなものをしたことがあったかもしれないですが、その点について今回はどうなのでしょうかというのが１つ。城南小学校学区、住みたいとか子育てをしたいというわけで移り住んできているのではないというふうにおっしゃったのですが、そうなのか尋ねました。","respondent":"柏木学務課長","answer":"１つは、中間報告ですが、適宜、委員会には、審議の状況等についてはご報告をしたいと考えています。そうすると、やはり品川区全体として評価をされているというふうには考えてあります。","id":"exchange-023"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"できるだけ長く期間を取っていただきたいなというのが１点と、しかるべき方たちには、パブリックコメントを募集中ですよ。できたら長く取っていただきたいというのと、今、その辺についていかがか尋ねました。","respondent":"柏木学務課長","answer":"最初にパブリックコメントの時期ですが、今、１２月中を予定しているということで、まだ時期等については決定はしてございません。パブリックコメントの期間を長くということと、あと周知の方法については、審議会等も含めて少し検討させていただきたいと思います。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"長くて１か月ぐらいかなと認識しているのですけれども、できるだけ長く取っていただきたいというのと、ぜひ考えてほしいと求めました。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-04","title":"自閉症・情緒障害特別支援学級の新設","agenda":"自閉症・情緒障害特別支援学級の新設","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この原則以外の例外というのは例えば何なのかなというのを伺いたいのと、実際に１人で通学するのも難しいのか、諦めざるを得ないと思うのですよ。そういった家庭や児童にも手だてを講じるべきではないかと思うのですが、いかがか尋ねました。","respondent":"唐澤特別支援教育担当課長","answer":"保護者と学校が相談の上、少し様子を見てみようかなという対応というのは、検討の余地があるのかなという形で考えております。そうしたものなども連携しながら対応していく必要があると認識しておりますので、保護者の方に丁寧な説明をしながら進めていきたいと考えています。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。なかなか親の状況が許さないとかという場合もあるかもしれないので、そこは子どもの利益最優先で、ぜひ進めていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だから、そういう特別な支援なのだから、そこは本当にその移動支援を、何とかうまく組み合わせていただきたいなと思います。本当に連携をしていただければなと思いますが、もし最後何かあれば、そこだけ説明を求めました。","respondent":"唐澤特別支援教育担当課長","answer":"新設するに当たって、就学相談、転学相談等々で説明することにはなっているのですが、特別支援教室も、この対象となるお子さんというのはまず利用する可能性もありますので、そうしたところ含めて、丁寧に説明できればと考えています。","id":"exchange-028"},{"speaker":"せお委員","kind":"質問","question":"２番目のところですが、保護者が支援学級がいいと言った場合とかはどういった対応になるのか、そこを教えてください。それをお願いします。","respondent":"唐澤特別支援教育担当課長","answer":"就学相談につきましては、こちらの就学相談での対応もありますが、保護者の方のニーズも併せて大切なことです。特別支援学校に適になった際に、保護者の方とやはり丁寧な説明、話をしながら進めていければと考えております。","id":"exchange-029"},{"speaker":"せお委員","kind":"質問","question":"結構そういう方でも特別支援学校ですと言われる方もいらっしゃると思うのですが、そういった方は全然いないという理解でいいでしょうか。両方持っていらっしゃるお子さんで特別支援学校と言われる方もいらっしゃると思うので、そういったパターンはどういうことになるのか尋ねました。","respondent":"唐澤特別支援教育担当課長","answer":"自閉症・情緒障害特別支援学級ですが、まず、対象としてはそこが前提になってまいります。丁寧な説明をしながら、保護者のニーズに寄り添いながら対応していく、このような形になってまいります。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問・要望","question":"私からも要望ですが、転学相談のときから、障害の福祉のほうとかと連携してぜひそこも相談に乗っていただけるとありがたい。ここは要望しておきますが、そこのところを相談できなかったとか、そこはぜひ丁寧に相談に乗っていただけたらと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"品川区として相当強く要望させていただいて、５年と続いているのです、この流出が。６年になるときに、都のほうに言っていくのかというところを少しお尋ねしたいのと、その２点をお願いします。","respondent":"中谷指導課長","answer":"品川区として特別支援教育を重要な施策として進めていく上においては、しっかりとそのあたりを強く要望していきたいと考えております。特別支援教育に係る知識をしっかりと研修などの体制でもって身につけていただくということ、今、強力に進めていきたいと考えております。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"最後に１つだけ。ですから、品川区に来ていただくようなことをお願いしたいのですが、最後にそれだけ。","respondent":"中谷指導課長","answer":"かなうというところもありますので、１つの選択肢だけではなく、複数で進めてまいりたいと考えています。","id":"exchange-033"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そこに行って、区教委としては保護者の付添いは求めないというのを約束していただいたというふうに認識しております。生活者ネットワークとしてずっとインクルーシブ教育を求めてまいりました。","respondent":"唐澤特別支援教育担当課長","answer":"やはり安全面を第一に考えてというところで、ここは考えていければと考えています。ただ、保護者の方の不安等につきましては、やはり引き続きこうした就学相談、転学相談の場で丁寧な説明をしながら、対応していきたいと考えています。","id":"exchange-034"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ただ、やはり学校での付添いとかそういうことも求められながら、保護者の方が、自分が付き添いたいとおっしゃるケースもあるのは把握しております。やはり基本は、ほかの子どもたちと同じような対応をされるべきというふうに、改めてそのことだけは申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]},{"id":"topic-05","title":"大原児童センターの休館","agenda":"大原児童センターの休館","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改修工事の内容について、もう少し教えていただきたいのですが、。","respondent":"大澤子ども育成課長","answer":"今回の改修は、中身だけの改修になりますけれども、大きなところとしては、エレベーターの設置を予定しています。","id":"exchange-036"}]},{"id":"topic-06","title":"令和４年度子ども・子育て会議","agenda":"令和４年度子ども・子育て会議","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"第３回で、今年度の第１回にもこういった報告もあったようですが、少しお聞かせほしいと求めました。","respondent":"今井保育教育運営担当課長","answer":"お問合せの内容についてです。その他の保育の役割についての説明など、区で作成する子ども・子育て支援事業計画全般的に関わる今後の動きなどについて、ご説明いただいたものです。","id":"exchange-037"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"せお委員","kind":"質問","question":"質問ですが、行政視察において、多様な家族の形だったりライフスタイルの形だったりに合わせて、１泊にするとか、そういった対応というのは可能なのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は常に意識していただきたいのですが、やはり文教委員会としての柔軟な判断というのは、私はあっていいと思うのです。私はやってほしいと求めましたし、その議論の中で様々な委員の事情などもあるでしょうから、意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今、委員長も質問の概要をまとめていただいて、昨日も言ったので、あえて繰り返す必要はあるのかなと思うのですが、言うにはいいのですが、繰り返さなくていいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"その説諭の内容についてもっと検証すべきだという質問もあったのですが、そういう考えというのはないのでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"教員個々が、それぞれが対応している、この学校いじめ対策委員会で決めた方針がしっかりと一人一人の教員まで伝わるような対応ということが。事案、事例を積み上げていく中で、効果的なものというところは考えられていくものだというふうに考えております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりその説諭の内容が教育的にどうだったのかというのは、検証、そして改善をしていくべき点だと思いました。これは要望とともに、そういったことを今後強化していくというお考えというのはあるのでしょうかというのを、最後に伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"もしくはまずいのかというところを、区教委とも相談しながら、子どもたちに働きかけていくというところを大切にしていきたいと考えております。一人一人が共通認識を持って、共通認識を持って児童・生徒の理解をしながら指導に当たっていく…","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。改めて確認させていただきたいのは、それを確認させていただきたいのと、それで間違いないですよねということを確認させてほしいと求めました。","respondent":"柏木学務課長","answer":"閉園の決定は、正式には幼稚園条例の改正がされるというのが前提でありますので、今は廃園の方向性が示されているという認識でございまして、最終決定につきましては教育委員会に権限がありますので、教育委員会のほうで決定するということになります。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、お話があった方向性の決定というところで、ホームページで発表し、保護者の方へも説明しということですね。一般質問でほかの答弁も聞きましたけれども、変更して１年延ばすというふうにされたわけですが、そういうことができるものなのか尋ねました。","respondent":"立木保育課長","answer":"子ども未来部でそうした方針を、閉園に向けて、そういったところもしっかり考えていかなければいけないという前提の下で方針を出しています。そういったところをお知らせするという意味では、ホームページ等で公表したり説明をしたりというような形で、進めてきているところです。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、条例を改正して正式に決定する前に、閉園に向けてのいろいろなことは、早めに区民の方に知らせるために、通知というか、周知することができるという認識でよろしいか尋ねました。","respondent":"立木保育課長","answer":"方向性を定めておりますので、その方向に進めていくために、順次、その説明とか周知を進めているところです。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"そのときに、今までの経緯からすると、新４歳の方は中止します。５歳の空きを募集しますという表現になるのかなと思うのですが、それも、ホームページに載せるということでよろしいか尋ねました。","respondent":"立木保育課長","answer":"委員がおっしゃるとおり、令和６年度の入園案内に関しましては、例年１０月ぐらいにお知らせを出しておりますが、伊藤幼稚園の新入園児に関しましては、新４歳児は停止で、新５歳児につきましては、空きがある部分に関しましては募集をかけるという形で行うことを考えてあります。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"提案","question":"今回の議会に提案されて、提案されて、１０月のところでお話しすると思っていたのです。法規に基づいていろいろなことをするべきだと思うのに、廃園がどうこうと言っているわけではないので、その手続をなぜ今回も出してこなかったのかとの意見を述べました。","respondent":"立木保育課長","answer":"実際、いつ上程されるかというところは、また今後のお話になるかと思いますが、既に閉園として出させていただいている伊藤幼稚園に関しましては、令和６年度末ということになりますので、それに合わせて区が閉園の手続を取るというふうに認識しています。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"いつかということは、では、今度なのか、それとも、何でしょうか、閉園してから出すのですかね。今のお話を伺うと無理だと思うので、また６年度に向けて進んでいくということになると、どういうふうにお考えなのか尋ねました。","respondent":"立木保育課長","answer":"令和６年度末ですので、今の予定でいきますと、私どもが方針を出している部分に関しましては、令和７年の３月末で廃止という形になると思われます。それに合わせた形で決定を取るというような事務手続になるのかなと考えているところです。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが続くという認識になるのですが、現状の形がなくなっているのに、それを条例で改正していないという形で存続していくという認識でよろしいか尋ねました。","respondent":"立木保育課長","answer":"令和６年度までは廃止しませんので、運営もそのまま、在園のお子様は修了まできちんと見るという形になります。修了をもって廃止という形を今のところ考えてありますので、それに合わせて廃止の手続を取るという形だと認識しております。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"委員長がご説明いただいたとおりなのですが、回収の話で、回収をどのようにして、それで回収されたお金はどこに行くのかなというところです。足りなかったのはどうしていたのかなというところで、その後どうするのかというところも含めて、お願いします。","respondent":"柏木学務課長","answer":"今回の未納額を全体の金額のパーセンテージで言いますと、全体の０.０２％が未納となっているという状況です。年によっては次年度繰越しという金額もありますので、そういう部分で取りあえずは賄っているという状況です。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、未納分は、出っ張って出てくるわけではなくということでいいですかね。今言った１８万幾らかが私費会計の中に入らないとしたら、入ってきたらどうするのかというので、少しそこが分からない。","respondent":"柏木学務課長","answer":"回収された未納分の金額については、全て給食食材費に入ってくるです。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"試行が１校だけだと、大規模という学校があると思うので、そういうことも含めていろいろな条件があったのかということをお尋ねしたいと思います。そして、全校に展開していく、その道筋みたいなのが分かれば、お願いします。","respondent":"大澤子ども育成課長","answer":"１つ目が、すまいるスクールの本来業務に大きな支障を及ぼさない施設ということで検討した結果、すまいるスクール第一日野となったところです。試行実施後には、また対応したスタッフへの聞き取りなどを行いまして、その後の展開を検討していく予定です。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"意見","question":"今の５つが整わない学校には、現時点の判断で結構ですが、どうでしょうとの意見を述べました。","respondent":"大澤子ども育成課長","answer":"今の条件をクリアできないとなかなか厳しいものがあると今は考えておりますが、そのことも含めまして、試行している中で、今の条件が本当に全てそろわないとできないのかどうかということも含めて、検討してまいりたいと考えております。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"意見","question":"そうですね。これだけの条件ではなくて、ぜひ試行の最中で施策が円滑に行くように、今お話があったように進めていっていただければよろしいかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"吉田副委員長","kind":"質問","question":"例えばその仕出しがどういう業者になるのか、そういう選定のことというのは、どこでどういうふうに検討されていくのか。当然、試行に当たっては相手先が決まっていくのだと思うのですが、その選定についてはどのようにお考えなのか尋ねました。","respondent":"大澤子ども育成課長","answer":"事業者を決定するに当たってですけれども、他区の学童クラブ等で実績のある事業者、複数業者に打診をしまして、その中から品川区内でも展開できるという事業者に、現在はお願いする予定です。","id":"exchange-055"},{"speaker":"吉田副委員長","kind":"質問","question":"例えばこのすまいるスクールの仕出しの中で、やはり原則、そうするとアレルギー対応とかは、他区の場合はどうされているのか。だから、そういうこともできるような業者を選んでいるのか、その辺のことについて伺いたいのですが、いかがか尋ねました。","respondent":"大澤子ども育成課長","answer":"他区の実績でも、仕出し弁当業者で今、アレルギー対応ができるところはないので、品川区の場合も、アレルギー対応はできないということで、保護者の方にはご案内をします。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39098,"voices":185}},{"id":"r05-20230704-5","meetingId":"r05-cm07","date":"2023年7月4日","dateIso":"2023-07-04","committee":"総務委員会","time":"午前１０時００分～午後 ０時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前例に縛られず、冒頭だけではなくて、委員会審査の全体を録音・録画してよいと思います。理由を伺いたいなと思いますけれども、しかも、委員会についても本会議場の対応と同様に区民に全ての撮影・録画を認めてよいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"松本委員","kind":"意見","question":"中塚委員から本会議の話がありましたけれども、他自治体においては、委員会のインターネット中継をやっているところもあります。冒頭のみならず、全体を録画されるのも問題ないかと思いますので、前例に縛られる必要はないと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"私は前例でお願いしたいと思いますが、今、まさに中塚委員も既に分かって、あえて言っていらっしゃるのだろうと思っています。よく分かっていらっしゃると思うのですけれども、ぜひそれをお願いしたいと思うし、今日は前例でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]},{"id":"topic-02","title":"説明に入る前に、各所管委員会における審査の結果","agenda":"説明に入る前に、各所管委員会における審査の結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正予算の特徴や狙いについて、どのようにお考えなのか、少しご説明ほしいと求めました。このようなものはいつ頃から検討されているのかも含めて、ご説明ほしいと求めました。","respondent":"遠藤財政課長","answer":"検討の時期ですが、３月の後半ぐらいから、それぞれの所管で検討していただいてあります。そのような形で進めたところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に高齢者の方にお話を伺うと、ない袖は振れないという話も伺いますので、ないのか。補正予算を今の時点でどう組むかは、そのような対応が必要だと思うのですけれども、併せていかがか尋ねました。","respondent":"遠藤財政課長","answer":"前回の５月の補正予算の段階で、住民税非課税の方への横出しなどをしながら支援をさせていただいていますので、総合的にご支援はしてきたです。以前のような対策などが必要かと考えていますけれども、現在は、今回は予算の補正をさせていただいたところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ十分な警戒とともに、必要なときは迅速な対応を要望しておきたいと思います。豪雨災害でひどい被害が起きているだけに、対応強化が必要だなと思うのですけれども、その点についても一言伺いたいと思います。","respondent":"遠藤財政課長","answer":"災害復旧基金なども積ませていただいて、臨機応変にお金のうえでは対応するです。引き続き、区民への周知に努めまして、所管を中心にやらせていただくところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"豪雨災害については、従来の規模を超える被害が起きておりますので、引き続き、十分な警戒をしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"それぐらいいろいろな形で使えるといえば、あれも１割補助だけれども、進んでいくわけではないですか。せっかくお金が出ているからやるというのではなくて、もう少し実があるような形で、何かうまく結びつけてほしいなということが１つ。","respondent":"遠藤財政課長","answer":"これはぜひ必要なものだということで進めるところで、戸建て２棟というところは、２棟だけやらせていただいたところです。これから３年間かけて、こちらは財政面での支援という形になりますけれども、進めるようにしたいです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"２３ページの防災費についてお聞きします。この４０組織、７０組織というのは、説明を求めました。","respondent":"遠藤財政課長","answer":"今回のそれぞれの数字ですけれども、こちらの事業につきましては、３年間で実施するという形で進めしています。２０組織、２０組織というところで予算を組んで、全ての組織に持っていただきたいなと考えているところです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それから、実際、各組織というのは、地域、町会云々を考えられているのか。それを対象にして、今後、どんどん広げていこうという対応で考えられているのか、少し説明を求めました。","respondent":"遠藤財政課長","answer":"カセットボンベ式など、いろいろありますので、それはそれぞれの防災区民組織で考えていただくという形で進めているところです。それから、防災区民組織ですけれども、基本的には、町会が多分イコールになっておりますので、それで２００組織と考えているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは要望で申し上げておきます。そして、今後、もちろん話合いをして、今回、実証事業経費ということをここに出しているわけですが、継続できる可能性は担保されているのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"今回、ほかにも寄附金で歳入が入ってきているのですけれども、この指定寄附という制度というか、枠組みなのですか。ふるさと納税などとの違いを少しお伺いできればと思います。","respondent":"遠藤財政課長","answer":"ふるさと納税の寄附金も１つの形になるかと思うのですけれども、今回、このように選挙啓発用品に使わせていただくという形で予算要求させていただいたところです。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"これは、税額控除というか、控除等の関係などはどうなっているのですか。このような指定寄附というものと、税金、税額との関係というのはどうなっているのか尋ねました。","respondent":"遠藤財政課長","answer":"ふるさと納税は２,０００円の控除という形になろうかと思います。寄附は、一般的に、当然、上限というものがあろうかと思うのですけれども、基本的に２,０００円の控除が受けられると認識しています。","id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"今回の指定寄附も、そのようなことは可能なのか尋ねました。","respondent":"遠藤財政課長","answer":"恐らく、そのような形で認識しております。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"可能であれば、できればホームページなどに公開していただいて、ぜひ区民の方にお願いしますということを周知していただければなと思います。要望で終わらせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、一義的に学校側がこのお金を使って、協議会を立ち上げて進めていくということだと思っています。より進んでいくのではないかなと思ったのですが、考え方について、少し説明を求めました。","respondent":"遠藤財政課長","answer":"教育委員会のみの予算という形になっておりますけれども、スポーツ推進課、あるいは文化観光課が一緒になってやっていくと聞いているところです。そちらの予算も考えているところですけれども、どのような形にするか、検討されると伺っているところです。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"学校が進めていけると、今度は地域でも進めていけるような予算をしっかりと確保していただきたいなと思ったので、これを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほども述べたとおり、個々の事業は必要な事業だと思いますので、賛成したいと思います。その上で、電気代の補助、コロナへの十分な警戒、豪雨対策をしっかりと進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-03","title":"国連を支える世界こども未来会議 ｉｎ ＳＨＩＮＡＧＡＷＡ","agenda":"国連を支える世界こども未来会議 ｉｎ ＳＨＩＮＡＧＡＷＡ","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"もう一点、ＳＤＧｓの学習について、講師はもう決まっていらっしゃるとは思うのですが、どのような選定基準で、どのような方を選んだのかということ。それとも幾つか内容を絞って子どもたちに特化して説明するのかということを少しお伺いしたいなと思っていますが、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"こちらで連携している、検討中でございまして、小学校４年生から６年生が理解しやすい内容で検討しています。","id":"exchange-019"},{"speaker":"澤田委員","kind":"質問","question":"では、講師はまだ特に決まっていらっしゃらない感じか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"提案","question":"提案して、発信していく、とても貴重な経験になるのではないかなと思います。ここでの最優秀グランプリ受賞者は、「第４回国連を支える世界こども未来会議」はどのようなものなのか、伺いたいと思いますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"日本の学生も入ってくるというところが、第３回の国連を支える世界こども未来会議からで、昨年度から実施されました。１４か国、３自治体から、約６０名の参加で実施したところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"「第４回国連を支える世界こども未来会議」に品川区を代表して参加するのでしょうけれども、最終的に報告書なるものは作成されるのか。参加した子どもの感想などを載せてもいいのかなと思うのですけれども、その点だけご説明くださいとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"実施後の報告書の作成というところですけれども、子どもたちがどういった話合いを行ったのか、どういった感想をいただけたのか、そういった実施概要もきちんと報告書としてまとめ上げて、やっただけではなくて、こういった成果も出して、周知を図りたいと思います。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、お願いというか、お話を伺えればと思います。お願いだけしておきます。","respondent":"吉岡政策推進担当課長","answer":"今、委員からお話のとおり、せっかく議場を利用させていただいて、このような機会を設けましたので、当然、集合写真という形で収めたいとは思うのですけれども、いい運用もいたしまして、思い出に残るようにしたいと思います。","id":"exchange-023"}]},{"id":"topic-04","title":"区民アンケート","agenda":"区民アンケート","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"４項目中１項目ということで、薄まってしまったという声も伺いますし、私もそう思います。３点目は、羽田新ルートの中止を求める考えがあるのか、その点も伺いたいと思います。","respondent":"辻広報広聴課長","answer":"全体としては４０％ということで、薄まっているという認識は、私どもは持っていないところです。例えば、３０代の男性で、どこに在住の人の回答は、というクロス集計は、幾つも作る予定にしております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"国に対して中止を求めるという判断を、なぜできないのか、その点を伺いたいと思います。全区民に対して、誇りを持っているか否か、その程度を質問しているわけですけれども、この設問の目的は何なのかを伺いたいと思います。","respondent":"辻広報広聴課長","answer":"属性によってどのような影響があるのかということを細かく調べることが今回の目的ですので、それをもって、すぐに中止を求める予定はございません。誰もが生きがいを感じて、自分らしく暮らしていくための品川区をつくるための一要素と捉えまして、設問としたところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"この誇りについての全区民調査のことを改めて伺いますが、区民であることに誇りを持っているかどうかを調査する目的がよく分かりません。改めて伺いたいのですけれども、それを区が全区民に聞くことにどのような狙いがあるのか、改めて伺いたいと思います。","respondent":"辻広報広聴課長","answer":"それを分かった上で、各個人がどう思っているか。いわゆるウエルビーイングを高める１つの要素ですので、皆様がどのような心持ちでいるのかということを改めてお伺いするということが目的です。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"５割なのか、６割なのか、思えという強制につながりかねないと思うのです。誇りの強制はあってはならないと思いますけれども、その点、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"まずは問１の最初のところで、もしも誇りに思えないという方が多いのであれば、どこに原因があるのかといったことの分析に使おうと思ってあります。では、誇りが持てるような品川区政をこれからつくるための基礎調査とするということで、ご理解いただきたいと思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"今まで、品川区はどうなのだろうという問いかけをアンケートとして出すということは、私はすばらしいことだと思います。意見だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"この１００字については、どのように考えて１００字なのかということを教えてください。何かやり方などを考えているものがあれば説明を求めました。","respondent":"辻広報広聴課長","answer":"何か１つの項目に対して、それは区としてももっと取り組まなければいけないなという判断をするという使い方をする予定です。このアンケートをもう少し柔らかく、分かりやすく、小・中学生向けにしたものにする予定です。","id":"exchange-029"},{"speaker":"大倉委員","kind":"質問・要望","question":"５ページを見ると、１００字しか答えられないという逆の捉え方をされてしまったらもったいないなと思って、少し伺いました。タブレットを使って、インターネットでスマートフォンから簡単アクセスというＱＲコードを読み込んで使うということでいいのか尋ねました。","respondent":"辻広報広聴課長","answer":"ＱＲコードを読むということではなくて、タブレット上で答えられるようなものをつくる。小・中学生向けに実際にやったことがあるということですので、それを参考にしながらつくり込みをしたいと考えています。","id":"exchange-030"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し聞いたのと、修正ができない理由は何かあるのか、教えていただきたい。その点について、説明を求めました。","respondent":"辻広報広聴課長","answer":"インターネットでの回答は修正できないという話ですけれども、申し訳ないのですが、もうそれで終了です。これだけにさせていただいて、また別の何か封書等を出すようなときには、そういった今のアイデアも活かしていきたいなと考えています。","id":"exchange-031"},{"speaker":"大倉委員","kind":"意見","question":"いろいろお考えいただいて、このような形になったということで理解しましたので、ぜひ多くの区民の方がアンケートに答えて、これを区に反映できるように、周知を含めてしっかりやっていただいて、１人でも多くの回答を得られるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"伺いたいのは、例えば、では、誇れますという人たちが何％いたときに、それにどのような意味があるのかということを把握する必要があると思います。何を基準に、何％だったからどうということを判断していく基準が取りにくいと思うのですが、その辺りはどのように考えていらっしゃいますか。","respondent":"辻広報広聴課長","answer":"全てについて言えるのですけれども、その項目をどのように判断するかというのは、非常に難しいところかなと思います。よそで同じように実施していれば、その比較も考えられますけれども、今のところはないです。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"そうすると、どう活かしていくのかということがすごく難しい調査かなと思って、例えば、「幸せだと感じていますか」の問いです。そういったところで比較するということを考えて、このような問いなのかというのは、どうなのか尋ねました。","respondent":"辻広報広聴課長","answer":"これからの区政を進めていく上で、まず、現状の心持ちをお伺いする。それと、何が大切だと思っているかということと掛け合わせて、これからの施策に反映していこうというつもりでおりました。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"ずっと住まわれている方で、ある程度変化してくるのではないかと思いますが、そういったところは特に聞かれるつもりはないのかというところはいかがか尋ねました。","respondent":"辻広報広聴課長","answer":"全数調査をするに当たって、あまり複雑にしてしまうと、回答率が悪くなってしまうということもございました。居住年数については問わず、今、品川区に住んでいらっしゃる方にお伺いしようという基本的な理念の下につくり込んだものです。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望も含めてですが、外国語の記載についてどうなっているのか。ないようであれば、送るときに外国語の表記もしてほしいと求めましたが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"外国の方への対応です。広報の英語版や、ポケット版のアプリですと、外国語対応もしておりますので、そちらでの周知等を考えているところです。","id":"exchange-036"},{"speaker":"澤田委員","kind":"質問","question":"回収率見込も４５％と非常に高い数字であるのですけれども、いろいろなものを集計してだと思うのですが、どのように算出したのでしょうか。そこを説明を求めました。","respondent":"辻広報広聴課長","answer":"今まで世論調査をさせていただいたときに、大体４５％から５０％ぐらいが多かったです。２３区の中でも、世論調査等の回収率が大体４５％ということもございまして、それに合わせて４５％とさせていただきました。","id":"exchange-037"},{"speaker":"澤田委員","kind":"提案","question":"今回は間に合わないかもしれませんが、また次回の参考にしてみたりということはいかがでしょうかというご提案です。ばれないで済むというか、身ばれしないで済むのかなということで、そのようなことはいかがでしょうかというご提案ですとの意見を述べました。","respondent":"辻広報広聴課長","answer":"アンケートを開始しますというのを１回やるだけですけれども、何回かに分けて、Ｔｗｉｔｔｅｒ等ではご案内をしていこうかなと考えています。制度設計の経費的なことも考えまして、提案として、ほかの事業のときにも使えるかなと思います。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問","question":"先ほど、せっかくやるのだからというお答えもあって、まさに区長の政治的な流れの中でやることになっているのは承知しています。その中で、これをやることになっている中での全数ということを活かした今回の調査のメリット、狙いを改めてお伺いしたいと思います。","respondent":"辻広報広聴課長","answer":"全数調査のメリットとしては、誤差が生じないというのが１点です。それほどの誤差が出ない数字は計算式でありますけれども、今回は一人ひとりにきちんとご意見をお伺いしようということでやらせていただくものです。","id":"exchange-039"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"基本的にはできないと思うので、そこをしっかり酌み取れるようなアンケート調査に努めていただきたいということはお願いしておきたいと思います。最後に１つだけ確認したいのですけれども、１人の人が何回もできないようになっているとは思いますけれども、その辺の確認をお伺いしたいと思います。","respondent":"辻広報広聴課長","answer":"インターネットでの回答についてです。それを入力して回答していただくということで、１回やると、ひもづけされているです。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"確認","question":"１回ではないから、それは確認したから、絶対間違いない。前の部分は確認しているから間違っていないと思うのです。","respondent":"辻広報広聴課長","answer":"あれは、今、委員がおっしゃいますように、１人ずつにひもづけはされておりません。そこは、しっかり考えていきたいと思っています。","id":"exchange-041"}]},{"id":"topic-05","title":"品川区ジェンダー平等の推進に関する検討委員会の設置","agenda":"品川区ジェンダー平等の推進に関する検討委員会の設置","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"策定委員会を設置しながら、条例の案文自体も最終的には落とし込んで、第１回定例会に提案とあります。この資料を見たときに思ったのですけれども、その点、いかがか尋ねました。","respondent":"加島人権啓発課長","answer":"区の認識といたしましては、あくまで議案を示すのは議会に対してと考えております。生き生きとした人生を享受できるよう示されていると考えておりますので、こういった国際的な視点を資料にも示させていただいていると考えております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"提案","question":"議案については、実際の条文を十分検討できる時間を示してほしいなというところを趣旨として、質問いたしました。提案側としての工夫を求めて終わりたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"財政調整は、もう３００から４００でいいのだけれども、それはそれで、もう触れないという了解ですか。触れるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"触れると、中身に触れてもいいということですか。どこかで１回ぐらいやるのかという質問です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"コロナの感染状況がどうなるか不安定なところもありますので、感染状況によっては中止の判断。委員会運営のことですので、できる限り協力したいとは思いますけれども、コロナの対策は十分な警戒が必要だと述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":47922,"voices":182}},{"id":"r05-20230705-14","meetingId":"r05-cm07","date":"2023年7月5日","dateIso":"2023-07-05","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前例はそういう対応をしてきましたけれども、やはり冒頭のみではなくて、審議中も含めて写真は認めてよいと考えています。全てをインターネット中継までしている時代ですから、委員会についても、全てを写真撮影してよいかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"障害は種別が様々ありますので、そこはちょっと幅広くないなというふうに感じたのですが、なぜ育成会だけなのかというのを伺いたい。なので、そうした方向というか例えばという形で、もうこの委員会では示されるということでいいのか、伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"資料の一番下、２番の（４）その他のところにありますが、傍聴可としてございまして、８月１日の広報しながわのほうで掲載を予定しています。この検討委員会の結果を踏まえまして、段階的に検討を進めるものということで認識をしています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民の願い実現に求めるものを建設していく、障害者団体も含めて聴取していただきたいなと思いますし、そういうメンバーに私は見えます。どういった意図で、何でこのメンバーなのかなというのがちょっと疑問なのですけど、もう一度そこをお聞かせいただけたらと思います。","respondent":"泉広町事業調整担当課長","answer":"手をつなぐ育成会の方々を通しまして、今回の検討委員会の資料につきましては、ホームページのほうでも資料を出していくということになってあります。基本的には大井町駅周辺地域まちづくり方針、そういったところの土地利用の方針に即しながらも、選定をしたです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"内容のところに書いてあるので、要するに民間に何を聞くかというのも、この検討委員会で話されるということでしょうか。そこに民間の方に何をやってもらうかを聞く内容を決めるというのが、何で入っているのかなというのは思うのですけど、何でなのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"この品川区庁舎跡地等活用検討委員会の内容のところに含まれているですけれども、活用検討委員会の中でも広く情報共有しながら進めたいという趣旨で、ここで内容を説明するです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、この委員会の中で、要は対話型市場調査というのは、企業の方に、この跡地をどういうふうに使うかというのを聞いていくわけですよね。そうしたことが、そういう検討委員会にはすべきではないと思うのですけれども、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の調査内容に関連するご質問ということでお答えをいたします。先ほど申し上げた検討委員会の最終の段階につきましては、その内容について共有をしていただくという形で考えているところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"さらに周辺開発を一層進めていくということになっていきますので、そうした活用の仕方は、私はすべきでないと思っています。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"私から３点お伺いをしたいと思います。その辺りを教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"令和１０年から速やかに事業に入れるようにといったところはしっかり念頭に置きながら、検討を進めてまいる予定としています。事業手法の検討と対話型市場調査に伴いまして、段階的に検討を進め、ご報告してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"我々の考え方とか意見、しっかりとそれはご報告をしてほしいと求めましたので、この点についてのご見解を伺いたいということです。当然、そういったこともこれから、この検討委員会の中で一体的に示されるのかどうかというところを確認させてください。","respondent":"泉広町事業調整担当課長","answer":"検討委員会と並行して行ってまいりますワークショップですとか、やはり５回が適切ではないかということで、区としては捉えているところです。当然、そういった庁舎を含めました周辺のまちづくりという観点で、様々これから検討を進めてまいるです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"確認","question":"最後の部分だけもう１回確認ですけれども、今の新庁舎とかＪＲとかの広町の跡地と、その一体的な考え方というものがこれから示されるという認識でいいのか説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"今この第１回の検討委員会の中でも現状の整理ということで、検討を図っていくというところでございまして、庁舎一体のまちづくりといった観点での示し方をしてまいるといったところで考えてあります。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これまでは学識経験者が３名いらっしゃって、基本構想・基本計画策定委員会のメンバーでは、大島委員だけがメンバー構成されております。新しい学識経験者が２名委員になられるのですけれども、どういういきさつで大島先生だけが残ったのかということを教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"委員の学識経験者に関するご質問です。今、庁舎のほうの委員にもなっていたということも踏まえまして、そういった経過もお詳しいといったところも踏まえての選定となっています。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今までおられた方には、今回の活用検討委員会では当然選出されていませんけども、その前のとはいろいろと反映できるものはあるのですか。前回のメンバーの人たちにも幅広く告知できるような報告というのは考えていらっしゃるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"現状では今、庁舎の委員の皆様に、こういった情報をお渡しして何かしらの情報を得るといった仕組みは考えてございません。今いただいたご意見を踏まえまして、今後検討してまいりたいということで考えてあります。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討をよろしくお願いします。この活用検討委員会ではどういう体制でいくのか、あるいは、これまでのどういうふうな状態でいくのかというのを教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"事務局側の構成といったところですけれども、今まさに検討しています。事務局側の構成につきましても、整ったところでご報告をさせていただきたいと思ってあります。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"この収益性と公共性とは何を指しているのかも併せて伺いたいと思います。そしてもう１点、コンサルの企業がどこなのか、ご説明ほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"こういった官民連携手法を導入していくといったことと、前提条件として進めてまいりたいと思っているところです。もう一つ、事務局を補佐するコンサルタント業務のご質問ですけれども、こちらは今、業者選定の手続中となっています。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりはこの跡地を活用して、財源を生み出すという考えがあるのかどうかを確認させてください。８月３０日までには当然決まると思いますので、決まり次第委員会に報告してほしいと求めましたが、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"これから検討をさせていただきまして、そこは改めて検討の上、ご報告をするです。そういったところ、機能につきまして何か限定するものではなく、今は幅広く段階的に検討を進めていくです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"いかがかということと、そういう前提はやめるべきだと私は思いますが、いかがでしょうかと。それを示していただきたいということと、新庁舎のコストを下げるということにどうしてつながるのか、よく分からないのでご説明ください。","respondent":"泉広町事業調整担当課長、大友新庁舎建設担当課長","answer":"検討を進めていくというものでございまして、そういった検討の中で、公共性と収益性といったところを両立できるやり方を検討していくというものです。はそのほかの事業に充てていくことで… 新庁舎の費用の考え方ですけれども、基本計画でお示ししている約４００億円以上、こちらの考え方は変わりません。物価上昇や費用対効果を含めたＺＥＢ対応化などで価格の上昇が見込まれるという現状におきまして…","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"それとも、何か別の方法もあるというのか、ちょっと今の説明を私は初めて聞いたので、どういうことなのか伺いたいと思います。区民の財産を使って、区が財源をいただくだけだというようにしか思えないのですけども、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"事業スキームが既に決まったものではございませんで、そういったところも含めまして、対話型市場調査の中で確認をしてまいるものです。財源に関わるものですけれども、こちらにつきましても、区民負担の実質的な軽減を目指していくですので、そういった手法を様々検討しています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"それと最後に、第１回の跡地活用検討委員会ということで、これから考えるのだと言いますけども、実際はもう決まっているのではないですか。このＣ地区、牽引役としての集客施設になりますよというものが示されているのではないかと私は思うのですけども、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"跡地の活用の方法が決まっているのではないかというご意見です。まちづくりの観点から進めてきた検討といったところになってございまして、庁舎跡地等の活用に関しましては、まさに今後検討を進めていくところで。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"なぜかというと、業務委託ですから、何らかの成果物を品川区に提出しているのです。ではなくて、日建設計が品川区に示したものがあるのではないかと伺いましたので、改めて伺います。","respondent":"泉広町事業調整担当課長","answer":"繰り返しのご答弁になりますけれども、先ほど申し上げましたとおり、まちづくりの観点から検討をこれまでしてきたものでございまして、現在そこのところにつきましては、決まったような施設といったところはございません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"私が聞いているのは、日建設計が何か示したものがあるのでしょうと。あるのかないのかを最後に伺いたい。","respondent":"多並広町事業担当部長","answer":"ご指摘いただいたようなまちづくりの検討を都市環境部のほうで進めてまいりまして、まちづくり方針という形で最終的に令和２年にまとめてあります。今まで検討したことがあるかないかという話ですが、今後はそれに基づいて具体的な検討をこれから…","id":"exchange-019"},{"speaker":"中塚委員","kind":"意見","question":"こういうのは一からやり直すべきだと思います。しかも、特養ホームとか障害者グループホームを初めから排除する、こんなことは決して許されないと、強く指摘して終わりたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"もう一つ、１０名ということですが、各団体の参加者は１名ずつということでよろしかったでしょうか。それとも、例えば生徒会とか子どもたちの代表なのか、その辺について伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"こういったところとも連携して進めていきたいということで考えているところです。もう一つ、こちらは生徒の皆様ではございませんで、そういった子どもたちの視点も含めていただきたいということで考えてあります。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問・要望","question":"これは７月１０日まで募集ということで、今現在、大体何名ぐらいの方から申込がされているのでしょうか。その選定方法ですが、幅広い年齢層の区民の方にご参加していただきたいと思うのですが、区としてどのような形で選定されていくのかお知らせください。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきまして、今後選考といった手続がありますので、何名かといったところは控えさせていただきたいと思います。作文を書いていただいてありますので、そういった作文の内容を踏まえて選考していくです。","id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"改めてなのですけれども、ワークショップ・対話型市場調査を実施するということですけれども、この調査をする場合の、対話する内容、今のところ想定されているところをもう一度お願いできますか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"これはまさにこれから検討してまいるというところになってありますが、いずれにしても今後こちらについては検討していくものです。対話型市場調査も同様に今後検討といったところになりますけれども、今回何か、業態ですとか事業スキームといったことを限定せず。","id":"exchange-023"},{"speaker":"松本委員","kind":"提案","question":"全く何もないところでやっていくと、単純に先ほどからの懸念が出ている高層マンションとか高層ビルを建ててというふうなものが出てくると思われます。そうした福祉施設などもこの土地の中に入っていくようなアイデアを市場調査の中でやっていただくということをご提案いただけないかなと思いますがと…","respondent":"泉広町事業調整担当課長","answer":"まちづくり一帯を考えて、そういったところも実現できる仕組みを検討してまいるということで、対話型市場調査・ワークショップを展開してまいります。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"区内関係団体の中で、青稜中学校・高等学校がありますけれども、跡地の近くの学校だと思いますけれども、この私立の青稜中学校・高等学校を区内関係団体の中に入れた理由というのは、何かあるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"やはりこの庁舎周辺の一体的なまちづくりを考えたときには、教育の視点、そういったところを踏まえてこちらの学校を選定させていただいたものです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"品川区全体を捉えるところ、青少年問題協議会がありますけれども、そうした全体の教育的観点という意味ではほかの団体とかはあまり検討されなかったのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"教育的な視点での団体といったところのご意見です。庁内、教育委員会にとっても、この検討を進める中では連携をしながらそういったご意見を補足していくといったことを考えてございまして。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"新庁舎整備でも、ご意見募集フォームだとか、そうしたことを行ってきたかと思います。専門的な団体の方々のご意見を取り入れていく、その仕組みというのは検討されているのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきましては、今年度行ってまいりますワークショップですとかアンケート調査、区民ニーズをしっかりと捉えていきたいと考えています。ご意見フォーム等の取組もありますので、そういったところも参考にしながら、多くのご意見を聴取できるように努めてまいります。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"この５回でおのおの何を話すのか、具体的に何を議論するか、話を進めていくかというのは決まっているのでしょうか。決まっていたら概略を教えていただきたいです。","respondent":"泉広町事業調整担当課長","answer":"は回数ですけれども、段階的に検討を進めていく中でのものですので、一旦この検討委員会の中でしっかり区民ニーズと民間事業者のご意見。次回、第１回の検討委員会の内容をご説明する中で、それぞれのテーマにつきましては概要をご説明させていただきたいと考えています。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問","question":"ぜひ、第１回の後にお聞きできればと考えています。そして、今回の検討委員会での内容が、次の委員会等に引き継がれるということで、理解いたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"せお副委員長","kind":"質問","question":"１点だけ、今、ほかの委員からも様々ありました、例えば防災の観点からとか教育の観点、あと、福祉の観点と、そういったところは区内の庁舎内で連携していくというお話だったのですけど、そこの連携の仕方というか具体的に何かありましたら説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"庁内の連携の手法といったところです。例えば検討委員会をつくってみたいなところはまだ考えてございませんけれども、いずれにしましても、これも引き続き検討する中で。","id":"exchange-030"},{"speaker":"塚本委員","kind":"確認","question":"１点確認なのですけど、令和１１年度、区民避難所としてここは使えなくなるということに恐らくなるのだろうと思うのです。その間、災害は待ってくれないのでどうするのだというところが、そこについてどのような対応を考えていらっしゃるのか説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"委員おっしゃるとおり、令和８年度から整備工事等が入った場合に約３年間、この施設が区民避難所として使用できない可能性があります。地域との説明、そういったところで連携しながら、体制を図っていきたいなというふうに考えているところです。","id":"exchange-031"},{"speaker":"塚本委員","kind":"確認","question":"これは、今後はどちらかというと防災課主管で進めるということでよろしいですか。そこだけ最後確認させてください。","respondent":"吉岡政策推進担当課長","answer":"委員のおっしゃるとおり、こちら防災課あるいは地域、地域センター、避難所連絡会議等もありますので、そういったところでしっかりと話し合っていただいて、準備を進めていくというような流れになろうかと思います。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問","question":"大体この解体はどれくらいかかるのかというのが１点と、令和８年度からいろいろ工事とかある中で、それを説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"今のところおおよその解体期間が令和６年４月から６月の３か月間の期間でということで確認をしています。今後運用する中でうまく、そのまま活用できるようなところがあれば、考えていきたいというふうに考えてあります。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"意見","question":"ぜひ、今やられている旧荏原第四中学校の検討委員会でしたか、ああいうところでも、ただ真っさらにしておくだけでは何なので、地域とのコミュニケーションの中で何か活用を見いだしてくれればいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"ご説明あったとおり、令和６年以降も引き続き暫定活用を継続したいということですけども、この点については了解をしたいと思います。１点伺いたいのですけども、令和７年、どの時期なのかお伺いしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"令和８年度は実施設計、令和９年度、令和１０年度のところで整備工事ということで検討しているようなところです。ですので、一定程度その方針というところで、どのようなものかということは今年度、方針として策定をするというようなスケジュールです。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"旧荏原第四中学校跡地に何ができるのかという概要はそこで示されるということでよいのか、改めて確認させてほしいと求めました。ぜひ進めていただきたいと要望したいと思いますが、併せていかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"まさに今年度、ワークショップ、あとは跡地活用の方針策定委員会、もちろん、それまでの地域からの要望、そういったものも踏まえまして、基本方針を検討していくという形になりますので、そういったところでしっかりと進めていきたいと考えています。","id":"exchange-036"},{"speaker":"筒井委員","kind":"確認","question":"委員について、どういう方で構成されるのかというのは、まだ発表はされていないでしょうか。確認で伺います。","respondent":"吉岡政策推進担当課長","answer":"実は来週の７月１０日に第１回の跡地活用方針策定委員会を開催するということで、学識経験者の方が２名と、あとは公募区民の方が２名というところで。区の職員も、部長級の職員が４名、この委員会に参加をするです。","id":"exchange-037"}]},{"id":"topic-02","title":"令和５年陳情第１４号、広町地区土地区画整理事業に係る品川区合意を事前に区議会に報告するよう求める陳情","agenda":"令和５年陳情第１４号、広町地区土地区画整理事業に係る品川区合意を事前に区議会に報告するよう求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"土地区画整備事業の概要ということで、この１１５億円というのは具体的に何の費用なのか、道路とかインフラとかそういうことなのでしょうか。ちょっとよく分からないのでご説明いただきたいのと、この１１５億円というのは誰が幾ら負担するのか、ご説明いただけますか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきましては、委員ご指摘のとおり、道路といった基盤整備に関わる費用として、約１１５億円がかかってまいるといった内容です。こちらは施行者であるＵＲ都市機構のほうが、保留地を譲渡することによって…","id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"約１１５億円は、電柱を建てたり、いわゆるＪＲ東日本や新庁舎や庁舎跡地の建物部分は含まれていないということでよいのか確認させてください。誰がどう負担するのか、私の不勉強もあってよく分からないので、もう少しご説明いただけたらと思います。","respondent":"泉広町事業調整担当課長","answer":"先ほど委員からご指摘がございました、インフラ等の整備にかかってくる経費といったところになってあります。先ほど申し上げた、施行者であるＵＲ都市機構のほうがそれを譲渡するといった形で、費用を捻出して事業を進めるといったことになってあります。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"今の約１１５億円のところですけれども、いつの時点でこの約１１５億円という数字が出てきたのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"約１１５億円と数字が示された時点ですけれども、こちらは令和４年６月２８日の建設委員会の資料といたしまして、約１１５億円の事業費といったところをご提示したものです。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"この約１１５億円の市場、約１１５億円に足らなかった場合というのは、これは区の負担は出てくるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"そういった資金の精査を図ってまいりますので、ＵＲ都市機構のほうと検討、協議を進めていくことになります。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"これ、約１１５億円で足りない場合に誰がどう負担するのかということが、全く現時点で協議されていないということなのか尋ねました。","respondent":"泉広町事業調整担当課長、多並広町事業担当部長","answer":"この約１１５億円の部分に関するご質問ですけれども、この約１１５億円、資金計画等の精査を行うというものです。 権利者の中で、それがあれば、その法律に従って処理していくということになります。基本的にはそこについては全て、手続をこれから行っていきますので、権利者という立場でそれはこれから調整していくです。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"それで、この資金計画のところが、この陳情の中で出てきているかと思います。議会で区から説明というのはなかったというふうな記述がされておりますけど、なかったということでよろしいのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"今申し上げました約１１５億円といったところをご提示してございまして、事業計画書の詳細につきましてはご提示をしてございません。こちらにつきましては、施行の認可後に、縦覧が必要になってくる図書といったところを基本としながら、これまでご説明をさせていただいたです。","id":"exchange-043"},{"speaker":"山本委員","kind":"質問","question":"それから、行政として一般的なのでしょうか。品川区では、品川区が行政財産を含む土地区画整理事業をする場合、議決案件となるものなのでしょうかというところで説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"地方公共団体が施行した場合の一般的な考え方といったところですけれども、これは、土地区画整理法の中で定められているです。今回は土地区画整理上の換地といったことになりますので、今回この内容につきましては、議会に付すべきような内容にはなってございません。","id":"exchange-044"},{"speaker":"山本委員","kind":"質問","question":"ＵＲが施行者であるので議決案件ではないということへの質問ではなくて、この土地区画整理事業をする場合だったらどうかということをお聞きしたいのですが、それでも変わらないということでよろしいか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"個人施行で実施しているものですけれども、土地区画整理上の換地といったことになりますので、こちらは議決事項にならないです。","id":"exchange-045"},{"speaker":"山本委員","kind":"意見","question":"区が実際にこの土地区画整理事業を進めている場合と同程度の情報開示を進めていくことがふさわしいのではないかというふうに私は思いました。特に議決は必要ではないということであっても、やはり、同程度の開示は必要ではないかというところで考えましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問","question":"品川区でも同じようなことがあるのでお伺いしたいのですけれど、例えば、それは対策しないといけないというふうな話が出てくると思います。これは、どうするのかというのは決まっているかと思うのですけれども、その決まっている点について議会でのご報告はあったのかお伺いいたします。","respondent":"泉広町事業調整担当課長","answer":"土壌汚染に関わる経費につきましては、従前の土地所有者が負担をして、それを処理していくといったことになってあります。そういったことは基本協定の中で定められてありますけれども、区議会のほうにはその協定の内容につきまして、個別にご説明をした経緯はございません。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問","question":"この陳情書の２ページにある、田町事業と比べて、こうした資料が提示できなかった理由などはあるのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"基本的にはそういう施行認可後に、必要とされている縦覧図書といったところを基本としながら、これまでご説明をさせていただいてきたです。広町事業と田町事業につきましては、それぞれ権利者の構成も異なりますので、そういったやり方は様々なのかということで認識しています。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"結論は不採択でお願いをいたします。説明を求めたい、区からの報告というところで了としたいと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"山本委員","kind":"意見","question":"当該事業は、品川区にとって大きな行政財産の再開発であって、やはり、事前により丁寧な説明を行っていくべきだというふうに考えております。本陳情の趣旨に賛同いたしまして、趣旨採択といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"理由ですけれども、現庁舎跡地について官民連携手法の導入は行うべきではありません。ただ、区民の方が、より丁寧に議会にも資料を出してほしい、丁寧に説明をしてほしいと、その趣旨はよく理解できますので、趣旨採択ということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問・要望","question":"ご説明があったように、港区の田町事業との違いがありますので、この陳情を採択するまでの合理的な理由はなかったと判断をいたしました。今後は、この行財政改革特別委員会等々で、議会に丁寧なご説明を求めていきたいと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"松本委員","kind":"確認","question":"出せないということは分かりますけれども、そうでもないというものが幾つかあるということが本日、確認した中でも分かりました。ではなぜその業者が選ばれたのか、選ばれなかったほかの業者との違いというふうなところで、当会派としては採択というふうに申し上げします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"採択というふうに申し上げさせていただきましたが、陳情者の意向を考えるならば、きちんと議会で、少しでも陳情者の意向に沿う形というのが重要かと思いますので、当会派としても趣旨採択と意見を変えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":33282,"voices":147}},{"id":"r05-20230706-19","meetingId":"r05-cm07","date":"2023年7月6日","dateIso":"2023-07-06","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時４５分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"避難計画のところで伺いたいのですけれども、確認なのですが、そこを伺いたいと思います。いろいろなことを広げていくということが、実際に機能するものになっていくと思うのですけれども、そこを伺いたいと思います。","respondent":"平原防災課長、菅野高齢者福祉課長","answer":"冒頭ご説明させていただきましたとおり、お店の商品がもうない、物の入手が極めて重要になってまいります。そういった点で、当然物資の支援対象ということで私どもは考えてありますので… 福祉避難所とは、区民避難所で他の避難者と共に生活を送ることが困難で、あらかじめ指定した避難行動要支援者を受け入れる、現在４３施設あります。それを踏まえて、各施設と協定の締結等をするなど、今後の整備に向けて…","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこだけ確認させてほしいと求めました。より実践的な、実効性ある避難所運営訓練をしていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"令和２年度から福祉部では、災害時検討というのを進めておりまして、現地といろいろやり取りをしている最中です。考え方としては、それぞれの職員が行って確認をしているという、その作業をしている最中というところで補足します。 それに合わせまして、在宅避難となった時の支援につきましても、しっかりと周知してまいりたいと考えています。そちらで前年度の取組の紹介でありますとか、当年度の今後の予定でありますとか…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"全ての避難所に既に配備できるようになっているのか確認させていただきたいのと、この間も災害が起きた時、いかがでしょうか。区内にあるのか、それともないのかも含めて伺いたいと思いますが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"想定すると屋外での避難とか、そういう想定になるのかなと思うのですけれど、現在テントに関しては特に備蓄は考えていないところです。そうすることで２日目、３日目以降の都からの物資を早急に、協議を進めているところです。 すみません、１点、物資の分担につきまして、東京都からのところを補足させていただければと思います。大きくは２日目、それぞれ分散と集中の考え方によって物資を管理していますが、いろいろなところから運んでくることになっておりま…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"この道路が使えないとか、そういったことがあると思いますので、輸送できるような仕組みをぜひ整えていただきたいというふうに思います。最初から使っていくような形になっているのかどうかということを確認させていただきたいのと、各家庭のプライバシーも守られ、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"屋根つきのものですと、テントというイメージに近いのかなと思っています。そういった形で、プライバシーを守れるような間仕切りを備蓄しています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者のところは３００件……、障害別には、どの障害で何件来ているのかというところも伺いたいと思います。これは地域の方との連携を強めていくということだと思うのですけれども、これはどのくらい行われているのか、伺いたいと思います。","respondent":"松山障害者支援課長、平原防災課長","answer":"私からは、障害者の方の避難行動要支援者の個別計画の進捗状況について、ご説明申し上げます。今年度につきましては、約３００人の方を対象に作成予定です。 ワークショップは町会ごとに行わせていただいておりますが、令和４年度は６町会につきまして実施させていただきました。これまで… 障害別の内訳についてです。特に障害別の内訳というのはこちらでカウントしておらず、まずは障害福祉サービスをご利用の方を優先的にしようということで…","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"それぞれに合った計画をつくっていっていただきたいと思うのですが、その障害別による課題というのでしょうか、そういうのはあるのでしょうか。もう少し詳しく、どういった形で打合せをしてワークショップを行われているのか、ご説明ほしいと求めました。","respondent":"松山障害者支援課長、平原防災課長","answer":"障害別の課題があるかというご質問についてお答え申し上げます。どういった言葉かけによってどういう支援が必要か、なかなか障害別の課題というのを一般的に示すというところまでは至っておりません。 今年度どういう形の取組をしていくかといった認識合わせから始めさせていただきまして、そういったところを皆さんで話し合っていただく。それを皆さんで話し合う検討会、訓練あるいは確認的なところ…","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"要支援者に対する支援というのは、なかなか大変なところがあると思いますけれども、実際に起こった際に対応できるような、実効性のあるものにしていっていただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういう方がどのように行って、決定をどうするのか、開設はどうするのかということを伺いたいと思います。マスクとか消毒とかは割と有効利用のイメージがつきやすいのですけれども、トイレとかはどうなのか、その辺について説明を求めました。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"災害対策本部といいましょうか、本部長である区長が最終的に判断することになりますが、本部判断ということで開設してまいります。ただ、開設は区の職員が行いますけれども、共助の体制をつくっていくこととしております。 こちら、「優しさを形にプロジェクト」ということで、生理用品については活用を進めているところです。見たり使用してみたりということが大切かと思いますので、そういった効果を見込んで活用してまいりたいと考えております。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"本当にトイレなどはそういう使い方で、これをこのまま有効な備蓄にしないで、使ってみてくださいということをぜひ進めてほしいと求めました。保管のしやすさはどうかとか、これ、それから試しに使うという機会にぜひ使ってほしいということを伝えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"２０１８年の災害対策担当部長からのご答弁では、こちらは５２か所の避難所マニュアルというものは、５２か所全ての避難所マニュアルになるのかといったところで質問します。","respondent":"平原防災課長","answer":"それを基に区民避難所に参加の避難所連絡会議の方々で考えていただいて、もう一度避難所の割りつけなどをやり直していただいたのが、当時の派遣です。その先をどうしていくかというのはまだ、何か方向が決まっているものではございませんが、検討はしていきたいと考えています。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"その後の地域の方々からも、自分たちだけではどうしてもできないと、区に求めるニーズというのがまだまだあるように思われます。２０分とかの動画じゃなくて、これは要望ですが、。","respondent":"平原防災課長","answer":"区の職員で分かること、そういったところについては、しっかりと支援させてまいりたいと思います。そういった動画ですが、共通化できるところなどを考えていきながら、そういった周知方法をまた研究してまいりたいと考えています。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"今年１月のご答弁でいただいていると思いますが、避難所運営マニュアルをつくる上での連絡会議でのコミュニケーションを図っていくといったところでも、今後ともさらに力強く進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"それ以外の方も、なかなか公開されないという課題もあったかと思うのですけれども、今後のこの展開についてお考えをお伺いしたいと思います。それと、障害特性を踏まえた防災マニュアルの作成を、昨年の３定の一般質問で求めさせていただきました。","respondent":"平原防災課長、羽鳥防災体制整備担当課長、松山障害者支援課長","answer":"５２の区民避難所マニュアルですけれども、こういったことの公開は、まず進めてまいりたいと考えています。冒頭ご説明させていただきましたとおり… 特に具体的なお声というのはまだ挙がっていないのですけれど、今後いろいろな声を伺いながら、いろいろな対応をしていきたいと考えております。… 私からは障害特性を踏まえた防災マニュアルの作成について、お答え申し上げます。一体どういうものが実際に…","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"ラップ式ポータブルトイレも各避難所に４台ずつ整備されているということも確認ができました。それぞれ団体に確認していただいているということなのですが、他自治体でも、障害特性に応じたマニュアルが作成されている事例もあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"私から、３ページの避難行動要支援者支援について、幾つか質問させてください。ここに差がある場合はなぜ同意を得られていないのか、同意を得られていない方々に対する今後の対応等について、聞かせてください。","respondent":"平原防災課長","answer":"このようなことを行いますということで同意された場合、例えば平常時から安否確認であるとか、そういったことで進めさせていただいてあります。同意が得られないような場合でも、あくまでも事前の準備ということで、同意を得ていくということで進めているものです。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何かの理由が、そこ以外には出さないということだと思うので、そこの理解というところも進めていただきたいというふうに要望しておきます。その作成をした後の見直しの方法について、お聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"障害の場合、計画を作成するのは、ケアプランを作成する相談支援員がいたします。対応の仕方等も含めてまたきめ細かく、お一人おひとりと相談させていただいて、またバージョンアップしていくというふうな方法をとっております。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうときに、その方たちに対応できる方、看護等に対応できるような方もそこに派遣される計画というのは、お持ちなのでしょうか。いろいろ防災課でも、かなり煮詰められていると思うのですが、まずそこを１点、説明を求めました。","respondent":"平原防災課長","answer":"あるいは状況が許せばなのですけれども、介護タクシー等々が使えるような状況であれば、そういったものも当然活用していくことを考えてあります。避難所では何なのか、基本的にはそういった動きの中で看護師の派遣等々、決まっていくような形になってあります。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"云々書いてありますけれど、実際に現実論は難しいのではないかと思うのですが、どうなのでしょうか。東京都の統一見解は３日間、皆さん、品川区は独自に１週間持ってくださいよと公表してはいけないのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった形で、輸送がとどまることがないような体制は、とっているものというふうに認識しています。なるべく１週間分確保するということで、「１週間分」を赤文字で強調させていただいて、周知させていただいているところです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"というのは、今、課長がおっしゃったとおり、緊急輸送道路あります、でも、それ、誰が仕切るのですか。もう一旦止まってしまったら、緊急輸送道路など使えないのではないか尋ねました。","respondent":"平原防災課長","answer":"今ではなるべく１週間以上という言い方をしていますが、今後言い方についてはまた、いろいろ工夫してまいりたいと考えています。普段のものがそのまま災害時にも転用できるのだということを、こちらをしっかりと今後周知してまいりたいと考えています。","id":"exchange-019"},{"speaker":"こしば委員","kind":"質問","question":"例えば、毎年１２月に避難所訓練を行います。その辺、説明を求めました。","respondent":"平原防災課長","answer":"我がまちの安全を確保する一番最初のところだというような認識を、そういったところの認識が、啓発のための動画を併せて用意させていただきました。こういう避難施設の考え方なども含んでおりますが、そういったところも、防災課のほうからも周知してまいりたいと考えています。","id":"exchange-020"},{"speaker":"こしば委員","kind":"質問","question":"では、そうしますと、まず最初に避難する場所は、一時集合場所という認識でよろしいか尋ねました。","respondent":"平原防災課長","answer":"一時集合場所というふうに考えてありますけれど、安全を確保できる場所というのが一番最初に避難いただくということで考えていただければと思います。一時集合場所だというふうに考えてありますので、まずは安全確保、こういったことが重要だというふうに考えてあります。","id":"exchange-021"},{"speaker":"こしば委員","kind":"質問","question":"Ｂ学校はまだ２００人、３００人ぐらい空きがあると、Ｂ学校のほうに行ってもらうような。補完避難場所として捉えているのかどうか、その辺が少し分かりづらいと思ったので、説明をお願いします。","respondent":"平原防災課長","answer":"といいますのは、順次そこを使わせていただくというような考え方で、義務教育学校の一部はそういう指定をさせていただいているところです。そういったところは順次、そういう施設が使えるかどうかの確認をした後に、開設していくということを考えてあります。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、既に何年かたっておりますし、さらに更新して、それをもう少しみんなが使えるように公表するお考えは、あるのかないのか伺いたいのと。そういうお声が出ているということなので、ぜひ検討していただきたいのですが、その辺についてお考えを伺いたいと思います。","respondent":"平原防災課長","answer":"なかなか全てに対応というのが、やはり訓練の支援といいましても、なかなか対応できなかったところもありますけれども。そういったところで、またお声をいただければ、そういったところの広げ方みたいなものも工夫してまいりたいと考えています。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"そして広めていただきたいのと、地域の方たちが取り組めるような支援の内容まで描かれていると、大変いいかなというふうに思います。今後とも、こういうものはどんどん広げていっていただきたいと思っての意見と質問です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"澤田委員","kind":"質問","question":"１点目は避難施設の備蓄品についてなのですが、小学校以外のいろいろな施設もあると思うのですが、用意されているのでしょうか。そこで質問なのですが、各施設の混雑状況などは、ココシル品川で分かるようになっているのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"３つ目です。ただ、各避難所の混雑状況といったことが把握できるような機能までは、今のところ搭載していないという状況です。","id":"exchange-025"},{"speaker":"澤田委員","kind":"質問・要望","question":"もう１点、より利用者にとって便利なのではないかと思うので、そちらも検討していただけると大変ありがたいです。以上、全て要望になってしまうのですが、ご検討のほどよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"マニュアル自体は５２か所全て整備されているのは分かりましたが、しっかりとマニュアルに記載をしている避難所の数を、把握していれば説明を求めました。","respondent":"平原防災課長","answer":"５２のマニュアルのうち、子どもスペース等々の数ですが、大変申し訳ございません、今、この段階では把握してございません。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"優先度を上げるべきだというようなこととか、これについていろいろと求めた質問の中で、これをしっかりと進めてほしいと求めました。国の場でもそう求めさせていただきましたけれども、区でもしっかり確認してもらった上で、現段階のご答弁をほしいと求めました。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"前回アドバイザーを入れて避難所マニュアルを検討した際に、例えば、全てに行き渡らなかったというような状況もあります。併せてございました子どもに対応するようなスタッフにつきましても… いろいろな選択肢があると思いますので、そういったところを総合的に考えながら、進めていきたいと考えております。電柱に巻き看板ということで設置させていただいているのは、広域避難場所を案内させていただいて…","id":"exchange-028"},{"speaker":"つる委員","kind":"意見","question":"ＱＲコードだらけになってしまってもよくないのですけれど、そういう設置箇所も工夫がいろいろできるのかなと思いますので、ぜひ今後検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"せりざわ委員","kind":"提案","question":"以前これも議会で提案しましたけれど無電柱化していくに当たって、地上変圧器と言うのですか、いろいろ書いてあるのですけれど。例えばトランスに関しては道路課が許可してくれないとかいう話なのか、どういう状況なのかというのを、防災課のほうの感覚を少し教えてほしいですとの意見を述べました。","respondent":"羽鳥防災体制整備担当課長","answer":"避難看板の中に周辺の地図も載せる予定ですので、通りかかったときにふっと見ていただく、そういった形での効果も見込んで設置しています。今後も各課と連携をしながら、様々な形で防災情報を発信できるように、お伝えできるように、整備してまいりたいと考えております。","id":"exchange-030"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"日常と災害時の非日常の境界線を少しずつ近づけていくというのですか、そういった取組をぜひ、防災の皆さんで取り組んでいただければ。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"西村委員","kind":"質問・要望","question":"もう１点、同じように授乳スペースに関しても設置予定があるのか、改めて全避難所をご確認いただきたいと考えています。これは要望ですけれども、何かございましたらお答えください。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"私からは、１つ目の備蓄についてお答えします。ここの倉庫の備蓄されている食品は何年後に有効活用が必要だということが、システムと担当者のほうで分かりやすいような管理をしております。 授乳スペースのお話をいただきました。こちらにつきましては前回の検討の際に、授乳スペースあるいは着替え、そういったところに使っていただくような形で運用しています。","id":"exchange-032"},{"speaker":"西村委員","kind":"意見","question":"食生活面でのニーズも、今後さらにシステムで管理していただいているのであれば、町ベースでできていくのではないかなと思います。準備していた、災害が来たと区民の方々が思えるように、引き続き体制の整備をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"鈴木副委員長","kind":"確認","question":"愛の手帳１から２度とかいうのがありますけれど、この６項目が要配慮者ということでの名簿ということで、確認させていただいていいでしょうか。それから、同意をされた５,３４６名なのですけれども、高齢とか障害とかの数がそれぞれ分かったら教えていただけたらと思います。","respondent":"平原防災課長","answer":"名簿という段階ではしているのですけれど、ご本人の確認という点では年１度の更新ということでさせていただいているところです。身体障害をお持ちの方が２,５４０人、その方が２３５人、愛の手帳の方が１９８人という内訳です。","id":"exchange-034"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"それまでも５,７００でしたか、この同意の数字と計画の数字というのがどういうふうに関係しているのか、伺いたいと思います。令和３年に災害対策基本法が改正されて、何というのですか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"今年度新たに３,０００件の原案をさらに作成する予定で、この原案のうち、今年度も５,０００件の移行を予定している次第となっております。４３か所の福祉避難所のうち… あるいは今進めております地域防災計画の修正、現在検討といいましょうか、準備に入っているところです。個別避難計画につきましては避難行動要支援者全体に対してつくっていくことになりますので…","id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"確認","question":"そしてこの避難所に対してはこういう方が、何というのですか、そういう方向で区としても進めているということでいいのでしょうか。何人分くらいを指定していくということで、区としては考えられているのか、その点についても伺いたいと思います。","respondent":"平原防災課長","answer":"もう１点ですが、ご協力いただくというような形で進めさせていただきまして、現在増加させていただいているところです。一般の受入れということではございませんので、広く公表というよりは、そこが福祉避難所ですよという形での公示ということで考えているところです。","id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"４３か所ということですけれども、そこで受け入れる対象者も特定するということで、そういうことで決まっていると考えていいのでしょうか。逆に、そういうところを区民に対しても周知していくのが必要なのではないかと思うのですけれど、その点はいかがか尋ねました。","respondent":"菅野高齢者福祉課長、平原防災課長","answer":"私のほうからは、福祉避難所に行かれる方の状態像というか対象者について、ご説明をします。地域の支援者の方ともすり合わせをしながら、本計画への移行を進めていくというのが現在のところです。 ただ一方で、直接避難という言葉が、福祉避難所とはこういうものですよというのはしっかりと周知させていただければと思ってあります。例えば介護度の低い方は、区民避難所の要配慮者スペースといったところも活用しながら…","id":"exchange-037"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"その検討の組織というのですか、当事者の意見を伺うような場所というのは、どういう形でされているのか。検討会の中にも当事者が入るのが一番いいかなと思うのですけれど、その点はどう考えられているのかについても伺いたいと思います。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"避難の支援者や避難方法、避難先の選定や被災後の生活支援など、調整しなければならない課題がたくさんあると認識しているところです。ワークショップなどといったところで、実施した町会からは… 庁内では、福祉部、防災課を含めた検討会というのは令和２年度から行っております。視覚障害者の方への支援というのはどうしたらいいかといったような、お互いに少しずつそういった検討会を通じて理解を得ていくというような作業を。","id":"exchange-038"},{"speaker":"鈴木副委員長","kind":"質問","question":"するところもあるというふうに伺ったのですけれど、そういう考え方で２段階の計画にしていくのか、その点も伺いたいと思います。それから、その計画をつくるに当たって、どれぐらい報酬として出されるのか、その点についても伺います。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"私からは、個別支援計画の作成過程についてのご説明をします。その後、当該対象者へ提案して、避難行動が必要な場合は支援者の調整等を行いまして本計画に移行するという、２段階の形をとっているところです。 １０人弱ぐらいの方はなかなか同意が、残念ながら得られなかったというところがありますけれども、そちらは計画をつくるところまでは行っております。報酬につきましては、高齢者と一緒の金額設定となっております。","id":"exchange-039"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"１回の計画で７,０００円というのがモデルで区のほうでは書かれていましたけれども、ご検討いただけたらと要望させてほしいと求めました。どちらにしても、これからも当事者の意見も聞きながら計画を立てて、そして支援をしていただけるようにということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":53381,"voices":104}},{"id":"r05-20230710-10","meetingId":"r05-cm07","date":"2023年7月10日","dateIso":"2023-07-10","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"委員会審査での写真撮影についての検討の要望なのですけれども、傍聴人から写真撮影を求められて、その可否を議論する場面があったと伺っています。私たちは見直す必要があると思いますので、ぜひこの議会運営委員会で議論いただきたいと思うのですけども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"せりざわ委員","kind":"質問","question":"それも以前、私もいろいろ教えていただいて、そうなのだなと初めて理解したところもあるのですけれども。各委員会でがちゃがちゃするというよりは、区議会全体でやったほうがいいかなというお話は、私も賛同しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは話し合う中で、その課題をどうするかという話合いもあると思いますし、それは大事な視点かなと思っています。それとあと、預からせていただきたいと、先ほど委員長におっしゃっていただいたのは、具体的にはどういう感じで進めていかれるのかだけお伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":8191,"voices":39}},{"id":"r05-20230724-6","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"区民委員会","time":"午後 １時００分～午後 １時４７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"令和５年度八潮みらい懇談会","agenda":"令和５年度八潮みらい懇談会","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"八潮地区の地元の議員とちょっと話をしてきたのですけれども、確認をさせてください。どのような方たちが、いわゆる懇談のメンバーとして何人ぐらいいらっしゃるのか、その背景も含めて説明を求めました。","respondent":"中西八潮まちづくり担当課長","answer":"それから保育園や八潮学園の施設長、それから明晴学園にも入っていただいていたり、あとはピッコロの施設長にもご参加を賜っているところです。人数としましては、２０名程度というところでやっているところです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"ＵＲもある八潮地区の中で、やはり比較的若い層の方たちが懇談会に参加をしていく必要があるのではないかというのが地元の議員の意見でした。その辺りの、そのような方たちの参加をぜひ促してほしいということが地元の議員の意見でしたが、その辺りをぜひ説明を求めました。","respondent":"中西八潮まちづくり担当課長","answer":"各団体様、実際に八潮みらい懇談会の中でも、少し若い世代の方に参加をいただきたいねという話は出ております。今５０代の方がなっていらっしゃいますので、そういった方々にも参加いただけるような手だてを考えてまいりたいというふうに考えております。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"不審者の情報が複数というように出ているのだけれども、今八潮の地域の中の防犯カメラの状況というのはどうなっているのでしょうか。お伺いします。","respondent":"中西八潮まちづくり担当課長","answer":"団地内、その建物の中に関しましては、ご自分の管理組合の中で設置をされているというように聞いてあります。そういったところは防犯カメラがついていない部分が少しありますので、そこは課題だというようなところで、地域でもお話が出ているところです。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"すると１０ポイントぐらい高いから、施策の中で人口動態が大事だから、その辺についていかがですかということが１点です。だから、その辺についてもいかがか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"１点目の高齢化率が進んでいるという中での取組ですが、いかに若い世代の方々、そういったところは今検討をしています。まず地域としてできるか、それから、私どもとしてどういったフォローができるかというところは考えてまいりたいと思います。","id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認なのですけれども、八潮地区に関しては八潮まちづくり担当課長のところでやっていくのか。八潮地区についてはどのように考えているかということを、やはり生活安全担当課長から答弁していただければ幸いなのですけれども、いかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"設置場所等につきましては、そちらでアングルと位置関係につきましては適正な場所を検討してくださっているということになります。場所については、そういったところは捜査機関等の防犯も併せて有効な場所に設置、今後もつけていただけると考えております。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"もちろん地域も含めてですけれども、防犯カメラの設置を積極的にやっていただきたいと考えています。その辺についてはいかがか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"防犯カメラをつける際の補助金の申請など、そういったところで窓口もやっておりますので、生活安全担当と連携をしまして進めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"横山委員","kind":"質問","question":"３点お伺いいたします。最近はどういった傾向になっているのか、先ほどほかの委員の質問の中で、現在の状況を説明を求めました。","respondent":"中西八潮まちづくり担当課長","answer":"申し訳ございません、地域の方からは、その辺りをどのように連携していくかというところも検討課題かなとは思っております。補足になりますが、八潮地区には多種多様な人種の方がいらっしゃるということを少しずつ認知していくような取組を今進めているところです。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"３０年後の地域の未来をより具体的に地域の皆様にイメージしていただけるような、そうした素地をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問","question":"不審者ですから子どもたちの安全だけではないと思うのですけれども、品川区はまもるっちの協力者登録というものがあると思うのです。例えばまずメンバー２０名の方に登録をご協力いただいたり、またそこから自治会、そのような取組はされていらっしゃいますか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"まずはＰＴＡのほうでもう１回見回りを始めようかですとか、それを進めつつ、まもるっちの取扱い等も含めて検討してまいりたいと考えています。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"行っていないですか。行っていないかどうか、それを。","respondent":"中西八潮まちづくり担当課長","answer":"たしかこの委員会の中で高島平団地のお話を少し出させていただいたという経緯はあります。視察に行ったのは光が丘団地だけです。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"というのは、全然違うではないですか。どのようなことを視察したいのかとか、どういう目的があってということを具体的に教えていただければ幸いです。","respondent":"中西八潮まちづくり担当課長","answer":"昭和５８年に全く同じタイミングで都営住宅、全く同じような成り立ちでできた団地が光が丘だったというところで、そちらのほうに視察に行ったです。今後に関しましても、どのような地域活動がされているかといったところも含めて、視察先は選定していきたいなと考えています。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、あえて言いますけれども、ハード面は物すごく大事です。ソフト面も大事だけれども、ハード面は、私は物すごく大事だと考えていますので、その辺も含めてしっかり視察してきてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"せらく委員","kind":"質問・要望","question":"今視察のお話が出ていましたけれども、八潮団地と似た成り立ちの光が丘団地に行かれたということで、逆に八潮団地に視察に来られた団体などがもしあったら、八潮地区のどのようなところを見られたとか、八潮地区のアピールポイントという部分もあれば教えていただきたいです。","respondent":"中西八潮まちづくり担当課長","answer":"八潮地区に視察に来られた団体というのは、すみません、ちょっと私のほうでは把握はしておりません。いわゆる歩車分離というところで、一つ八潮地区の特色としてあるということは、お話としてよく聞く話です。","id":"exchange-013"}]},{"id":"topic-02","title":"しながわシティラン実行委員会の設置","agenda":"しながわシティラン実行委員会の設置","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"どうなのかなというところと、この辺ぐらいまでには決めないといけないと、何か一定の目安などがあれば教えてほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"コースについては、まず実行委員会を年２回開く想定をしておりまして、順調にいけば１２月頃を予定しております。細かい調整はこの後でも問題ないかと思っているのですが、大枠はそこまでに決めたいと考えております。","id":"exchange-014"},{"speaker":"えのした委員","kind":"意見","question":"年内、１２月までということで、一つ安心材料になりましたけれども、これが全く逆のコースとなると、走る地域のコースの環境等、安全が一番だとは思いますけれども、やはり品川区の魅力、走りやすさ、区民の方が参加しやすいコースをぜひ熟考してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"ほかの自治体マラソンの場合には、営業時間にあまりかからないようなところにしたりとか、３月ですから気温の問題はそれほどないのだと思うのですが。もしかしたらもうされているのかもしれませんが、私はまだ伺っていないので、その辺りのことを教えていただける範囲で説明を求めました。","respondent":"三井スポーツ推進課長","answer":"大井ふ頭中央海浜公園が入っておりますので、オリンピックレガシーなどを含めて、総合的に考えていきたいと考えています。もう一つ、今回区議会事務局を通して推薦の依頼をかけさせていただきましたので、議会運営委員会等でまたお知らせがあるかと思います。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆる、やはり旧東海道を走るということはイコール商店街を走るということになりますけれども、その辺りもお考えになっているのか教えてください。商店街のことを説明を求めました。","respondent":"三井スポーツ推進課長","answer":"もし商店街を走れないという状態になったとしても、商店街連合会と連携して、何かしらのイベント等も考えていきたいなということは考えております。その辺の具体的な内容は実行委員会でこれから検討するかと思いますが…","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"お伺いいたします。その際にどういったお話があったのかというところと、ホームページに載っているのですが、その辺りの考え方を説明を求めました。","respondent":"三井スポーツ推進課長","answer":"アイデアソンは３月に実施させていただいて、コースについてはその辺の話を受けながら準備委員会のほうでも話をしまして、実行委員会でもまた検討はしていきたいと思っています。","id":"exchange-018"},{"speaker":"横山委員","kind":"確認","question":"案という形なのでしょうか。その辺りを確認させてください。","respondent":"三井スポーツ推進課長","answer":"ボランティア、応援といった様々な形で参加することで、区民のシビックプライドの醸成を図るということで決めております。それを今度は実行委員会にまた案として出した段階で検討していくというような形になります。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"どういったところを魅力的に見せていくのかという発信の部分が大切になってくるのですが、理念といいますか、そうしたよい機会になるかと思います。健康づくりというか、総合的にその理念をどういった形で実現していくのかというところを実行委員会のほうではお話しいただきたいと期待しております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"山本委員","kind":"確認","question":"どうしても確認をしたいというところでいうと、やはり品川区のシティランということでいえば、品川区全域を走れるに越したことはないのかなと。この海側になったということで、全域を含めたところはどのように難しかったのかなということ、検討経緯を聞かせていただけないか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今回、大井、荏原、品川、大崎など、幅広く走るルートを検討してまいりました。商店街についても幾つか、その辺も検討はしたのですけれども、安全性の問題からなかなか難しいということで断念せざるを得なかったという状況です。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"そういった意味でも、先の話になるかもしれませんが、検討いただきたいと思った次第です。ぜひ多くの区民の皆さんを巻き込んで、よいイベントにしていただきたいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16867,"voices":66}},{"id":"r05-20230724-7","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"厚生委員会","time":"午後 １時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"令和５年陳情第２３号、利用できない区民のために、障害者施設の迅速な整備を求める陳情","agenda":"令和５年陳情第２３号、利用できない区民のために、障害者施設の迅速な整備を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"利用状況が３年前のものですので、現在の定員における稼働率等を教えていただければ、助かります。","respondent":"松山障害者支援課長","answer":"直近の障害児者総合支援施設の稼働率につきまして、お答え申し上げます。生活介護のハード上の定員における稼働率は６０％で、就労継続支援Ｂ型の稼働率は２０％と、どちらも順調に伸びております。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"３年前に比べて、こちらの就労継続支援Ｂ型が低い理由は、希望がないのでしょうか。どのような感じで、低い数字なのか尋ねました。","respondent":"松山障害者支援課長","answer":"就労支援センターをご希望されている方が多く、就労継続支援Ｂ型は、ご希望される方が少なくはなってきているという実態があります。障害児者総合支援施設をご希望された特別支援学校の令和５年度の卒業生ですと、就労継続支援Ｂ型については、通所をされております。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何点か質問をさせてほしいと求めました。今後の障害者の増加をどのぐらいに見込んでいるのか、また、その増加に対しての具体的な計画等があれば説明を求めました。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"令和４年１０月１日から、障害児者総合支援施設のショートステイの定員を６人から１２人に増やして、対応をしております。区の認識といたしましても、障害児者総合支援施設に多くの方にご利用いただきたく、考えております。 このような整備金補助の周知強化を努めていくことで、区としては、民間整備というところにも努めてまいりたいとは思っております。１２月に、各年度における障害福祉サービスの見込量を設定しまして…","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"２点目が、既存の施設のバリアフリーの状況についても、この陳情で書かれているので、その点についても、教えてほしいと求めました。そのできない問題点についても、聞かせてほしいと求めました。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"手すりの設置、スロープの設置、適切に対応をしています。サービスが継続できるということが一番として、区としては考えて、検討していかなければならないです。 大体３０年、建て替えの周期については、６０年という目安となっております。建物における長寿命化を図り、安全性を確保しながら、維持していくという考えに至ります。","id":"exchange-004"},{"speaker":"ひがし委員","kind":"質問・要望","question":"定期的に、バリアフリーなどの意見が出たときには、定期的に改修できる範囲で行っているということでよろしいですか。利用者が、利用しやすい施設が出来上がってくるのではないかと思いますので、その点については要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"もっとこのような施設を、このように造っていきたいという方針があるのか、その点を伺いたいと思います。今、計画されているもので、区として整備する、そのような大きな施設はあるのか、ないのかについて、まず伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"第６期品川区障害福祉計画の中でも、親亡き後を見据えた居住支援のための機能の充実化が求められておりまして、区としても認識しております。先ほどご説明させていただいたとおり、児童発達支援センター、就労継続支援Ｂ型施設。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点をどう考えられているのかということも伺いたいと思います。大規模改修の計画は、どのように考えられているのか、その点についても伺います。","respondent":"川崎障害者施策推進課長","answer":"先ほど御説明したように、建て替えの周期は６０年という目安で、あと１４年とはなります。適切な修繕を行いながら、安全性を確保しながら、維持していくというところになります。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"需要を、「今後利用したい」ということで答えているわけですから、このようなことも踏まえた計画をつくっていくことが必要なのではないかと思います。その点は、このアンケートをどのように計画に反映させていくのか、それはどう考えられているのかについても伺いたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"ですので、今後、土地をお持ちのオーナーに対しての働きかけも必要になってくるとは考えています。他区でも、今までの周知計画プラス新たなグループホーム整備促進の動きを検討していって… この方は地域移行ということで対応できるのか、どのような支援ができるのかということを、相談支援事務所を通じて。地域自立支援協議会でも報告させていただき、その数字についても、計画に反映してまいりたいと考えております。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今度の第７期と第３期の計画の中の見込みの数字は分かりますけれども、この計画に反映されないではないですか。どのように考え、どのように立てていくのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"令和６年度の４月１日に開設予定の出石つばさの家は、重い方を中心に対象の方として、整備していくところになります。品川区総合実施計画の中におきまして、予定はしておりますので、総合実施計画上で示している数値ではありますけれども。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"そこのところは、せっかくアンケートも取っているわけですから、その点を伺いたいと思います。どのようにその計画の中に反映されるのか、指針との関係では、どうなのかということも伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"相談対応であるとか、各課等と連携して、情報共有に努めてまいりたいと考えております。委員長、副委員長とともに、指針を含めて、また、区の進められる施策とともに、検討しながら、この指針の部分は、検討を重ねてまいりたいと思います。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"あれだけ土地を買収してやっていくわけですから、区が姿勢を示して、やっていただきたいと私は思います。アップした施設を整備していくということが求められるのではないかと思うのですけれども、区としては、その点はどう考えるのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"先ほども御説明したとおり、各年度における障害福祉サービスの見込みを設定して、その確保に十分努めていきたい。そこは、区としても、確実に努めていきたいと考えています。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"高次脳機能障害の方に対してのサービスの確保だったり、そのような施設的な部分も含めての充実というところを、どう考えられているか。その点も伺います。","respondent":"川崎障害者施策推進課長","answer":"今回、第７期の障害福祉計画の策定委員の中に、公募区民の中に、発達障害の方、高次脳機能障害の方、当事者２名がおります。その当事者の方のご意見も踏まえまして、今後のサービスの見込量確保は、充実させていきたいと考えております。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"当たり前に生活できるということが求められて、新たに計画を立てるわけですから、ぜひ反映してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点確認なのですけれども、それを前提に、我々も計画を立てるということでよろしいでしょうか。区の考え方を聞かせてください。","respondent":"川崎障害者施策推進課長","answer":"はい、そのとおりです。自分らしく暮らしていける品川」を目指して、区民の幸せ、ウェルビーイングを目指す施策づくりに取り組んでいます。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"もう１点、質問です。お考えとして、これから障害者の推移といいますか、どのようになっていくとうような見込みをしていらっしゃいますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"障害者のどのような見込みということは、種別などということでしょうか。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"増減で、今後、増える傾向などといった推移の見込みをお伺いできればと思います。","respondent":"川崎障害者施策推進課長","answer":"令和４年度は、令和３年度よりも、微減という形で減っています。ただ、精神障害者保健福祉手帳所持者数も増加しておりますので、全体的には障害者の数は増加しているとは認識はしております。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情者の陳情の趣旨について、お伺いをしたいと思います。障害者施設の迅速な整備を求めておられるのですけれども、今現在、現実問題としての可能性があるのかということをお聞きしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"障害者グループホームが８施設増加、５９人の定員増につながったということで、促進はされていると思います。引き続きグループホームの補助金の周知強化にも努め、区有地、また民有地などの洗い出しも検討をしてまいりたいと考えております。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"といいますと、迅速な整備を行っている。区としては、そのようなご認識だということでよろしいのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"グループホーム以外でも、障害児の部分でも、放課後等デイサービスも、整備は促進されております。障害者、障害児ともに、必要なところの整備は、確実に、着実に進めていると認識しております。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"森澤区長としても、武蔵小山のところで、ウェルビーイングをというのでしょうか。記者会見でしたでしょうか、どのような施設なのかを具体的にご説明いただけたら、ありがたいです。","respondent":"東野福祉計画課長","answer":"事業者との連携を進めていきましょうということで、まずは高齢者福祉施設での検討を進めていくもので、ほかの施設へも考えていきたいです。ですから、小山台住宅等跡地のところにできる障害者施設については、対象とはなっていないものです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"いま一つイメージが、持てないのですけれども、どのようなことが変わるのでしょうか。変わる中身、充実される中身、そこら辺のところを、もう少しイメージを持っているような形で、ご説明いただけないか尋ねました。","respondent":"東野福祉計画課長","answer":"初めて行うような施策になりますので、千葉大学の大学院の准教授から、いろいろな知見をいただいた上で、今後、考えていくことになろうかと思います。施設造りを進めていきましょうという段階で、例えばアンケートを取ったりなどといったことで…","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、建物の建て方というか、建築の在り方のところでのウェルビーイングと、そのようなところなのでしょうか。それが、障害者のほうまでは行かないで、まだ研究されていることが、高齢者からということなのか。","respondent":"東野福祉計画課長","answer":"高齢者施設からというところになります。まずは、ハード面で、どのようなことができるかというところでの考え方をまとめていくというようなものです。","id":"exchange-021"},{"speaker":"こしば副委員長","kind":"質問","question":"各委員から質疑応答がありまして、この陳情の理由と書かれていること全てが、必ずしも今の状況に沿っているとは言い難い面もあるかと感じました。それで、この陳情の理由については、今の状況を必ずしも反映していないということで、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"区民のための施設をどうしたらいいのかということを、質疑の中で、私は確認をさせていただきました。ですので、現状、そのような取組が確認できましたので、この陳情に対しては不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"ひがし委員","kind":"質問・要望","question":"民間事業者への働きかけを行って、待機者が希望する施設を利用できるように取り組んでほしいと求めました。入所しながらの工事が難しいという点も確認できましたので、また、利用者が安心して利用できる施設になるように取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはり、施設整備という点では、２３区の中でも、品川区は、まだまだ整備率は低い状態です。ぜひ、施設の整備は、早急に進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"本日結論出すで、不採択でお願いいたします。この陳情書の趣旨の理由に対して努力されているということで、本日結論を出すで、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"おぎの委員","kind":"確認","question":"実際、今、施設がどのような状況になっているのかを、私たち議員も、しっかりとこの目で確認をしたほうがいいと思います。ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"お話を伺っていて、品川区でも非常に取組をされているということは、十分理解させていただきました。ご家族の方に、より寄り添った政策を行っていただきたいというようなことを感じましたので、採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"これ以上増やすということは、もう難しいという感じか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"兵庫県で医療支援型のグループホームになっているというものがあったのですけれども、そのようなものが入る余地は、もう全くないですか。なかったら、なかったで、私は、期日までに出さなかったので、もう諦めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今回、初めて厚生委員になられたの方も結構いらっしゃるではないですか。区内施設も視察するということも、ゆとりがあるところで、計画に組んでいただけたらいいのではないかという希望です。","respondent":"松永委員長","answer":"ご意見として頂戴させていただいて、検討します。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":19515,"voices":85}}]);
